TEST(LLVMCPointerAddresses, OverLimitCallOperandDoesNotBlockInlining) {
  class FieldDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140001000)
        return std::nullopt;
      auto Record = NdType::makeNamedRecord("CRecord", 32);
      Record->FieldDisplayNames = {"values_"};
      Record->FieldDisplayOffsets = {8};
      Record->FieldDisplayTypes = {NdType::makeInt(8, true)};
      FunctionSym FS;
      FS.Name = "fill_values";
      FS.Addr = Addr;
      FS.Params = {{"this", NdType::makePtr(Record)}};
      FS.ReturnType = NdType::makeVoid();
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-inline-over-limit", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::getUnqual(I8);
  llvm::FunctionType *LenTy = llvm::FunctionType::get(I64, {Ptr}, false);
  llvm::Function *GetLength = llvm::Function::Create(
      LenTy, llvm::GlobalValue::ExternalLinkage, "GetLength", Module);
  llvm::FunctionType *EmptyTy =
      llvm::FunctionType::get(I64, {Ptr, I64, I64, I64, I64}, false);
  llvm::Function *IsEmpty = llvm::Function::Create(
      EmptyTy, llvm::GlobalValue::ExternalLinkage, "IsEmpty", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "fill_values", Module);
  rewrite_source::setOriginalVA(*Function, 0x140001000);
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  llvm::Value *Home = Builder.CreateAlloca(I64, nullptr, "rax");
  llvm::Value *Clobber = Builder.CreateAlloca(I64, nullptr, "rdx");
  llvm::Value *Len =
      Builder.CreateCall(GetLength, {Function->getArg(0)}, "len");
  Builder.CreateStore(Len, Home);
  Builder.CreateStore(Builder.CreateFreeze(llvm::UndefValue::get(I64)),
                      Clobber);
  llvm::Value *Loaded = Builder.CreateLoad(I64, Home);
  llvm::Value *Add = Builder.CreateAdd(
      Builder.CreatePtrToInt(Function->getArg(0), I64),
      llvm::ConstantInt::get(I64, 8));
  Builder.CreateStore(Loaded, Builder.CreateIntToPtr(Add, Ptr));
  Builder.CreateCall(IsEmpty, {Function->getArg(0), Loaded, Loaded, Loaded,
                               Loaded});
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  Options.EmitIncludes = false;
  ASSERT_TRUE(
      LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr, Function));
  OS.flush();
  EXPECT_NE(Source.find("this->values_ = GetLength("), std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("len0"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("GetLength("), Source.rfind("GetLength(")) << Source;
}

TEST(LLVMCPointerAddresses, UnprintedCursorCopyDoesNotBlockSingleUseCall) {
  class CursorDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140001000)
        return std::nullopt;
      auto Node = NdType::makeNamedRecord("CNode", 16);
      auto Record = NdType::makeNamedRecord("CRecord", 16);
      Record->FieldDisplayNames = {"m_node"};
      Record->FieldDisplayOffsets = {8};
      Record->FieldDisplayTypes = {NdType::makePtr(Node)};
      FunctionSym FS;
      FS.Name = "check_empty";
      FS.Addr = Addr;
      FS.Params = {{"this", NdType::makePtr(Record)}};
      FS.ReturnType = NdType::makeVoid();
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-cursor-copy", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *EmptyTy = llvm::FunctionType::get(I64, {Ptr}, false);
  llvm::Function *Empty = llvm::Function::Create(
      EmptyTy, llvm::GlobalValue::ExternalLinkage, "IsEmptyPayload", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "check_empty", Module);
  rewrite_source::setOriginalVA(*Function, 0x140001000);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Then = llvm::BasicBlock::Create(Context, "then", Function);
  llvm::BasicBlock *Else = llvm::BasicBlock::Create(Context, "else", Function);
  llvm::IRBuilder<> Builder(Entry);
  llvm::Value *Home = Builder.CreateAlloca(I64, nullptr, "home");
  llvm::Value *Dead = Builder.CreateAlloca(I64, nullptr, "dead_copy");
  llvm::Value *Base = Builder.CreatePtrToInt(Function->getArg(0), I64);
  llvm::Value *FieldPtr = Builder.CreateIntToPtr(
      Builder.CreateAdd(Base, llvm::ConstantInt::get(I64, 8)), Ptr);
  Builder.CreateStore(Builder.CreateLoad(I64, FieldPtr), Dead);
  llvm::Value *Flag =
      Builder.CreateCall(Empty, {Function->getArg(0)}, "empty_call");
  Builder.CreateStore(Flag, Home);
  llvm::Value *Loaded = Builder.CreateLoad(I64, Home);
  Builder.CreateStore(Loaded, Dead);
  Builder.CreateCondBr(
      Builder.CreateICmpEQ(Loaded, llvm::ConstantInt::get(I64, 0)), Then,
      Else);
  Builder.SetInsertPoint(Then);
  Builder.CreateRetVoid();
  Builder.SetInsertPoint(Else);
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  Options.EmitIncludes = false;
  ASSERT_TRUE(
      LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr, Function));
  OS.flush();
  const auto BodyAt = Source.find("check_empty(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto IfAt = Source.find("if (!(IsEmptyPayload(", BodyAt);
  EXPECT_NE(IfAt, std::string::npos) << Source;
  EXPECT_EQ(Source.find("= IsEmptyPayload("), std::string::npos) << Source;
  const auto CallAt = Source.find("IsEmptyPayload(", BodyAt);
  ASSERT_NE(CallAt, std::string::npos) << Source;
  EXPECT_EQ(Source.find("IsEmptyPayload(", CallAt + 1), std::string::npos)
      << Source;
}

