TEST(LLVMCPointerAddresses, InvokeCallIsNotInlined) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-invoke-call", Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *LenTy = llvm::FunctionType::get(I64, {Ptr}, false);
  llvm::Function *Len = llvm::Function::Create(
      LenTy, llvm::GlobalValue::ExternalLinkage, "GetLength", Module);
  llvm::FunctionType *PersTy =
      llvm::FunctionType::get(I32, /*isVarArg=*/true);
  llvm::Function *Pers = llvm::Function::Create(
      PersTy, llvm::GlobalValue::ExternalLinkage, "__CxxFrameHandler3", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr, Ptr}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "invoke_len", Module);
  Function->setPersonalityFn(Pers);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Cont = llvm::BasicBlock::Create(Context, "cont", Function);
  llvm::BasicBlock *Pad = llvm::BasicBlock::Create(Context, "pad", Function);
  llvm::IRBuilder<> Builder(Entry);
  llvm::Value *LenCall = Builder.CreateInvoke(
      Len, Cont, Pad, {Function->getArg(0)}, "len");
  Builder.SetInsertPoint(Cont);
  Builder.CreateStore(LenCall, Function->getArg(1));
  Builder.CreateRetVoid();
  Builder.SetInsertPoint(Pad);
  llvm::LandingPadInst *LP = Builder.CreateLandingPad(
      llvm::StructType::get(Context, {Ptr, I32}), 0);
  LP->setCleanup(true);
  Builder.CreateUnreachable();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  Options.EmitIncludes = false;
  ASSERT_TRUE(
      LLVMCEmitter().emit(Module, OS, Options, nullptr, nullptr, Function));
  OS.flush();
  EXPECT_NE(Source.find("= GetLength("), std::string::npos) << Source;
  EXPECT_EQ(Source.find("GetLength("), Source.rfind("GetLength(")) << Source;
}

TEST(LLVMCPointerAddresses, FieldIncrementPrintsPlusEquals) {
  auto Aux = NdType::makeNamedRecord("CAuxData", 24);
  Aux->FieldDisplayNames = {"_m_nRef"};
  Aux->FieldDisplayOffsets = {8};
  Aux->FieldDisplayTypes = {NdType::makeInt(4, true)};
  class AuxDbg : public NullDebugContext {
  public:
    TypeRef AuxTy;
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140001000)
        return std::nullopt;
      FunctionSym FS;
      FS.Name = "bump_ref";
      FS.Addr = Addr;
      FS.ReturnType = NdType::makeVoid();
      FS.Params.emplace_back("p", NdType::makePtr(AuxTy));
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;
  Dbg.AuxTy = Aux;

  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-field-inc", Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "bump_ref", Module);
  rewrite_source::setOriginalVA(*Function, 0x140001000);
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  llvm::Value *Base = Builder.CreatePtrToInt(Function->getArg(0), I64, "base");
  llvm::Value *Sum =
      Builder.CreateAdd(Base, llvm::ConstantInt::get(I64, 8), "ref_addr");
  llvm::Value *Slot = Builder.CreateIntToPtr(Sum, Ptr, "ref_p");
  llvm::Value *Old = Builder.CreateLoad(I32, Slot, "old");
  llvm::Value *Inc =
      Builder.CreateAdd(Old, llvm::ConstantInt::get(I32, 1), "inc");
  Builder.CreateStore(Inc, Slot);
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  Options.EmitIncludes = false;
  ASSERT_TRUE(
      LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr, Function));
  OS.flush();
  EXPECT_NE(Source.find("p->_m_nRef += 1"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("_m_nRef = ("), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, AtlCtorKeepsEmptyWideImageArg) {
  BinaryImage Img = makeImageObjectFixture(0x1400464F0, {0, 0}, false);
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-ctor-empty-wide", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  auto *Base = new llvm::GlobalVariable(
      Module, I8, /*isConstant=*/true, llvm::GlobalValue::ExternalLinkage,
      nullptr, (kNdCodePtrPrefix + llvm::utohexstr(0x140030000)).str());
  llvm::FunctionType *CtorTy =
      llvm::FunctionType::get(I64, {I64, I64}, false);
  llvm::Function *Ctor = llvm::Function::Create(
      CtorTy, llvm::GlobalValue::ExternalLinkage, "CStringT_ctor", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(I64, {I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "GetDisplayName", Module);
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  llvm::Value *Slot = Builder.CreateAlloca(I64, nullptr, "t7");
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), Slot);
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0x1400464F0), Slot);
  llvm::Value *Lit = Builder.CreateLoad(I64, Slot, "t7_v");
  llvm::Value *Off = Builder.CreateSub(
      Lit, llvm::ConstantInt::get(I64, 0x140030000), "selmrgoff");
  llvm::Value *Gep = Builder.CreateInBoundsGEP(I8, Base, Off, "selmrgptr");
  llvm::Value *AsInt = Builder.CreatePtrToInt(Gep, I64, "lit_i");
  Builder.CreateCall(Ctor, {Function->getArg(0), AsInt});
  Builder.CreateRet(Function->getArg(0));

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options, nullptr, &Img,
                                  Function));
  OS.flush();
  EXPECT_NE(Source.find("CStringT_ctor("), std::string::npos) << Source;
  EXPECT_NE(Source.find("L\"\""), std::string::npos) << Source;
  EXPECT_EQ(Source.find("1400464F0"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("1400464f0"), std::string::npos) << Source;
}

