TEST(HighCPointerAddresses, FieldLoadComposesIntoIfCondAndStore) {
  auto Record = NdType::makeNamedRecord("CRecord", 192);
  Record->FieldDisplayNames = {"m_completedCount"};
  Record->FieldDisplayOffsets = {80};
  HighFunc Func;
  Func.Name = "CRecord_LabelKill";
  Func.ReturnType = NdType::makeVoid();
  Func.Params = {{"this", NdType::makePtr(Record)}};
  MedVar Cnt;
  Cnt.Kind = MedVar::Temp;
  Cnt.Id = 97;
  Cnt.Size = 4;
  Cnt.TheArch = Arch::X64;
  HighStmt Load;
  Load.Kind = StmtKind::Assign;
  Load.Dst = HighExpr::makeVar(Cnt, NdType::makeInt(4));
  Load.Val = HighExpr::makeUnary(
      NdOp::INT_SEXT,
      HighExpr::makeLoad(
          HighExpr::makeBinop(NdOp::INT_ADD, parameter(0, Func.Params[0].Type),
                              HighExpr::makeConst(80, 8)),
          NdType::makeInt(4)));
  Load.Val->Type = NdType::makeInt(4);
  Func.Body.push_back(std::move(Load));
  HighStmt If;
  If.Kind = StmtKind::If;
  If.Cond = HighExpr::makeVar(Cnt, NdType::makeInt(4));
  HighStmt Store;
  Store.Kind = StmtKind::Store;
  Store.StoreAddr = HighExpr::makeConst(0x140008000, 8);
  Store.StoreVal = HighExpr::makeVar(Cnt, NdType::makeInt(4));
  If.Body.push_back(std::move(Store));
  Func.Body.push_back(std::move(If));
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("if (this->m_completedCount)"), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("this->m_completedCount"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t97"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("v97"), std::string::npos) << Source;
}

