TEST(HighCPointerAddresses, TypedCallPeelsWidenedImmediate) {
  class CalleeDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140002000)
        return std::nullopt;
      FunctionSym FS;
      FS.Name = "Catalog_Lookup";
      FS.Addr = Addr;
      FS.ReturnType = NdType::makeNamedRecord("CStringT", 8);
      FS.Params.emplace_back("this", NdType::makePtr());
      FS.Params.emplace_back("nType", NdType::makeInt(4, true));
      FS.Params.emplace_back("nKey", NdType::makeInt(4, true));
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  HighFunc Func;
  Func.Name = "find_imm";
  Func.ReturnType = NdType::makeVoid();
  auto Wide = HighExpr::makeUnary(NdOp::INT_ZEXT, HighExpr::makeConst(1, 4));
  Wide->Type = NdType::makeInt(8, false);
  HighStmt Call;
  Call.Kind = StmtKind::Assign;
  MedVar Dest;
  Dest.Kind = MedVar::Temp;
  Dest.Id = 1;
  Dest.Size = 8;
  Dest.TheArch = Arch::X64;
  Call.Dst = HighExpr::makeVar(Dest, NdType::makeInt(8));
  Call.Val = HighExpr::makeCall(
      "Catalog_Lookup", 0x140002000,
      {HighExpr::makeConst(0x140006000, 8), HighExpr::makeConst(0x140005000, 8),
       Wide, HighExpr::makeConst(42, 4)});
  Func.Body.push_back(std::move(Call));
  HighStmt Ret;
  Ret.Kind = StmtKind::Return;
  Func.Body.push_back(std::move(Ret));
  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  ASSERT_TRUE(HighCEmitter().emit({Func}, OS, Options, &Dbg));
  OS.flush();
  EXPECT_NE(Source.find("Catalog_Lookup("), std::string::npos) << Source;
  EXPECT_NE(Source.find(", 1, 42)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(uint32_t)1"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(int64_t)"), std::string::npos) << Source;
}

