TEST(HighCPointerAddresses, CallArgNamedFrameSlotOmitsIntegerView) {
  HighFunc Func;
  Func.Name = "isempty_slot";
  Func.FrameSize = 64;
  Func.ReturnType = NdType::makeVoid();
  MedVar SP;
  SP.Kind = MedVar::Reg;
  SP.Size = 8;
  SP.TheArch = Arch::X64;
  SP.RegOff = getTargetRegInfo(Arch::X64).StackPointer;
  auto Sp = HighExpr::makeVar(SP, NdType::makeInt(8, false));
  auto Slot = HighExpr::makeBinop(NdOp::INT_SUB, Sp, HighExpr::makeConst(8, 8));
  HighStmt Store;
  Store.Kind = StmtKind::Store;
  Store.StoreAddr = Slot;
  Store.StoreVal = HighExpr::makeConst(0, 8);
  Func.Body.push_back(std::move(Store));
  auto Wide = HighExpr::makeUnary(NdOp::INT_ZEXT, Slot);
  Wide->Type = NdType::makeInt(8, false);
  HighStmt Call;
  Call.Kind = StmtKind::ExprStmt;
  Call.Val = HighExpr::makeCall("IsEmpty", 0x140032a38, {Wide});
  Func.Body.push_back(std::move(Call));
  HighStmt Ret;
  Ret.Kind = StmtKind::Return;
  Func.Body.push_back(std::move(Ret));
  const std::string Source = emitFunctions({Func});
  const auto Args = lastCallArguments(Source, "IsEmpty");
  ASSERT_TRUE(Args) << Source;
  ASSERT_EQ(Args->size(), 1u) << Source;
  EXPECT_NE((*Args)[0].find("frame_base"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("unknown register"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(int32_t)&"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(uint32_t)&"), std::string::npos) << Source;
}

