TEST(HighCPointerAddresses, DebugCalleePointerArgsOmitIntegerView) {
  class CalleeDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr == 0x140001000) {
        FunctionSym FS;
        FS.Name = "CRecord_GetRecordNameWithColor";
        FS.Addr = Addr;
        FS.CallConv = DebugCallConv::Cdecl;
        FS.ReturnType = NdType::makeNamedRecord("CStringT", 8);
        FS.Params.emplace_back(
            "this", NdType::makePtr(NdType::makeNamedRecord("CRecord", 8)));
        return FS;
      }
      if (Addr == 0x140002000) {
        FunctionSym FS;
        FS.Name = "CRecord_GetRecordName";
        FS.Addr = Addr;
        FS.ReturnType = NdType::makeNamedRecord("ATL::CStringT<wchar_t>", 8);
        FS.Params.emplace_back(
            "this", NdType::makePtr(NdType::makeNamedRecord("CRecord", 8)));
        return FS;
      }
      return std::nullopt;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  HighFunc Func;
  Func.Name = "CRecord_GetRecordNameWithColor";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  Func.Params = {
      {"this", NdType::makePtr(NdType::makeNamedRecord("CRecord", 8))},
      {"result", NdType::makePtr(NdType::makeNamedRecord("CStringT", 8))}};
  Func.FrameSize = 16;
  MedVar SP;
  SP.Kind = MedVar::Reg;
  SP.Size = 8;
  SP.TheArch = Arch::X64;
  SP.RegOff = getTargetRegInfo(Arch::X64).StackPointer;
  auto Home = HighExpr::makeBinop(
      NdOp::INT_SUB, HighExpr::makeVar(SP, NdType::makeInt(8, false)),
      HighExpr::makeConst(8, 8));
  HighStmt Store;
  Store.Kind = StmtKind::Store;
  Store.StoreAddr = Home;
  Store.StoreVal = parameter(1, Func.Params[1].Type);
  Func.Body.push_back(std::move(Store));
  HighStmt Call;
  Call.Kind = StmtKind::Assign;
  MedVar Dest;
  Dest.Kind = MedVar::Temp;
  Dest.Id = 24;
  Dest.Size = 8;
  Dest.TheArch = Arch::X64;
  Call.Dst = HighExpr::makeVar(Dest, NdType::makeInt(8));
  Call.Val = HighExpr::makeCall("CRecord_GetRecordName", 0x140002000,
                               {parameter(0, Func.Params[0].Type), Home});
  Func.Body.push_back(std::move(Call));
  HighStmt Ret;
  Ret.Kind = StmtKind::Return;
  Ret.RetVal = parameter(1, Func.Params[1].Type);
  Func.Body.push_back(std::move(Ret));

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  ASSERT_TRUE(HighCEmitter().emit({Func}, OS, Options, &Dbg));
  OS.flush();
  EXPECT_NE(Source.find("extern __fastcall CStringT* CRecord_GetRecordName("
                        "CRecord* this, CStringT* result)"),
            std::string::npos)
      << Source;
  const auto Args = lastCallArguments(Source, "CRecord_GetRecordName");
  ASSERT_TRUE(Args) << Source;
  ASSERT_EQ(Args->size(), 2u) << Source;
  EXPECT_EQ((*Args)[0], "this") << Source;
  EXPECT_NE((*Args)[1].find("(CStringT*)(uintptr_t)((frame_base - 8))"),
            std::string::npos) << Source;
  EXPECT_EQ(Source.find("unknown register"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("var_m8 ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("CStringT* var_m8"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("GetRecordName((uintptr_t)this"), std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("(uintptr_t)&"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("CRecord* var_m8"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("::"), std::string::npos) << Source;
}

