TEST(HighCPointerAddresses, LabelIfElsePrintsGreaterOnMaxCount) {
  auto U32 = NdType::makeInt(4, false);
  auto Record = NdType::makeNamedRecord("CRecord", 32);
  Record->FieldDisplayNames = {"m_completedCount", "maxCount"};
  Record->FieldDisplayOffsets = {8, 12};
  Record->FieldDisplayTypes = {U32, U32};
  HighFunc Func;
  Func.Name = "label_gt";
  Func.ReturnType = NdType::makeVoid();
  Func.Params = {{"this", NdType::makePtr(Record)}};
  auto This = parameter(0, Func.Params[0].Type);
  auto Kill = HighExpr::makeLoad(
      HighExpr::makeBinop(NdOp::INT_ADD, This, HighExpr::makeConst(8, 8)),
      NdType::makeInt(4, true));
  auto Max = HighExpr::makeLoad(
      HighExpr::makeBinop(NdOp::INT_ADD, This, HighExpr::makeConst(12, 8)),
      NdType::makeInt(4, true));
  HighStmt Master;
  Master.Kind = StmtKind::Call;
  Master.CallExpr = HighExpr::makeCall("master", 0x140002000, {This});
  HighStmt Taken;
  Taken.Kind = StmtKind::Call;
  Taken.CallExpr = HighExpr::makeCall("kill", 0x140002100, {This});
  HighStmt Guard;
  Guard.Kind = StmtKind::IfElse;
  Guard.Cond = HighExpr::makeUnary(
      NdOp::BOOL_NOT,
      HighExpr::makeBinop(
          NdOp::BOOL_AND,
          HighExpr::makeBinop(NdOp::INT_LESSEQUAL, Kill, Max),
          HighExpr::makeBinop(NdOp::INT_NOTEQUAL, Kill, Max)));
  Guard.Body = {Master};
  Guard.ElseBody = {Taken};
  Func.Body = {Guard};
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("this->maxCount > this->m_completedCount"),
            std::string::npos)
      << Source;
  const size_t Gt = Source.find("this->maxCount > this->m_completedCount");
  ASSERT_NE(Gt, std::string::npos);
  const size_t KillAt = Source.find("kill(", Gt);
  const size_t MasterAt = Source.find("master(", Gt);
  ASSERT_NE(KillAt, std::string::npos) << Source;
  ASSERT_NE(MasterAt, std::string::npos) << Source;
  EXPECT_LT(KillAt, MasterAt) << Source;
  EXPECT_EQ(Source.find(" >= "), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(int32_t)this->"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(uint32_t)this->"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, AddressOfWrapperRecordOmitsOffset0Field) {
  auto Str = NdType::makeNamedRecord("CStringT", 8);
  Str->FieldDisplayNames = {"m_pszData"};
  Str->FieldDisplayOffsets = {0};
  Str->FieldDisplayTypes = {NdType::makePtr()};
  auto Record = NdType::makeNamedRecord("CRecord", 192);
  Record->FieldDisplayNames = {"m_auxName"};
  Record->FieldDisplayOffsets = {32};
  Record->FieldDisplayTypes = {Str};
  HighFunc Func;
  Func.Name = "aux_name";
  Func.ReturnType = NdType::makeVoid();
  Func.Params = {{"this", NdType::makePtr(Record)}};
  auto Addr = HighExpr::makeBinop(NdOp::INT_ADD, parameter(0, Func.Params[0].Type),
                                  HighExpr::makeConst(32, 8));
  HighStmt GetLen;
  GetLen.Kind = StmtKind::If;
  GetLen.Cond = HighExpr::makeBinop(
      NdOp::INT_SLESS, HighExpr::makeConst(0, 4),
      HighExpr::makeCall("GetLength", 0x140032a40, {Addr}));
  HighStmt Assign;
  Assign.Kind = StmtKind::Call;
  Assign.CallExpr =
      HighExpr::makeCall("CStringT_assign", 0x1400329f8, {parameter(0), Addr});
  GetLen.Body = {Assign};
  HighStmt Load;
  Load.Kind = StmtKind::Assign;
  MedVar Dest;
  Dest.Kind = MedVar::Temp;
  Dest.Id = 1;
  Dest.Size = 8;
  Dest.TheArch = Arch::X64;
  Load.Dst = HighExpr::makeVar(Dest, NdType::makePtr());
  Load.Val = HighExpr::makeLoad(Addr, NdType::makePtr());
  HighStmt Use;
  Use.Kind = StmtKind::Call;
  Use.CallExpr = HighExpr::makeCall(
      "use_ptr", 0x140002000, {HighExpr::makeVar(Dest, NdType::makePtr())});
  Func.Body = {GetLen, Load, Use};
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("GetLength(&this->m_auxName)"), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("CStringT_assign("), std::string::npos) << Source;
  EXPECT_NE(Source.find("&this->m_auxName"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("&this->m_auxName.m_pszData"), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("this->m_auxName.m_pszData"), std::string::npos)
      << Source;
}

