TEST(HighCPointerAddresses, UnionOverlayPicksUniqueAccessWidth) {
  auto Aux = NdType::makeNamedRecord("CAuxData", 24);
  Aux->FieldDisplayNames = {"_m_nRef", "_m_pNext"};
  Aux->FieldDisplayOffsets = {8, 8};
  Aux->FieldDisplayTypes = {NdType::makeInt(4, true),
                            NdType::makePtr(NdType::makeVoid())};
  HighFunc Func;
  Func.Name = "release";
  Func.ReturnType = NdType::makeVoid();
  Func.Params = {{"p", NdType::makePtr(Aux)}};
  const auto I32 = NdType::makeInt(4, true);
  auto Addr = [&]() {
    auto Add = HighExpr::makeBinop(NdOp::INT_ADD, parameter(0, Func.Params[0].Type),
                                   HighExpr::makeConst(8, 8));
    Add->Type = NdType::makeInt(8, false);
    return Add;
  };
  MedVar T;
  T.Kind = MedVar::Temp;
  T.Id = 94;
  T.SSAVer = 8;
  T.Size = 4;
  T.TheArch = Arch::X64;
  HighStmt Load;
  Load.Kind = StmtKind::Assign;
  Load.Dst = HighExpr::makeVar(T, I32);
  Load.Val = HighExpr::makeLoad(Addr(), I32);
  auto Inc = HighExpr::makeBinop(NdOp::INT_ADD, HighExpr::makeVar(T, I32),
                                 HighExpr::makeConst(1, 4));
  Inc->Type = I32;
  HighStmt Store;
  Store.Kind = StmtKind::Store;
  Store.StoreAddr = Addr();
  Store.StoreVal = Inc;
  auto AtomicAddr = HighExpr::makeBinop(
      NdOp::INT_ADD, parameter(0, Func.Params[0].Type), HighExpr::makeConst(8, 8));
  AtomicAddr->Type = NdType::makeInt(8, false);
  auto Atomic = HighExpr::makeBinop(NdOp::ATOMIC_ADD, std::move(AtomicAddr),
                                    HighExpr::makeConst(static_cast<uint64_t>(-1), 4));
  Atomic->Type = NdType::makeInt(4, false);
  Atomic->MemoryOrdering = NdMemoryOrdering::SequentiallyConsistent;
  HighStmt Fetch;
  Fetch.Kind = StmtKind::ExprStmt;
  Fetch.Val = std::move(Atomic);
  Func.Body = {Load, Store, Fetch};
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("p->_m_nRef"), std::string::npos) << Source;
  EXPECT_NE(Source.find("__atomic_fetch_add(&p->_m_nRef, 0xFFFFFFFF,"),
            std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("(uint32_t *)(&p->_m_nRef)"), std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("(uint32_t)(-1)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("___u1"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("_m_pNext"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("+ 8"), std::string::npos) << Source;
}

