  AddPtr.addInput(This);
  AddPtr.addInput(MedVar::makeConst(80, 8));
  AddPtr.Addr = 0x140001000;
  Block.Ops.push_back(std::move(AddPtr));
  MedOp LoadPtr;
  LoadPtr.Opcode = NdOp::LOAD;
  LoadPtr.Output = PtrBox;
  LoadPtr.addInput(TAddr0);
  LoadPtr.Addr = 0x140001004;
  Block.Ops.push_back(std::move(LoadPtr));
  MedOp AddField;
  AddField.Opcode = NdOp::INT_ADD;
  AddField.Output = TAddr1;
  AddField.addInput(PtrBox);
  AddField.addInput(MedVar::makeConst(0x2C0, 8));
  AddField.Addr = 0x140001008;
  Block.Ops.push_back(std::move(AddField));
  MedOp LoadField;
  LoadField.Opcode = NdOp::LOAD;
  LoadField.Output = TField;
  LoadField.addInput(TAddr1);
  LoadField.Addr = 0x14000100C;
  Block.Ops.push_back(std::move(LoadField));
  MedOp Zext;
  Zext.Opcode = NdOp::INT_ZEXT;
  Zext.Output = RDX1;
  Zext.addInput(TField);
  Zext.Addr = 0x140001010;
  Block.Ops.push_back(std::move(Zext));
  MedOp Call;
  Call.Opcode = NdOp::CALL;
  Call.Addr = 0x140001014;
  Call.addInput(MedVar::makeConst(0x140002000, 8));
  Block.Ops.push_back(std::move(Call));
  MedOp Ret;
  Ret.Opcode = NdOp::RETURN;
  Ret.Addr = 0x140001018;
  Block.Ops.push_back(std::move(Ret));
