  const MedVar RSP0 = Reg(4, 0, x86reg::RSP);
  const MedVar RCX1 = Reg(10, 107, x86reg::RCX);
  const MedVar XMM0 = Reg(21, 1, x86reg::XMM0, 16);
  const MedVar T116 = Temp(116, 5, 16);
  const MedVar NameAddr = Temp(68, 241, 8);

  MedFunc Med;
  Med.Entry = 0x140001000;
  Med.Name = "label_kill_xmm";
  Med.CC = CallingConv::Win64;
