  MedBlock Fork;
  Fork.Id = 0;
  Fork.StartAddr = 0x140001000;
  Fork.EndAddr = 0x140001010;
  Fork.Succs = {1};
  MedOp LeaAddr;
  LeaAddr.Opcode = NdOp::INT_ADD;
  LeaAddr.Output = NameAddr;
  LeaAddr.addInput(RSP0);
  LeaAddr.addInput(MedVar::makeConst(0xD0, 8));
  LeaAddr.Addr = 0x140001000;
  Fork.Ops.push_back(std::move(LeaAddr));
  MedOp LeaRcx;
  LeaRcx.Opcode = NdOp::COPY;
  LeaRcx.Output = RCX1;
  LeaRcx.addInput(NameAddr);
  LeaRcx.Addr = 0x140001004;
  Fork.Ops.push_back(std::move(LeaRcx));
  MedOp Br;
  Br.Opcode = NdOp::BRANCH;
  Br.Addr = 0x140001008;
  Br.addInput(MedVar::makeConst(0x140001010, 8));
  Fork.Ops.push_back(std::move(Br));

  MedBlock Mid;
  Mid.Id = 1;
  Mid.StartAddr = 0x140001010;
  Mid.EndAddr = 0x140001018;
  Mid.Preds = {0};
  Mid.Succs = {2};
  MedOp MidBr;
  MidBr.Opcode = NdOp::BRANCH;
  MidBr.Addr = 0x140001010;
  MidBr.addInput(MedVar::makeConst(0x140001018, 8));
  Mid.Ops.push_back(std::move(MidBr));

  MedBlock Taken;
  Taken.Id = 2;
  Taken.StartAddr = 0x140001018;
  Taken.EndAddr = 0x140001038;
  Taken.Preds = {1};
  const MedVar LoadAddr = Temp(68, 300, 8);
  MedOp LeaLoad;
  LeaLoad.Opcode = NdOp::INT_ADD;
  LeaLoad.Output = LoadAddr;
  LeaLoad.addInput(RSP0);
  LeaLoad.addInput(MedVar::makeConst(static_cast<uint64_t>(-16), 8));
  LeaLoad.Addr = 0x140001018;
  Taken.Ops.push_back(std::move(LeaLoad));
  MedOp LoadName;
  LoadName.Opcode = NdOp::LOAD;
  LoadName.Output = T116;
  LoadName.addInput(LoadAddr);
  LoadName.Addr = 0x14000101A;
  Taken.Ops.push_back(std::move(LoadName));
  MedOp Movups;
  Movups.Opcode = NdOp::COPY;
  Movups.Output = XMM0;
  Movups.addInput(T116);
  Movups.Addr = 0x14000101C;
  Taken.Ops.push_back(std::move(Movups));
  MedOp Call;
  Call.Opcode = NdOp::INDIR_CALL;
  Call.Addr = 0x140001020;
  Call.addInput(MedVar::makeConst(0x140002000, 8));
  Taken.Ops.push_back(std::move(Call));
  MedOp Ret;
  Ret.Opcode = NdOp::RETURN;
  Ret.Addr = 0x140001028;
