TEST(HighCPointerAddresses, PoorerDeclaredParamPrefersRicherDebugType) {
  auto Holder = NdType::makeNamedRecord("PtrBox", 16);
  Holder->FieldDisplayNames = {"p"};
  Holder->FieldDisplayOffsets = {8};
  auto Life = NdType::makeNamedRecord("RecordLife", 8);
  Life->FieldDisplayNames = {"expirationType"};
  Life->FieldDisplayOffsets = {0};
  auto Data = NdType::makeNamedRecord("CRecordData", 1792);
  Data->FieldDisplayNames = {"m_life"};
  Data->FieldDisplayOffsets = {64};
  Data->FieldDisplayTypes = {Life};
  Holder->FieldDisplayTypes = {NdType::makePtr(Data)};
  auto Poor = NdType::makeNamedRecord("CRecord", 512);
  Poor->FieldDisplayNames = {"m_pRecordData"};
  Poor->FieldDisplayOffsets = {72};
  Poor->FieldDisplayTypes = {Holder};
  auto Rich = NdType::makeNamedRecord("CRecord", 512);
  Rich->FieldDisplayNames = {"m_completedCount", "m_pRecordData", "m_pRecordBadge"};
  Rich->FieldDisplayOffsets = {32, 72, 136};
  Rich->FieldDisplayTypes = {NdType::makeInt(4, false), Holder, Holder};
  HighFunc Func;
  Func.Name = "CRecord_RicherDebug";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeInt(8);
  Func.Params = {{"this", NdType::makePtr(Poor)}};
  class RichDbg : public NullDebugContext {
  public:
    TypeRef Record;
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140001000)
        return std::nullopt;
      FunctionSym FS;
      FS.Name = "CRecord_RicherDebug";
      FS.Addr = Addr;
      FS.Params.emplace_back("this", NdType::makePtr(Record));
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;
  Dbg.Record = Rich;
  MedVar Dest;
  Dest.Kind = MedVar::Temp;
  Dest.Id = 2;
  Dest.Size = 8;
  Dest.TheArch = Arch::X64;
  HighStmt Load;
  Load.Kind = StmtKind::Assign;
  Load.Dst = HighExpr::makeVar(Dest, NdType::makeInt(8));
  Load.Val = HighExpr::makeLoad(
      HighExpr::makeBinop(NdOp::INT_ADD, parameter(0, Func.Params[0].Type),
                          HighExpr::makeConst(144, 8)),
      NdType::makeInt(8));
  Func.Body.push_back(std::move(Load));
  returnValue(Func, HighExpr::makeVar(Dest, NdType::makeInt(8)));
  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  ASSERT_TRUE(HighCEmitter().emit({Func}, OS, Options, &Dbg));
  OS.flush();
  EXPECT_NE(Source.find("this->m_pRecordBadge.p"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("expirationType"), std::string::npos) << Source;
}

