TEST(HighCPointerAddresses, IndirectCallPrintsLoadedCalleePlusOffset) {
  HighFunc Func;
  Func.Name = "look";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  Func.Params = {{"p", NdType::makePtr(NdType::makeInt(8))}};
  auto Object = parameter(0, Func.Params[0].Type);
  auto Vtbl = HighExpr::makeLoad(Object, NdType::makeInt(8));
  auto Slot = HighExpr::makeBinop(NdOp::INT_ADD, Vtbl,
                                  HighExpr::makeConst(88, 8));
  auto AsU64 = std::make_shared<HighExpr>();
  AsU64->Kind = ExprKind::Cast;
  AsU64->CastTo = NdType::makeInt(8, false);
  AsU64->Type = NdType::makeInt(8, false);
  AsU64->Operands.push_back(Slot);
  auto AsI64 = std::make_shared<HighExpr>();
  AsI64->Kind = ExprKind::Cast;
  AsI64->CastTo = NdType::makeInt(8, true);
  AsI64->Type = NdType::makeInt(8, true);
  AsI64->Operands.push_back(std::move(AsU64));
  HighStmt Call;
  Call.Kind = StmtKind::Call;
  Call.CallExpr =
      HighExpr::makeCall("indirect", 0, {Object, HighExpr::makeConst(1, 4)});
  Call.CallExpr->IsIndirectCall = true;
  Call.CallExpr->IndirectTarget =
      HighExpr::makeLoad(std::move(AsI64), NdType::makePtr());
  Func.Body = {Call};
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("(*(void **)((uintptr_t)(*(void **)(p)) + 88))("),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("(uintptr_t)p, 1)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("*(int64_t *)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(uint64_t)((uint64_t)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("indirect("), std::string::npos) << Source;
}

