  Builder.CreateStore(Builder.CreateZExt(LoadId(), I64), R9);
  Builder.CreateBr(Join);

  Builder.SetInsertPoint(Else);
  llvm::Value *ElseId = Builder.CreateLoad(I32, ZeroHome, "EDI_2_v");
  Builder.CreateStore(Builder.CreateZExt(ElseId, I64), R9);
  Builder.CreateBr(Join);

  Builder.SetInsertPoint(Join);
  (void)Builder.CreateLoad(I64, R9, "r9_join");
  llvm::Value *Reload = LoadId();
  llvm::Value *Table = llvm::ConstantPointerNull::get(
      llvm::cast<llvm::PointerType>(Ptr));
