  Builder.CreateBr(Join);

  Builder.SetInsertPoint(Join);
  llvm::Value *Loaded = Builder.CreateLoad(I64, RDX, "RDX.28_v");
  Builder.CreateCall(ExW, {Function->getArg(0), Loaded, Function->getArg(0)});
  Builder.CreateRetVoid();

