TEST(HighCPointerAddresses, InvertSkipInsideSehTryFoldsRaise) {
  HighFunc Func;
  Func.Name = "seh_skip";
  Func.Entry = 0x401040;
  Func.ReturnType = NdType::makeInt(4);
  Func.Params = {{"arg0", NdType::makeInt(4)}};
  MedVar Result;
  Result.Kind = MedVar::Stack;
  Result.Id = 20;
  Result.Size = 4;
  Result.TheArch = Arch::X86;
  Result.StackOff = -20;
  HighStmt SkipGoto;
  SkipGoto.Kind = StmtKind::Goto;
  SkipGoto.GotoTarget = 0x40108D;
  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = HighExpr::makeBinop(NdOp::INT_NOTEQUAL,
                                   parameter(0, NdType::makeInt(4)),
                                   HighExpr::makeConst(7, 4));
  Guard.Body = {SkipGoto};
  HighStmt Raise;
  Raise.Kind = StmtKind::Call;
  Raise.CallExpr = HighExpr::makeCall("RaiseException", 0x401200,
                                      {HighExpr::makeConst(0xE0421001, 4)});
  HighStmt Join;
  Join.Kind = StmtKind::Assign;
  Join.Addr = 0x40108D;
  Join.Dst = HighExpr::makeVar(Result, NdType::makeInt(4, true));
  Join.Val = HighExpr::makeConst(static_cast<uint64_t>(-100), 4);
  HighStmt Try;
  Try.Kind = StmtKind::SEHTry;
  Try.EHIsReducible = true;
  Try.Body = {Guard, Raise, Join};
  HighEHClause Except;
  Except.Kind = HighEHClauseKind::SEHExcept;
  Try.EHClauses.push_back(Except);
  HighStmt Handler;
  Handler.Kind = StmtKind::Assign;
  Handler.Dst = HighExpr::makeVar(Result, NdType::makeInt(4, true));
  Handler.Val = HighExpr::makeConst(41, 4);
  Try.EHClauseBodies.push_back({Handler});
  HighStmt Ret;
  Ret.Kind = StmtKind::Return;
  Ret.RetVal = HighExpr::makeVar(Result, NdType::makeInt(4, true));
  Func.Body = {Try, Ret};
  invertSkipGotos(Func);
  structureIfElse(Func, 8, nullptr);
  const std::string Source = emitFunctions({Func}, Arch::X86);
  EXPECT_EQ(Source.find("goto L_"), std::string::npos) << Source;
  EXPECT_NE(Source.find("RaiseException"), std::string::npos) << Source;
  EXPECT_NE(Source.find("0xFFFFFF9C"), std::string::npos) << Source;
  EXPECT_NE(Source.find("= 41"), std::string::npos) << Source;
}

