TEST(HighCPointerAddresses, FallthroughAfterExitingIfDropsImpliedOr) {
  HighFunc Func;
  Func.Name = "media_fallthrough";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  auto IsMedia = []() {
    return HighExpr::makeCall("IsMediaPayload", 0x140002100, {parameter(0)});
  };
  auto EqZero = [](ExprPtr X) {
    return HighExpr::makeBinop(NdOp::INT_EQUAL, std::move(X),
                               HighExpr::makeConst(0, 4));
  };
  HighStmt Out;
  Out.Kind = StmtKind::Goto;
  Out.GotoTarget = 0x1400017DD;
  HighStmt Skip;
  Skip.Kind = StmtKind::If;
  Skip.Cond = EqZero(IsMedia());
  Skip.Body = {Out};
  HighStmt Find;
  Find.Kind = StmtKind::Call;
  Find.CallExpr = HighExpr::makeCall("Find", 0x140002000, {parameter(0)});
  HighStmt Table;
  Table.Kind = StmtKind::Call;
  Table.CallExpr = HighExpr::makeCall("table", 0x140002200, {parameter(0)});
  HighStmt Label;
  Label.Kind = StmtKind::Call;
  Label.CallExpr = HighExpr::makeCall("label", 0x140002300, {parameter(0)});
  HighStmt Inner;
  Inner.Kind = StmtKind::IfElse;
  Inner.Cond = HighExpr::makeBinop(
      NdOp::BOOL_OR,
      HighExpr::makeBinop(NdOp::BOOL_OR, EqZero(IsMedia()),
                          HighExpr::makeBinop(NdOp::INT_NOTEQUAL, parameter(1),
                                              HighExpr::makeConst(1, 4))),
      HighExpr::makeBinop(NdOp::INT_EQUAL, parameter(2),
                          HighExpr::makeConst(0, 8)));
  Inner.Body = {Table};
  Inner.ElseBody = {Label};
  HighStmt Ret;
  Ret.Kind = StmtKind::Return;
  Func.Body = {Skip, Find, Inner, Ret};
  invertSkipGotos(Func);
  ASSERT_GE(Func.Body.size(), 3u);
  const HighStmt *Guard = nullptr;
  for (const HighStmt &S : Func.Body) {
    if (S.Kind != StmtKind::IfElse || S.Body.empty() || !S.Body[0].CallExpr ||
        S.Body[0].CallExpr->CallTarget != "table")
      continue;
    Guard = &S;
  }
  ASSERT_NE(Guard, nullptr);
  auto CountCalls = [&](const HighExpr *E, const char *Name,
                        auto &&Self) -> unsigned {
    if (!E)
      return 0;
    unsigned N = E->Kind == ExprKind::Call && E->CallTarget == Name ? 1 : 0;
    for (const ExprPtr &Op : E->Operands)
      N += Self(Op.get(), Name, Self);
    return N;
  };
  EXPECT_EQ(CountCalls(Guard->Cond.get(), "IsMediaPayload", CountCalls), 0u);
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("Find("), std::string::npos) << Source;
  EXPECT_NE(Source.find("table("), std::string::npos) << Source;
  EXPECT_NE(Source.find("label("), std::string::npos) << Source;
  const auto BodyAt = Source.find("void media_fallthrough");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  size_t MediaCount = 0;
  for (size_t Pos = BodyAt;
       (Pos = Source.find("IsMediaPayload(", Pos)) != std::string::npos; Pos += 13)
    ++MediaCount;
  EXPECT_EQ(MediaCount, 1u) << Source;
}

