TEST(HighCPointerAddresses, NegatedIfElseSwapsToPositiveCond) {
  HighFunc Func;
  Func.Name = "adjustment_pos";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  HighStmt Regular;
  Regular.Kind = StmtKind::Call;
  Regular.CallExpr =
      HighExpr::makeCall("regularAdjustment", 0x140002000, {parameter(0)});
  HighStmt Unlimited;
  Unlimited.Kind = StmtKind::Call;
  Unlimited.CallExpr =
      HighExpr::makeCall("unlimitedAdjustment", 0x140002100, {parameter(0)});
  HighStmt Guard;
  Guard.Kind = StmtKind::IfElse;
  Guard.Cond = HighExpr::makeUnary(
      NdOp::BOOL_NOT,
      HighExpr::makeCall("GetAdjustmentLevel", 0x140002200, {parameter(0)}));
  Guard.Body = {Regular};
  Guard.ElseBody = {Unlimited};
  Func.Body = {Guard};
  invertSkipGotos(Func);
  ASSERT_EQ(Func.Body.size(), 1u);
  ASSERT_EQ(Func.Body[0].Kind, StmtKind::IfElse);
  ASSERT_TRUE(Func.Body[0].Cond);
  EXPECT_EQ(Func.Body[0].Cond->Kind, ExprKind::Call);
  EXPECT_EQ(Func.Body[0].Cond->CallTarget, "GetAdjustmentLevel");
  ASSERT_FALSE(Func.Body[0].Body.empty());
  EXPECT_TRUE(Func.Body[0].Body[0].CallExpr &&
              Func.Body[0].Body[0].CallExpr->CallTarget == "unlimitedAdjustment");
  const std::string Source = emitFunctions({Func});
  const auto BodyAt = Source.find("void adjustment_pos");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto Unl = Source.find("unlimitedAdjustment(", BodyAt);
  const auto Reg = Source.find("regularAdjustment(", BodyAt);
  EXPECT_NE(Unl, std::string::npos) << Source;
  EXPECT_NE(Reg, std::string::npos) << Source;
  EXPECT_LT(Unl, Reg) << Source;
  EXPECT_EQ(Source.find("!GetAdjustmentLevel", BodyAt), std::string::npos)
      << Source;
}

