TEST(HighCPointerAddresses, CallCondI32UndefStoreKeepsUnknownValue) {
  HighFunc Func;
  Func.Name = "adjustment_eax";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  MedVar Level;
  Level.Kind = MedVar::Temp;
  Level.Id = 113;
  Level.Size = 4;
  Level.TheArch = Arch::X64;
  MedVar View;
  View.Kind = MedVar::Temp;
  View.Id = 114;
  View.Size = 4;
  View.TheArch = Arch::X64;
  MedVar Slot;
  Slot.Kind = MedVar::Stack;
  Slot.Id = 50;
  Slot.Size = 4;
  Slot.StackOff = -80;
  Slot.TheArch = Arch::X64;
  HighStmt Get;
  Get.Kind = StmtKind::Assign;
  Get.Dst = HighExpr::makeVar(Level);
  Get.Val = HighExpr::makeCall("GetAdjustmentLevel", 0x140002200, {parameter(0)});
  HighStmt Cmp;
  Cmp.Kind = StmtKind::Assign;
  Cmp.Dst = HighExpr::makeVar(View);
  Cmp.Val = HighExpr::makeBinop(NdOp::SUBBYTES, HighExpr::makeVar(Level),
                                HighExpr::makeConst(0, 4));
  HighStmt Regular;
  Regular.Kind = StmtKind::Call;
  Regular.CallExpr =
      HighExpr::makeCall("regularAdjustment", 0x140002000, {parameter(0)});
  HighStmt Ctor;
  Ctor.Kind = StmtKind::Call;
  Ctor.CallExpr = HighExpr::makeCall("CStringT_ctor", 0x140002300,
                                     {parameter(0)});
  HighStmt Spill;
  Spill.Kind = StmtKind::Store;
  Spill.StoreAddr = HighExpr::makeVar(Slot);
  auto CastUndef = std::make_shared<HighExpr>();
  CastUndef->Kind = ExprKind::Cast;
  CastUndef->CastTo = NdType::makeInt(4, true);
  CastUndef->Type = NdType::makeInt(4, true);
  CastUndef->Operands.push_back(HighExpr::makeUndef(4));
  Spill.StoreVal = std::move(CastUndef);
  HighStmt Format;
  Format.Kind = StmtKind::Call;
  Format.CallExpr = HighExpr::makeCall(
      "LookupTextW", 0x140002400,
      {parameter(0), HighExpr::makeLoad(HighExpr::makeVar(Slot),
                                        NdType::makeInt(4))});
  HighStmt Guard;
  Guard.Kind = StmtKind::IfElse;
  Guard.Cond = HighExpr::makeBinop(NdOp::INT_EQUAL, HighExpr::makeVar(View),
                                   HighExpr::makeConst(0, 4));
  Guard.Body = {Regular};
  Guard.ElseBody = {Ctor, Spill, Format};
  Func.Body = {Get, Cmp, Guard};
  invertSkipGotos(Func);
  ASSERT_EQ(Func.Body.size(), 3u);
  ASSERT_EQ(Func.Body[2].Kind, StmtKind::IfElse);
  ASSERT_GE(Func.Body[2].Body.size(), 2u);
  ASSERT_EQ(Func.Body[2].Body[1].Kind, StmtKind::Store);
  ASSERT_TRUE(Func.Body[2].Body[1].StoreVal);
  const auto &Stored = Func.Body[2].Body[1].StoreVal;
  ASSERT_EQ(Stored->Kind, ExprKind::Cast);
  ASSERT_EQ(Stored->Operands.size(), 1u);
  EXPECT_EQ(Stored->Operands[0]->Kind, ExprKind::Undef);
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("GetAdjustmentLevel"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("= 0 /* unknown */"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, CallCondUndefStoreAfterSetupKeepsUnknownValue) {
  HighFunc Func;
  Func.Name = "period_eax";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  MedVar Period;
  Period.Kind = MedVar::Temp;
  Period.Id = 18;
  Period.Size = 4;
  Period.TheArch = Arch::X64;
  HighStmt Get;
  Get.Kind = StmtKind::Assign;
  Get.Dst = HighExpr::makeVar(Period);
  Get.Val = HighExpr::makeCall("GetPeriodID", 0x140002200, {parameter(0)});
  std::vector<HighStmt> Then;
  for (int I = 0; I < 9; ++I) {
    MedVar Slot;
    Slot.Kind = MedVar::Stack;
    Slot.Id = static_cast<unsigned>(40 + I);
    Slot.Size = 8;
    Slot.StackOff = -8 * (I + 1);
    Slot.TheArch = Arch::X64;
    HighStmt Setup;
    Setup.Kind = StmtKind::Store;
    Setup.StoreAddr = HighExpr::makeVar(Slot);
    Setup.StoreVal = HighExpr::makeConst(1, 8);
    Then.push_back(std::move(Setup));
  }
  MedVar Leftover;
  Leftover.Kind = MedVar::Stack;
  Leftover.Id = 88;
  Leftover.Size = 16;
  Leftover.StackOff = -80;
  Leftover.TheArch = Arch::X64;
  HighStmt Spill;
  Spill.Kind = StmtKind::Store;
  Spill.StoreAddr = HighExpr::makeVar(Leftover);
  Spill.StoreVal = HighExpr::makeUndef(16);
  Then.push_back(std::move(Spill));
  HighStmt Use;
  Use.Kind = StmtKind::Call;
  Use.CallExpr = HighExpr::makeCall(
      "LookupTextW", 0x140002400,
      {parameter(0), HighExpr::makeLoad(HighExpr::makeVar(Leftover),
                                        NdType::makeInt(16))});
  Then.push_back(std::move(Use));
  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = HighExpr::makeBinop(NdOp::INT_NOTEQUAL, HighExpr::makeVar(Period),
                                   HighExpr::makeConst(0, 4));
  Guard.Body = std::move(Then);
  Func.Body = {Get, Guard};
  invertSkipGotos(Func);
  ASSERT_EQ(Func.Body.size(), 2u);
  ASSERT_EQ(Func.Body[1].Kind, StmtKind::If);
  ASSERT_GE(Func.Body[1].Body.size(), 10u);
  const HighStmt *UnknownStore = nullptr;
  for (const HighStmt &S : Func.Body[1].Body) {
    if (S.Kind == StmtKind::Store && S.StoreVal &&
        S.StoreVal->Kind == ExprKind::Undef) {
      UnknownStore = &S;
      break;
    }
  }
  ASSERT_TRUE(UnknownStore) << "a prior call does not define an unknown store";
  EXPECT_EQ(UnknownStore->StoreVal->Type->Size, 16u);
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("GetPeriodID"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("= 0 /* unknown */"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, PackedUnknownValueDoesNotAcquirePriorCallResult) {
  HighFunc Func;
  Func.Name = "packed_eax";
  Func.Entry = 0x140001000;
  Func.FrameSize = 256;
  Func.ReturnType = NdType::makeVoid();
  MedVar SP;
  SP.Kind = MedVar::Reg;
  SP.Size = 8;
  SP.TheArch = Arch::X64;
  SP.RegOff = getTargetRegInfo(Arch::X64).StackPointer;
  auto Sp = HighExpr::makeVar(SP, NdType::makeInt(8, false));
  auto First =
      HighExpr::makeBinop(NdOp::INT_SUB, Sp, HighExpr::makeConst(176, 8));
  auto Second =
      HighExpr::makeBinop(NdOp::INT_SUB, Sp, HighExpr::makeConst(160, 8));
  auto Home =
      HighExpr::makeBinop(NdOp::INT_SUB, Sp, HighExpr::makeConst(80, 8));
  auto ArgTy = NdType::makeNamedRecord("ArgList", 16);
  ArgTy->FieldDisplayNames = {"types_", "values_"};
  ArgTy->FieldDisplayOffsets = {0, 8};
  ArgTy->FieldDisplayTypes = {NdType::makeInt(8, false),
                              NdType::makePtr(NdType::makeInt(8))};
  MedVar Period;
  Period.Kind = MedVar::Temp;
  Period.Id = 18;
  Period.Size = 4;
  Period.TheArch = Arch::X64;
  HighStmt Get;
  Get.Kind = StmtKind::Assign;
  Get.Dst = HighExpr::makeVar(Period, NdType::makeInt(4, false));
  Get.Val = HighExpr::makeCall("GetPeriodID", 0x140002200, {parameter(0)});
  HighStmt InitFirst;
  InitFirst.Kind = StmtKind::Store;
  InitFirst.StoreAddr = First;
  InitFirst.StoreVal = HighExpr::makeConst(0, 16);
  InitFirst.StoreVal->Type = ArgTy;
  HighStmt Spill;
  Spill.Kind = StmtKind::Store;
  Spill.StoreAddr = Home;
  Spill.StoreVal = HighExpr::makeUndef(16);
  MedVar T;
  T.Kind = MedVar::Temp;
  T.Id = 116;
  T.SSAVer = 1;
  T.Size = 16;
  T.TheArch = Arch::X64;
  HighStmt LoadHome;
  LoadHome.Kind = StmtKind::Assign;
  LoadHome.Dst = HighExpr::makeVar(T, NdType::makeInt(16));
  LoadHome.Val = HighExpr::makeLoad(Home, NdType::makeInt(16));
  HighStmt Pack;
  Pack.Kind = StmtKind::Store;
  Pack.StoreAddr = Second;
  Pack.StoreVal = HighExpr::makeVar(T, NdType::makeInt(16));
  auto Addr = std::make_shared<HighExpr>();
  Addr->Kind = ExprKind::Addr;
  Addr->Type = NdType::makePtr(ArgTy);
  Addr->Operands.push_back(HighExpr::makeLoad(First, ArgTy));
  HighStmt Use;
  Use.Kind = StmtKind::Call;
  Use.CallExpr = HighExpr::makeCall("LookupTextW", 0x140002000,
                                    {parameter(0), Addr});
  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = HighExpr::makeBinop(NdOp::INT_NOTEQUAL, HighExpr::makeVar(Period),
                                   HighExpr::makeConst(0, 4));
  Guard.Body = {InitFirst, Spill, LoadHome, Pack, Use};
  Func.Body = {Get, Guard};
  invertSkipGotos(Func);
  ASSERT_EQ(Func.Body.size(), 2u);
  ASSERT_EQ(Func.Body[1].Kind, StmtKind::If);
  bool KeptUnknownHome = false;
  unsigned PeriodStores = 0;
  for (const HighStmt &S : Func.Body[1].Body) {
    if (S.Kind != StmtKind::Store || !S.StoreVal)
      continue;
    if (S.StoreVal->Kind == ExprKind::Var && S.StoreVal->Var.Id == Period.Id)
      ++PeriodStores;
    if (S.StoreVal->Kind == ExprKind::Undef && S.StoreAddr &&
        S.StoreAddr->structuralEq(*Home))
      KeptUnknownHome = true;
  }
  EXPECT_TRUE(KeptUnknownHome);
  EXPECT_EQ(PeriodStores, 0u) << "undef has no proven relation to the prior call";
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("PeriodID"), std::string::npos) << Source;
  for (const auto &Store : portableStoreCalls(Source))
    EXPECT_EQ(Store.Value.find("PeriodID"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("unknown register"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("= 0 /* unknown */"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, AddressTakenValuesHomePreservesWideStore) {
  HighFunc Func;
  Func.Name = "values_home";
  Func.Entry = 0x140001000;
  Func.FrameSize = 256;
  Func.ReturnType = NdType::makeVoid();
  MedVar SP;
  SP.Kind = MedVar::Reg;
  SP.Size = 8;
  SP.TheArch = Arch::X64;
  SP.RegOff = getTargetRegInfo(Arch::X64).StackPointer;
  auto Sp = HighExpr::makeVar(SP, NdType::makeInt(8, false));
  auto Home =
      HighExpr::makeBinop(NdOp::INT_SUB, Sp, HighExpr::makeConst(80, 8));
  auto Owner =
      HighExpr::makeBinop(NdOp::INT_SUB, Sp, HighExpr::makeConst(176, 8));
  auto PtrBox = NdType::makeNamedRecord("PtrBox", 16);
  PtrBox->FieldDisplayNames = {"p", "_Ptr", "_Rep"};
  PtrBox->FieldDisplayOffsets = {8, 0, 4};
  PtrBox->FieldDisplayTypes = {NdType::makePtr(NdType::makeInt(8)),
                             NdType::makePtr(NdType::makeInt(8)),
                             NdType::makeInt(4, false)};
  auto ArgTy = NdType::makeNamedRecord("ArgList", 16);
  ArgTy->FieldDisplayNames = {"types_", "values_"};
  ArgTy->FieldDisplayOffsets = {0, 8};
  ArgTy->FieldDisplayTypes = {NdType::makeInt(8, false),
                              NdType::makePtr(NdType::makeInt(8))};
  MedVar Adjustment;
  Adjustment.Kind = MedVar::Temp;
  Adjustment.Id = 115;
  Adjustment.Size = 4;
  Adjustment.TheArch = Arch::X64;
  HighStmt Get;
  Get.Kind = StmtKind::Assign;
  Get.Dst = HighExpr::makeVar(Adjustment, NdType::makeInt(4, false));
  Get.Val = HighExpr::makeCall("GetAdjustmentLevel", 0x140002200, {parameter(0)});
  HighStmt InitOwner;
  InitOwner.Kind = StmtKind::Store;
  InitOwner.StoreAddr = Owner;
  InitOwner.StoreVal = HighExpr::makeConst(0, 16);
  InitOwner.StoreVal->Type = PtrBox;
  HighStmt Fill;
  Fill.Kind = StmtKind::Store;
  Fill.StoreAddr = Home;
  Fill.StoreVal = HighExpr::makeVar(Adjustment, NdType::makeInt(16));
  auto HomeAddr = std::make_shared<HighExpr>();
  HomeAddr->Kind = ExprKind::Addr;
  HomeAddr->Type = NdType::makePtr(NdType::makeInt(16));
  HomeAddr->Operands.push_back(HighExpr::makeLoad(Home, NdType::makeInt(16)));
  HighStmt Values;
  Values.Kind = StmtKind::Store;
  Values.StoreAddr =
      HighExpr::makeBinop(NdOp::INT_ADD, Owner, HighExpr::makeConst(8, 8));
  Values.StoreVal = HomeAddr;
  HighStmt Types;
  Types.Kind = StmtKind::Store;
  Types.StoreAddr = Owner;
  Types.StoreVal = HighExpr::makeConst(178, 8);
  auto Args = std::make_shared<HighExpr>();
  Args->Kind = ExprKind::Addr;
  Args->Type = NdType::makePtr(ArgTy);
  Args->Operands.push_back(HighExpr::makeLoad(Owner, PtrBox));
  HighStmt Use;
  Use.Kind = StmtKind::Call;
  Use.CallExpr = HighExpr::makeCall("LookupTextW", 0x140002000,
                                    {parameter(0), HighExpr::makeConst(0, 8),
                                     Args});
  Func.Body = {Get, InitOwner, Fill, Values, Types, Use};
  class CalleeDbg : public NullDebugContext {
  public:
    TypeRef Arg;
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140002000)
        return std::nullopt;
      FunctionSym FS;
      FS.Name = "LookupTextW";
      FS.Addr = Addr;
      FS.ReturnType = NdType::makeVoid();
      FS.Params.emplace_back("result", NdType::makePtr());
      FS.Params.emplace_back("key", NdType::makePtr());
      FS.Params.emplace_back("args", NdType::makePtr(Arg));
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;
  Dbg.Arg = ArgTy;
  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  ASSERT_TRUE(HighCEmitter().emit({Func}, OS, Options, &Dbg));
  OS.flush();
  expectPortableStore(Source, "__int128", "frame_base) - 80", "AdjustmentLevel");
  EXPECT_EQ(Source.find("unknown register"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, CallCondUndefStoreInsideCxxTryKeepsUnknownValue) {
  HighFunc Func;
  Func.Name = "period_try_eax";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  MedVar Period;
  Period.Kind = MedVar::Temp;
  Period.Id = 67;
  Period.Size = 4;
  Period.TheArch = Arch::X64;
  HighStmt Get;
  Get.Kind = StmtKind::Assign;
  Get.Dst = HighExpr::makeVar(Period);
  Get.Val = HighExpr::makeCall("GetPeriodID", 0x140002200, {parameter(0)});
  HighStmt Ctor;
  Ctor.Kind = StmtKind::Call;
  Ctor.CallExpr = HighExpr::makeCall("CStringT_ctor", 0x140002300,
                                     {parameter(0)});
  MedVar Leftover;
  Leftover.Kind = MedVar::Stack;
  Leftover.Id = 88;
  Leftover.Size = 16;
  Leftover.StackOff = -80;
  Leftover.TheArch = Arch::X64;
  HighStmt Spill;
  Spill.Kind = StmtKind::Store;
  Spill.StoreAddr = HighExpr::makeVar(Leftover);
  Spill.StoreVal = HighExpr::makeUndef(8);
  HighStmt Use;
  Use.Kind = StmtKind::Call;
  Use.CallExpr = HighExpr::makeCall(
      "LookupTextW", 0x140002400,
      {parameter(0), HighExpr::makeLoad(HighExpr::makeVar(Leftover),
                                        NdType::makeInt(8))});
  HighStmt Try;
  Try.Kind = StmtKind::CxxTry;
  Try.EHIsReducible = true;
  Try.Body = {Spill, Use};
  HighEHClause Cleanup;
  Cleanup.Kind = HighEHClauseKind::CxxCleanup;
  Try.EHClauses.push_back(Cleanup);
  Try.EHClauseBodies.emplace_back();
  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = HighExpr::makeBinop(NdOp::INT_NOTEQUAL, HighExpr::makeVar(Period),
                                   HighExpr::makeConst(0, 4));
  Guard.Body = {Ctor, Try};
  Func.Body = {Get, Guard};
  invertSkipGotos(Func);
  ASSERT_EQ(Func.Body.size(), 2u);
  ASSERT_EQ(Func.Body[1].Kind, StmtKind::If);
  ASSERT_GE(Func.Body[1].Body.size(), 2u);
  ASSERT_EQ(Func.Body[1].Body[1].Kind, StmtKind::CxxTry);
  ASSERT_FALSE(Func.Body[1].Body[1].Body.empty());
  ASSERT_EQ(Func.Body[1].Body[1].Body[0].Kind, StmtKind::Store);
  ASSERT_TRUE(Func.Body[1].Body[1].Body[0].StoreVal);
  EXPECT_EQ(Func.Body[1].Body[1].Body[0].StoreVal->Kind, ExprKind::Undef);
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("GetPeriodID"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("= 0 /* unknown */"), std::string::npos) << Source;
}

