TEST(HighCPointerAddresses, GuardedNullReturnIndirectCallUsesGuardThis) {
  auto Holder = NdType::makeNamedRecord("PtrBox", 8);
  Holder->FieldDisplayNames = {"p"};
  Holder->FieldDisplayOffsets = {0};
  auto Record = NdType::makeNamedRecord("CRecordBadge", 264);
  Record->FieldDisplayNames = {"m_pBadge"};
  Record->FieldDisplayOffsets = {256};
  Record->FieldDisplayTypes = {Holder};
  auto Str = NdType::makeNamedRecord("CStringT", 8);
  HighFunc Func;
  Func.Name = "GetDisplayName";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makePtr(Str);
  Func.Params = {{"this", NdType::makePtr(Record)},
                 {"result", NdType::makePtr(Str)}};
  auto Badge = HighExpr::makeLoad(
      HighExpr::makeBinop(NdOp::INT_ADD, parameter(0, Func.Params[0].Type),
                          HighExpr::makeConst(256, 8)),
      NdType::makeInt(8));
  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = HighExpr::makeBinop(NdOp::INT_EQUAL, Badge,
                                   HighExpr::makeConst(0, 8));
  HighStmt Ctor;
  Ctor.Kind = StmtKind::Call;
  Ctor.CallExpr = HighExpr::makeCall(
      "CStringT_ctor", 0x140002000,
      {parameter(1, Func.Params[1].Type), HighExpr::makeConst(0, 8)});
  HighStmt Early;
  Early.Kind = StmtKind::Return;
  Early.RetVal = parameter(1, Func.Params[1].Type);
  Guard.Body = {Ctor, Early};
  auto Vtbl = HighExpr::makeLoad(Badge, NdType::makeInt(8));
  HighStmt Display;
  Display.Kind = StmtKind::Call;
  Display.CallExpr = HighExpr::makeCall(
      "indirect", 0,
      {parameter(0, Func.Params[0].Type), parameter(1, Func.Params[1].Type)});
  Display.CallExpr->IsIndirectCall = true;
  Display.CallExpr->IndirectTarget = HighExpr::makeLoad(
      HighExpr::makeBinop(NdOp::INT_ADD, Vtbl, HighExpr::makeConst(88, 8)),
      NdType::makePtr());
  HighStmt Ret;
  Ret.Kind = StmtKind::Return;
  Ret.RetVal = parameter(1, Func.Params[1].Type);
  Func.Body = {Guard, Display, Ret};
  invertSkipGotos(Func);
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("if (this->m_pBadge.p == 0)"), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("(*(void **)((uintptr_t)(*(void **)(this->m_pBadge.p)) + "
                        "88))(this->m_pBadge.p,"),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("result)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("this->m_pBadge.p->p"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("*(int64_t *)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("((uintptr_t)this,"), std::string::npos) << Source;
}

