TEST(HighCPointerAddresses, UnusedCallAliasesUndeclaredStore) {
  HighFunc Func;
  Func.Name = "alias_len";
  Func.ReturnType = NdType::makeInt(8);
  Func.Params = {{"arg0", NdType::makeInt(8)}};
  Func.FrameSize = 16;
  MedVar Dest;
  Dest.Kind = MedVar::Temp;
  Dest.Id = 1;
  Dest.Size = 4;
  Dest.TheArch = Arch::X64;
  HighStmt Call;
  Call.Kind = StmtKind::Assign;
  Call.Dst = HighExpr::makeVar(Dest, NdType::makeInt(4));
  Call.Val = HighExpr::makeCall("GetLength", 0x140002000,
                                {parameter(0, NdType::makeInt(8))});
  MedVar SP;
  SP.Kind = MedVar::Reg;
  SP.Size = 8;
  SP.TheArch = Arch::X64;
  SP.RegOff = getTargetRegInfo(Arch::X64).StackPointer;
  MedVar Ghost;
  Ghost.Kind = MedVar::Reg;
  Ghost.Id = 0;
  Ghost.Size = 8;
  Ghost.RegOff = 0;
  Ghost.RenameTag = 99;
  Ghost.TheArch = Arch::X64;
  auto SlotAddr = HighExpr::makeBinop(
      NdOp::INT_SUB, HighExpr::makeVar(SP, NdType::makeInt(8, false)),
      HighExpr::makeConst(8, 8));
  HighStmt Store;
  Store.Kind = StmtKind::Store;
  Store.StoreAddr = SlotAddr;
  Store.StoreVal = HighExpr::makeUnary(
      NdOp::INT_ZEXT, HighExpr::makeVar(Ghost, NdType::makeInt(4)));
  HighStmt Ret;
  Ret.Kind = StmtKind::Return;
  Ret.RetVal = HighExpr::makeLoad(SlotAddr, NdType::makeInt(8));
  Func.Body = {Call, Store, Ret};
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("= GetLength(arg0)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("\n    GetLength(arg0);"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("v99"), std::string::npos) << Source;
}

