TEST(LLVMCPointerAddresses, AssignsPhiAtPredecessorEdges) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-phi", Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(I32, {llvm::Type::getInt1Ty(Context)}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "join", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Left = llvm::BasicBlock::Create(Context, "left", Function);
  llvm::BasicBlock *Right =
      llvm::BasicBlock::Create(Context, "right", Function);
  llvm::BasicBlock *Join = llvm::BasicBlock::Create(Context, "join", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  EntryBuilder.CreateCondBr(Function->getArg(0), Left, Right);
  llvm::IRBuilder<> LeftBuilder(Left);
  LeftBuilder.CreateBr(Join);
  llvm::IRBuilder<> RightBuilder(Right);
  RightBuilder.CreateBr(Join);
  llvm::IRBuilder<> JoinBuilder(Join);
  llvm::PHINode *Phi = JoinBuilder.CreatePHI(I32, 2, "joined");
  Phi->addIncoming(llvm::ConstantInt::get(I32, 1), Left);
  Phi->addIncoming(llvm::ConstantInt::get(I32, 2), Right);
  JoinBuilder.CreateRet(Phi);

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  EXPECT_NE(Source.find("joined"), std::string::npos) << Source;
  EXPECT_NE(Source.find(" = 1;"), std::string::npos) << Source;
  EXPECT_NE(Source.find(" = 2;"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("/* phi:"), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, RegisterCopyIntoOneStoreIsNotPrinted) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-reg-copy-one-store", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "save_regs", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Body = llvm::BasicBlock::Create(Context, "body", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  auto *RBX = EntryBuilder.CreateAlloca(I64, nullptr, "RBX");
  auto *RSI = EntryBuilder.CreateAlloca(I64, nullptr, "RSI");
  EntryBuilder.CreateStore(llvm::ConstantInt::get(I64, 0), RBX);
  EntryBuilder.CreateStore(llvm::ConstantInt::get(I64, 0), RSI);
  EntryBuilder.CreateBr(Body);

  llvm::IRBuilder<> Builder(Body);
  llvm::Value *RBXCopied = Builder.CreateLoad(I64, RBX, "RBX_v");
  Builder.CreateStore(RBXCopied, RBX);
  llvm::Value *RBXReload = Builder.CreateLoad(I64, RBX, "RBX_v7");
  llvm::Value *Field = Builder.CreateIntToPtr(
      Builder.CreateAdd(Builder.CreatePtrToInt(Function->getArg(0), I64),
                        llvm::ConstantInt::get(I64, 8)),
      Ptr);
  Builder.CreateStore(RBXReload, Field);
  llvm::Value *RSICopied = Builder.CreateLoad(I64, RSI, "RSI_v");
  Builder.CreateStore(RSICopied, RSI);
  llvm::Value *RSIReload = Builder.CreateLoad(I64, RSI, "RSI_v11");
  llvm::Value *Frame = Builder.CreateIntToPtr(
      Builder.CreateAdd(Builder.CreatePtrToInt(Function->getArg(0), I64),
                        llvm::ConstantInt::get(I64, 104)),
      Ptr);
  Builder.CreateStore(RSIReload, Frame);
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("save_regs(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto RbxCopy = Source.find("RBX_v", BodyAt);
  const auto RsiCopy = Source.find("RSI_v", BodyAt);
  const auto ZeroAt = Source.find("= 0;", BodyAt);
  EXPECT_EQ(RbxCopy, std::string::npos) << Source;
  EXPECT_EQ(RsiCopy, std::string::npos) << Source;
  EXPECT_NE(ZeroAt, std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, RegisterChainArgListValuesStoreUsesField) {
  auto ArgTy = NdType::makeNamedRecord("ArgList", 16);
  class ChainDbg : public NullDebugContext {
  public:
    TypeRef ArgListTy;
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140002000)
        return std::nullopt;
      FunctionSym FS;
      FS.Name = "StringUtil_FormatW";
      FS.Addr = Addr;
      FS.ReturnType = NdType::makeInt(8, false);
      FS.Params.emplace_back("result", NdType::makePtr());
      FS.Params.emplace_back("fmt", NdType::makePtr());
      FS.Params.emplace_back("args", NdType::makePtr(ArgListTy));
      return FS;
    }
    std::optional<VariableSym> resolveVariable(va_t FuncAddr,
                                               int64_t Disp) const override {
      if (FuncAddr != 0x140001000 || Disp != -24)
        return std::nullopt;
      VariableSym Var;
      Var.Name = "var_m18";
      Var.Type = NdType::makeInt(8, false);
      Var.StackOffset = Disp;
      return Var;
    }
    bool hasInfo() const override { return true; }
  } Dbg;
  Dbg.ArgListTy = ArgTy;

  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-arglist-reg-chain", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *FmtTy =
      llvm::FunctionType::get(I64, {Ptr, Ptr, I64}, false);
  llvm::Function *Fmt = llvm::Function::Create(
      FmtTy, llvm::GlobalValue::ExternalLinkage, "StringUtil_FormatW", Module);
  rewrite_source::setOriginalVA(*Fmt, 0x140002000);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(I64, {Ptr, Ptr}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "format_chain", Module);
  rewrite_source::setOriginalVA(*Function, 0x140001000);
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  auto *Frame = Builder.CreateAlloca(llvm::ArrayType::get(I8, 168), nullptr,
                                     "frame");
  auto *End = Builder.CreateInBoundsGEP(
      I8, Frame, llvm::ConstantInt::get(I64, 88), "frame_end");
  auto *RSP = Builder.CreateAlloca(I64, nullptr, "RSP");
  auto *RSP1 = Builder.CreateAlloca(I64, nullptr, "RSP1");
  auto *RSP2 = Builder.CreateAlloca(I64, nullptr, "RSP2");
  auto *Slot48 = Builder.CreateAlloca(I64, nullptr, "slot48");
  auto *Slot56 = Builder.CreateAlloca(I64, nullptr, "slot56");
  auto *Slot64 = Builder.CreateAlloca(I64, nullptr, "slot64");
  Builder.CreateStore(Builder.CreatePtrToInt(End, I64, "rsp_init"), RSP);
  Builder.CreateStore(
      Builder.CreateSub(Builder.CreateLoad(I64, RSP),
                        llvm::ConstantInt::get(I64, 8)),
      RSP1);
  Builder.CreateStore(
      Builder.CreateSub(Builder.CreateLoad(I64, RSP1),
                        llvm::ConstantInt::get(I64, 64)),
      RSP2);
  Builder.CreateStore(
      Builder.CreateAdd(Builder.CreateLoad(I64, RSP2),
                        llvm::ConstantInt::get(I64, 32)),
      Slot48);
  Builder.CreateStore(
      Builder.CreateAdd(Builder.CreateLoad(I64, RSP2),
                        llvm::ConstantInt::get(I64, 40)),
      Slot56);
  Builder.CreateStore(
      Builder.CreateAdd(Builder.CreateLoad(I64, RSP2),
                        llvm::ConstantInt::get(I64, 48)),
      Slot64);
  Builder.CreateStore(llvm::ConstantInt::get(I64, 2),
                      Builder.CreateIntToPtr(Builder.CreateLoad(I64, Slot48),
                                             Ptr));
  Builder.CreateStore(Builder.CreateLoad(I64, Slot64),
                      Builder.CreateIntToPtr(Builder.CreateLoad(I64, Slot56),
                                             Ptr));
  Builder.CreateCall(Fmt, {Function->getArg(0), Function->getArg(1),
                           Builder.CreateLoad(I64, Slot48)});
  Builder.CreateRet(Builder.CreateLoad(I64, Slot48));

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr,
                                  Function));
  OS.flush();
  const auto BodyAt = Source.find("format_chain(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  EXPECT_NE(Source.find("var_m28.types_ = 2"), BodyAt) << Source;
  EXPECT_NE(Source.find("var_m28.values_ = &var_m18"), BodyAt) << Source;
  EXPECT_EQ(Source.find("(char*)&frame"), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses,
     NarrowStoreIntoArgListBeforeWideCopyPreservesWidth) {
  auto ArgTy = NdType::makeNamedRecord("ArgList", 16);
  class ArgListDbg : public NullDebugContext {
  public:
    TypeRef ArgListTy;
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140002000)
        return std::nullopt;
      FunctionSym FS;
      FS.Name = "StringUtil_FormatW";
      FS.Addr = Addr;
      FS.ReturnType = NdType::makeVoid();
      FS.Params.emplace_back("result", NdType::makePtr());
      FS.Params.emplace_back("fmt", NdType::makePtr());
      FS.Params.emplace_back("args", NdType::makePtr(ArgListTy));
      return FS;
    }
    std::optional<VariableSym> resolveVariable(va_t FuncAddr,
                                               int64_t Disp) const override {
      if (FuncAddr != 0x140001000 || (Disp != -40 && Disp != -24))
        return std::nullopt;
      VariableSym Var;
      Var.Name = Disp == -40 ? "var_m28" : "var_m18";
      Var.Type = ArgListTy;
      Var.StackOffset = Disp;
      return Var;
    }
    bool hasInfo() const override { return true; }
  } Dbg;
  Dbg.ArgListTy = ArgTy;

  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-arglist-narrow-before-copy", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *I128 = llvm::Type::getInt128Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *FmtTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context),
                              {Ptr, Ptr, I64}, false);
  llvm::Function *Fmt = llvm::Function::Create(
      FmtTy, llvm::GlobalValue::ExternalLinkage, "StringUtil_FormatW", Module);
  rewrite_source::setOriginalVA(*Fmt, 0x140002000);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context),
                              {Ptr, Ptr, I32}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "format_narrow_color", Module);
  rewrite_source::setOriginalVA(*Function, 0x140001000);
  Function->getArg(2)->setName("color");
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  auto *Frame = Builder.CreateAlloca(llvm::ArrayType::get(I8, 168), nullptr,
                                     "frame");
  auto *End = Builder.CreateInBoundsGEP(
      I8, Frame, llvm::ConstantInt::get(I64, 88), "frame_end");
  auto *RSP = Builder.CreateAlloca(I64, nullptr, "RSP");
  auto *RSP1 = Builder.CreateAlloca(I64, nullptr, "RSP1");
  auto *RSP2 = Builder.CreateAlloca(I64, nullptr, "RSP2");
  Builder.CreateStore(Builder.CreatePtrToInt(End, I64), RSP);
  Builder.CreateStore(
      Builder.CreateSub(Builder.CreateLoad(I64, RSP),
                        llvm::ConstantInt::get(I64, 8)),
      RSP1);
  Builder.CreateStore(
      Builder.CreateSub(Builder.CreateLoad(I64, RSP1),
                        llvm::ConstantInt::get(I64, 64)),
      RSP2);
  auto *Slot48 = Builder.CreateAdd(Builder.CreateLoad(I64, RSP2),
                                   llvm::ConstantInt::get(I64, 32));
  auto *Slot56 = Builder.CreateAdd(Builder.CreateLoad(I64, RSP2),
                                   llvm::ConstantInt::get(I64, 40));
  auto *Slot64 = Builder.CreateAdd(Builder.CreateLoad(I64, RSP2),
                                   llvm::ConstantInt::get(I64, 48));
  Builder.CreateStore(Function->getArg(2), Builder.CreateIntToPtr(Slot48, Ptr));
  Builder.CreateStore(
      Builder.CreateLoad(I128, Builder.CreateIntToPtr(Slot48, Ptr)),
      Builder.CreateIntToPtr(Slot64, Ptr));
  Builder.CreateStore(llvm::ConstantInt::get(I64, 2),
                      Builder.CreateIntToPtr(Slot48, Ptr));
  Builder.CreateStore(Slot64, Builder.CreateIntToPtr(Slot56, Ptr));
  Builder.CreateCall(Fmt, {Function->getArg(0), Function->getArg(1), Slot48});
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr,
                                  Function));
  OS.flush();
  EXPECT_NE(Source.find("ArgList var_m28;"), std::string::npos) << Source;
  EXPECT_NE(Source.find("*(uint32_t *)&var_m28 = color;"), std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("\n    var_m28 = color;"), std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("\n    var_m28.types_ = color;"), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("var_m18 = var_m28;"), std::string::npos) << Source;
  EXPECT_NE(Source.find("var_m28.types_ = 2;"), std::string::npos) << Source;
  EXPECT_NE(Source.find("var_m28.values_ = &var_m18;"), std::string::npos)
      << Source;
}

TEST(LLVMCPointerAddresses, ZeroPastEightByteCallArgumentIsOmitted) {
  auto StrTy = NdType::makeNamedRecord("CStringT", 8);
  auto ArgTy = NdType::makeNamedRecord("ArgList", 16);
  class PastDbg : public NullDebugContext {
  public:
    TypeRef Str;
    TypeRef ArgListTy;
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr == 0x140002000) {
        FunctionSym FS;
        FS.Name = "fill_string";
        FS.Addr = Addr;
        FS.ReturnType = NdType::makeVoid();
        FS.Params.emplace_back("out", NdType::makePtr(Str));
        return FS;
      }
      if (Addr != 0x140002100)
        return std::nullopt;
      FunctionSym FS;
      FS.Name = "use_args";
      FS.Addr = Addr;
      FS.ReturnType = NdType::makeVoid();
      FS.Params.emplace_back("args", NdType::makePtr(ArgListTy));
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;
  Dbg.Str = StrTy;
  Dbg.ArgListTy = ArgTy;

  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-zero-past-string", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *FillTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Fill = llvm::Function::Create(
      FillTy, llvm::GlobalValue::ExternalLinkage, "fill_string", Module);
  rewrite_source::setOriginalVA(*Fill, 0x140002000);
  llvm::FunctionType *UseTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Use = llvm::Function::Create(
      UseTy, llvm::GlobalValue::ExternalLinkage, "use_args", Module);
  rewrite_source::setOriginalVA(*Use, 0x140002100);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "spill_past_string", Module);
  rewrite_source::setOriginalVA(*Function, 0x140001000);
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  auto *Frame = Builder.CreateAlloca(llvm::ArrayType::get(I8, 128), nullptr,
                                     "frame");
  auto *End = Builder.CreateInBoundsGEP(
      I8, Frame, llvm::ConstantInt::get(I64, 80), "frame_end");
  llvm::Value *Rsp = Builder.CreatePtrToInt(End, I64, "rsp_init");
  llvm::Value *StrSlot =
      Builder.CreateSub(Rsp, llvm::ConstantInt::get(I64, 32));
  llvm::Value *Past =
      Builder.CreateAdd(StrSlot, llvm::ConstantInt::get(I64, 8));
  llvm::Value *Pack =
      Builder.CreateSub(Rsp, llvm::ConstantInt::get(I64, 64));
  llvm::Value *Vals =
      Builder.CreateAdd(Pack, llvm::ConstantInt::get(I64, 8));
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0),
                      Builder.CreateIntToPtr(Past, Ptr));
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0),
                      Builder.CreateIntToPtr(Vals, Ptr));
  Builder.CreateCall(Fill, {Builder.CreateIntToPtr(StrSlot, Ptr)});
  Builder.CreateCall(Use, {Builder.CreateIntToPtr(Pack, Ptr)});
  Builder.CreateRetVoid();

  llvm::Function *Kept = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "keep_past_string", Module);
  rewrite_source::setOriginalVA(*Kept, 0x140001100);
  llvm::IRBuilder<> KeptBuilder(
      llvm::BasicBlock::Create(Context, "entry", Kept));
  auto *KeptFrame = KeptBuilder.CreateAlloca(
      llvm::ArrayType::get(I8, 128), nullptr, "frame");
  auto *KeptEnd = KeptBuilder.CreateInBoundsGEP(
      I8, KeptFrame, llvm::ConstantInt::get(I64, 80), "frame_end");
  llvm::Value *KeptRsp = KeptBuilder.CreatePtrToInt(KeptEnd, I64, "rsp_init");
  llvm::Value *KeptStr =
      KeptBuilder.CreateSub(KeptRsp, llvm::ConstantInt::get(I64, 32));
  llvm::Value *KeptPast =
      KeptBuilder.CreateAdd(KeptStr, llvm::ConstantInt::get(I64, 8));
  KeptBuilder.CreateStore(llvm::ConstantInt::get(I64, 9),
                          KeptBuilder.CreateIntToPtr(KeptPast, Ptr));
  KeptBuilder.CreateCall(Fill, {KeptBuilder.CreateIntToPtr(KeptStr, Ptr)});
  KeptBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr,
                                  nullptr));
  OS.flush();
  const auto BodyAt = Source.find("spill_past_string(");
  const auto KeptAt = Source.find("keep_past_string(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  ASSERT_NE(KeptAt, std::string::npos) << Source;
  const std::string ZeroFn = Source.substr(BodyAt, KeptAt - BodyAt);
  const std::string KeptFn = Source.substr(KeptAt);
  EXPECT_NE(ZeroFn.find("values_ = 0"), std::string::npos) << Source;
  EXPECT_NE(ZeroFn.find("fill_string("), std::string::npos) << Source;
  EXPECT_EQ(ZeroFn.find("+ 56"), std::string::npos) << Source;
  EXPECT_NE(KeptFn.find("= 9"), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, DropsDeclarationWithNoPrintedUse) {
  // The edge load sees an immediate in the slot, so it is not forwarded and
  // is declared. A later store of the argument keeps the slot from folding
  // away. The edge itself is not printed, and the unread multiply stays.
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-orphan-decl", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(I64, {I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "orphan_decl", Module);
  llvm::BasicBlock *Entry = llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Edge = llvm::BasicBlock::Create(Context, "edge", Function);
  llvm::BasicBlock *Later = llvm::BasicBlock::Create(Context, "later", Function);
  llvm::IRBuilder<> Builder(Entry);
  auto *Home = Builder.CreateAlloca(I64, nullptr, "RAX.5");
  auto *Copy = Builder.CreateAlloca(I64, nullptr, "RAX.4");
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), Home);
  Builder.CreateStore(Function->getArg(0), Copy);
  Builder.CreateBr(Edge);
  Builder.SetInsertPoint(Edge);
  Builder.CreateStore(Builder.CreateLoad(I64, Home, "RAX.5_v"), Copy);
  Builder.CreateBr(Later);
  Builder.SetInsertPoint(Later);
  // A non-parameter value keeps the slot out of the named-parameter home
  // rule, so the edge load is still declared.
  llvm::Value *Mixed = Builder.CreateAdd(
      Function->getArg(0), llvm::ConstantInt::get(I64, 1), "mixed");
  Builder.CreateStore(Mixed, Home);
  Builder.CreateMul(Function->getArg(0), llvm::ConstantInt::get(I64, 3),
                    "dead_flag");
  Builder.CreateRet(Builder.CreateLoad(I64, Copy, "copied"));

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  EXPECT_EQ(Source.find("RAX_5_v"), std::string::npos) << Source;
  EXPECT_NE(Source.find("dead_flag"), std::string::npos) << Source;
  EXPECT_NE(Source.find("* 3"), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, OmitsNestedPointerTestImpliedByOuter) {
  // if (p) { if (flag) { if (p) dtor(); } }
  // The inner pointer test repeats the outer one and nothing stores p.
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-implied-ptr", Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Dtor = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "dtor", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {I64, I32}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "implied_ptr", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Have = llvm::BasicBlock::Create(Context, "have", Function);
  llvm::BasicBlock *Gate = llvm::BasicBlock::Create(Context, "gate", Function);
  llvm::BasicBlock *Release =
      llvm::BasicBlock::Create(Context, "release", Function);
  llvm::BasicBlock *Done = llvm::BasicBlock::Create(Context, "done", Function);
  llvm::IRBuilder<> Builder(Entry);
  auto *Slot = Builder.CreateAlloca(I64, nullptr, "p");
  Builder.CreateStore(Function->getArg(0), Slot);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(Builder.CreateLoad(I64, Slot),
                           llvm::ConstantInt::get(I64, 0)),
      Have, Done);
  Builder.SetInsertPoint(Have);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(Function->getArg(1), llvm::ConstantInt::get(I32, 0)),
      Gate, Done);
  Builder.SetInsertPoint(Gate);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(Builder.CreateLoad(I64, Slot),
                           llvm::ConstantInt::get(I64, 0)),
      Release, Done);
  Builder.SetInsertPoint(Release);
  Builder.CreateCall(Dtor);
  Builder.CreateBr(Done);
  Builder.SetInsertPoint(Done);
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("void implied_ptr(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const std::string Body = Source.substr(BodyAt);
  EXPECT_NE(Body.find("dtor("), std::string::npos) << Source;
  size_t IfCount = 0;
  for (size_t Pos = 0; (Pos = Body.find("if (", Pos)) != std::string::npos;
       Pos += 4)
    ++IfCount;
  EXPECT_EQ(IfCount, 2u) << Source;
}

TEST(LLVMCPointerAddresses, OmitsNestedFlagPointerTestImpliedByOuter) {
  // The branch reloads a flag that was set from `p == 0`, then tests p again
  // through a second flag. Nothing stores p between the two tests.
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-implied-flag", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Dtor = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "dtor", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "implied_flag", Module);
  auto FlagBr = [&](llvm::IRBuilder<> &Builder, llvm::Value *Slot,
                    llvm::Value *Flag, llvm::BasicBlock *TakenOnZero,
                    llvm::BasicBlock *TakenOnNonZero) {
    llvm::Value *Eq = Builder.CreateICmpEQ(Builder.CreateLoad(I64, Slot),
                                           llvm::ConstantInt::get(I64, 0));
    Builder.CreateStore(Builder.CreateZExt(Eq, I8), Flag);
    Builder.CreateCondBr(
        Builder.CreateICmpNE(Builder.CreateLoad(I8, Flag),
                             llvm::ConstantInt::get(I8, 0)),
        TakenOnZero, TakenOnNonZero);
  };
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Have = llvm::BasicBlock::Create(Context, "have", Function);
  llvm::BasicBlock *Release =
      llvm::BasicBlock::Create(Context, "release", Function);
  llvm::BasicBlock *Done = llvm::BasicBlock::Create(Context, "done", Function);
  llvm::IRBuilder<> Builder(Entry);
  auto *Slot = Builder.CreateAlloca(I64, nullptr, "p");
  auto *Flag = Builder.CreateAlloca(I8, nullptr, "ZF");
  auto *Flag2 = Builder.CreateAlloca(I8, nullptr, "ZF2");
  Builder.CreateStore(Function->getArg(0), Slot);
  FlagBr(Builder, Slot, Flag, Done, Have);
  Builder.SetInsertPoint(Have);
  FlagBr(Builder, Slot, Flag2, Done, Release);
  Builder.SetInsertPoint(Release);
  Builder.CreateCall(Dtor);
  Builder.CreateBr(Done);
  Builder.SetInsertPoint(Done);
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("void implied_flag(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const std::string Body = Source.substr(BodyAt);
  EXPECT_NE(Body.find("dtor("), std::string::npos) << Source;
  size_t IfCount = 0;
  for (size_t Pos = 0; (Pos = Body.find("if (", Pos)) != std::string::npos;
       Pos += 4)
    ++IfCount;
  EXPECT_EQ(IfCount, 1u) << Source;
}

TEST(LLVMCPointerAddresses, OmitsPointerRetestAfterConjunct) {
  // if (p && IsKind(p)) { if (p) dtor(); }
  // The inner pointer test repeats the conjunct. IsKind stays.
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-implied-and", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *KindTy = llvm::FunctionType::get(I32, {Ptr}, false);
  llvm::Function *IsKind = llvm::Function::Create(
      KindTy, llvm::GlobalValue::ExternalLinkage, "IsKind", Module);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Dtor = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "dtor", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "implied_and", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Kind = llvm::BasicBlock::Create(Context, "kind", Function);
  llvm::BasicBlock *Retest =
      llvm::BasicBlock::Create(Context, "retest", Function);
  llvm::BasicBlock *Body = llvm::BasicBlock::Create(Context, "body", Function);
  llvm::BasicBlock *Done = llvm::BasicBlock::Create(Context, "done", Function);
  llvm::IRBuilder<> Builder(Entry);
  auto *Slot = Builder.CreateAlloca(I64, nullptr, "p");
  auto *Flag = Builder.CreateAlloca(I8, nullptr, "ZF");
  auto *Flag2 = Builder.CreateAlloca(I8, nullptr, "ZF2");
  Builder.CreateStore(Function->getArg(0), Slot);
  llvm::Value *Eq = Builder.CreateICmpEQ(Builder.CreateLoad(I64, Slot),
                                         llvm::ConstantInt::get(I64, 0));
  Builder.CreateStore(Builder.CreateZExt(Eq, I8), Flag);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(Builder.CreateLoad(I8, Flag),
                           llvm::ConstantInt::get(I8, 0)),
      Done, Kind);
  Builder.SetInsertPoint(Kind);
  llvm::Value *Called = Builder.CreateCall(
      IsKind, {Builder.CreateIntToPtr(Builder.CreateLoad(I64, Slot), Ptr)});
  Builder.CreateCondBr(
      Builder.CreateICmpNE(Called, llvm::ConstantInt::get(I32, 0)), Retest,
      Done);
  Builder.SetInsertPoint(Retest);
  llvm::Value *Eq2 = Builder.CreateICmpEQ(Builder.CreateLoad(I64, Slot),
                                          llvm::ConstantInt::get(I64, 0));
  Builder.CreateStore(Builder.CreateZExt(Eq2, I8), Flag2);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(Builder.CreateLoad(I8, Flag2),
                           llvm::ConstantInt::get(I8, 0)),
      Done, Body);
  Builder.SetInsertPoint(Body);
  Builder.CreateCall(Dtor);
  Builder.CreateBr(Done);
  Builder.SetInsertPoint(Done);
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("void implied_and(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const std::string Fn = Source.substr(BodyAt);
  EXPECT_NE(Fn.find("IsKind("), std::string::npos) << Source;
  EXPECT_NE(Fn.find("dtor("), std::string::npos) << Source;
  size_t IfCount = 0;
  for (size_t Pos = 0; (Pos = Fn.find("if (", Pos)) != std::string::npos;
       Pos += 4)
    ++IfCount;
  EXPECT_EQ(IfCount, 2u) << Source;
}

TEST(LLVMCPointerAddresses, OmitsReloadedFieldPointerTest) {
  // An else-if arm tests *(self+8), calls IsKind, then tests that field
  // again through another address temp. The second test's other edge is
  // empty. Both IsKind calls stay. The reloaded test does not.
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-reloaded-field", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *KindTy = llvm::FunctionType::get(I32, {Ptr}, false);
  llvm::Function *IsKind = llvm::Function::Create(
      KindTy, llvm::GlobalValue::ExternalLinkage, "IsKind", Module);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Use = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "use_field", Module);
  llvm::Function *Other = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "other_step", Module);
  llvm::Function *Tail = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "tail_step", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {I64, I32}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "reloaded_field", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Kind = llvm::BasicBlock::Create(Context, "kind", Function);
  llvm::BasicBlock *Retest =
      llvm::BasicBlock::Create(Context, "retest", Function);
  llvm::BasicBlock *Skip = llvm::BasicBlock::Create(Context, "skip", Function);
  llvm::BasicBlock *Again =
      llvm::BasicBlock::Create(Context, "again", Function);
  llvm::BasicBlock *Body = llvm::BasicBlock::Create(Context, "body", Function);
  llvm::BasicBlock *Join = llvm::BasicBlock::Create(Context, "join", Function);
  llvm::BasicBlock *OtherBB =
      llvm::BasicBlock::Create(Context, "other", Function);
  llvm::IRBuilder<> Builder(Entry);
  auto *Self = Builder.CreateAlloca(I64, nullptr, "self");
  auto *Addr1 = Builder.CreateAlloca(I64, nullptr, "addr1");
  auto *Addr2 = Builder.CreateAlloca(I64, nullptr, "addr2");
  auto *Slot1 = Builder.CreateAlloca(I64, nullptr, "p1");
  auto *Slot2 = Builder.CreateAlloca(I64, nullptr, "p2");
  auto *Flag = Builder.CreateAlloca(I8, nullptr, "ZF");
  auto *Flag2 = Builder.CreateAlloca(I8, nullptr, "ZF2");
  Builder.CreateStore(Function->getArg(0), Self);
  auto Stage = [&](llvm::AllocaInst *Addr, llvm::AllocaInst *Slot) {
    llvm::Value *Sum = Builder.CreateAdd(Builder.CreateLoad(I64, Self),
                                         llvm::ConstantInt::get(I64, 8));
    Builder.CreateStore(Sum, Addr);
    llvm::Value *Mem =
        Builder.CreateIntToPtr(Builder.CreateLoad(I64, Addr), Ptr);
    Builder.CreateStore(Builder.CreateLoad(I64, Mem), Slot);
  };
  auto FlagBr = [&](llvm::AllocaInst *Slot, llvm::AllocaInst *FlagSlot,
                    llvm::BasicBlock *OnZero, llvm::BasicBlock *OnNonZero) {
    llvm::Value *Eq = Builder.CreateICmpEQ(Builder.CreateLoad(I64, Slot),
                                           llvm::ConstantInt::get(I64, 0));
    Builder.CreateStore(Builder.CreateZExt(Eq, I8), FlagSlot);
    Builder.CreateCondBr(
        Builder.CreateICmpNE(Builder.CreateLoad(I8, FlagSlot),
                             llvm::ConstantInt::get(I8, 0)),
        OnZero, OnNonZero);
  };
  Stage(Addr1, Slot1);
  FlagBr(Slot1, Flag, OtherBB, Kind);
  Builder.SetInsertPoint(Kind);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(
          Builder.CreateCall(
              IsKind, {Builder.CreateIntToPtr(Builder.CreateLoad(I64, Slot1),
                                              Ptr)}),
          llvm::ConstantInt::get(I32, 0)),
      Retest, Join);
  Builder.SetInsertPoint(Retest);
  Stage(Addr2, Slot2);
  FlagBr(Slot2, Flag2, Skip, Again);
  Builder.SetInsertPoint(Skip);
  Builder.CreateBr(Join);
  Builder.SetInsertPoint(Again);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(
          Builder.CreateCall(
              IsKind, {Builder.CreateIntToPtr(Builder.CreateLoad(I64, Slot2),
                                              Ptr)}),
          llvm::ConstantInt::get(I32, 0)),
      Body, Join);
  Builder.SetInsertPoint(Body);
  Builder.CreateCall(Use);
  Builder.CreateBr(Join);
  Builder.SetInsertPoint(OtherBB);
  Builder.CreateCall(Other);
  Builder.CreateBr(Join);
  Builder.SetInsertPoint(Join);
  Builder.CreateCall(Tail);
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("void reloaded_field(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const std::string Fn = Source.substr(BodyAt);
  size_t KindCount = 0;
  for (size_t Pos = 0; (Pos = Fn.find("IsKind(", Pos)) != std::string::npos;
       Pos += 7)
    ++KindCount;
  EXPECT_EQ(KindCount, 2u) << Source;
  EXPECT_NE(Fn.find("use_field("), std::string::npos) << Source;
  EXPECT_NE(Fn.find("other_step("), std::string::npos) << Source;
  EXPECT_NE(Fn.find("tail_step("), std::string::npos) << Source;
  EXPECT_EQ(Fn.find("if (v1)"), std::string::npos) << Source;
  EXPECT_EQ(Fn.find("if (!(v1))"), std::string::npos) << Source;
  size_t IfCount = 0;
  for (size_t Pos = 0; (Pos = Fn.find("if (", Pos)) != std::string::npos;
       Pos += 4)
    ++IfCount;
  // Field test, first IsKind, second IsKind. The reload is not another if.
  EXPECT_EQ(IfCount, 3u) << Source;
}

TEST(LLVMCPointerAddresses, KeepsFieldPointerTestAfterFieldStore) {
  // A store through the same field between the tests keeps the later test.
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-field-store", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "field_store", Module);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Use = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "use_field", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Mid = llvm::BasicBlock::Create(Context, "mid", Function);
  llvm::BasicBlock *Retest =
      llvm::BasicBlock::Create(Context, "retest", Function);
  llvm::BasicBlock *Body = llvm::BasicBlock::Create(Context, "body", Function);
  llvm::BasicBlock *Done = llvm::BasicBlock::Create(Context, "done", Function);
  llvm::IRBuilder<> Builder(Entry);
  auto *Self = Builder.CreateAlloca(I64, nullptr, "self");
  auto *Addr1 = Builder.CreateAlloca(I64, nullptr, "addr1");
  auto *Addr2 = Builder.CreateAlloca(I64, nullptr, "addr2");
  auto *Slot1 = Builder.CreateAlloca(I64, nullptr, "p1");
  auto *Slot2 = Builder.CreateAlloca(I64, nullptr, "p2");
  auto *Flag = Builder.CreateAlloca(I8, nullptr, "ZF");
  auto *Flag2 = Builder.CreateAlloca(I8, nullptr, "ZF2");
  Builder.CreateStore(Function->getArg(0), Self);
  auto Stage = [&](llvm::AllocaInst *Addr, llvm::AllocaInst *Slot) {
    llvm::Value *Sum = Builder.CreateAdd(Builder.CreateLoad(I64, Self),
                                         llvm::ConstantInt::get(I64, 8));
    Builder.CreateStore(Sum, Addr);
    llvm::Value *Mem =
        Builder.CreateIntToPtr(Builder.CreateLoad(I64, Addr), Ptr);
    Builder.CreateStore(Builder.CreateLoad(I64, Mem), Slot);
  };
  auto FlagBr = [&](llvm::AllocaInst *Slot, llvm::AllocaInst *FlagSlot,
                    llvm::BasicBlock *OnZero, llvm::BasicBlock *OnNonZero) {
    llvm::Value *Eq = Builder.CreateICmpEQ(Builder.CreateLoad(I64, Slot),
                                           llvm::ConstantInt::get(I64, 0));
    Builder.CreateStore(Builder.CreateZExt(Eq, I8), FlagSlot);
    Builder.CreateCondBr(
        Builder.CreateICmpNE(Builder.CreateLoad(I8, FlagSlot),
                             llvm::ConstantInt::get(I8, 0)),
        OnZero, OnNonZero);
  };
  Stage(Addr1, Slot1);
  FlagBr(Slot1, Flag, Done, Mid);
  Builder.SetInsertPoint(Mid);
  llvm::Value *Sum = Builder.CreateAdd(Builder.CreateLoad(I64, Self),
                                      llvm::ConstantInt::get(I64, 8));
  Builder.CreateStore(llvm::ConstantInt::get(I64, 1),
                      Builder.CreateIntToPtr(Sum, Ptr));
  Builder.CreateBr(Retest);
  Builder.SetInsertPoint(Retest);
  Stage(Addr2, Slot2);
  FlagBr(Slot2, Flag2, Done, Body);
  Builder.SetInsertPoint(Body);
  Builder.CreateCall(Use);
  Builder.CreateBr(Done);
  Builder.SetInsertPoint(Done);
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("void field_store(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const std::string Fn = Source.substr(BodyAt);
  EXPECT_NE(Fn.find("use_field("), std::string::npos) << Source;
  size_t IfCount = 0;
  for (size_t Pos = 0; (Pos = Fn.find("if (", Pos)) != std::string::npos;
       Pos += 4)
    ++IfCount;
  EXPECT_EQ(IfCount, 2u) << Source;
}

TEST(LLVMCPointerAddresses, OmitsDeadNullAssignAfterImpliedField) {
  // A dominating field test already proved the pointer is live. The later
  // arm reloads it and stores 0 on the null edge. That assign is not printed,
  // and nothing after the field load stores 0 again.
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-dead-null-field", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *KindTy = llvm::FunctionType::get(I32, {Ptr}, false);
  llvm::Function *IsKind = llvm::Function::Create(
      KindTy, llvm::GlobalValue::ExternalLinkage, "IsKind", Module);
  llvm::FunctionType *UseTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I32}, false);
  llvm::Function *Use = llvm::Function::Create(
      UseTy, llvm::GlobalValue::ExternalLinkage, "use_id", Module);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Other = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "other_step", Module);
  llvm::Function *Tail = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "tail_step", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {I64, I32}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "dead_null_field", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Kind = llvm::BasicBlock::Create(Context, "kind", Function);
  llvm::BasicBlock *Retest =
      llvm::BasicBlock::Create(Context, "retest", Function);
  llvm::BasicBlock *Zero = llvm::BasicBlock::Create(Context, "zero", Function);
  llvm::BasicBlock *Field =
      llvm::BasicBlock::Create(Context, "field", Function);
  llvm::BasicBlock *Join = llvm::BasicBlock::Create(Context, "join", Function);
  llvm::BasicBlock *OtherBB =
      llvm::BasicBlock::Create(Context, "other", Function);
  llvm::IRBuilder<> Builder(Entry);
  auto *Self = Builder.CreateAlloca(I64, nullptr, "self");
  auto *Addr1 = Builder.CreateAlloca(I64, nullptr, "addr1");
  auto *Addr2 = Builder.CreateAlloca(I64, nullptr, "addr2");
  auto *Slot1 = Builder.CreateAlloca(I64, nullptr, "p1");
  auto *Slot2 = Builder.CreateAlloca(I64, nullptr, "p2");
  auto *ZeroHome = Builder.CreateAlloca(I32, nullptr, "zero_home");
  auto *Id = Builder.CreateAlloca(I32, nullptr, "id_slot");
  auto *Flag = Builder.CreateAlloca(I8, nullptr, "ZF");
  auto *Flag2 = Builder.CreateAlloca(I8, nullptr, "ZF2");
  Builder.CreateStore(Function->getArg(0), Self);
  Builder.CreateStore(llvm::ConstantInt::get(I32, 0), ZeroHome);
  auto Stage = [&](llvm::AllocaInst *Addr, llvm::AllocaInst *Slot) {
    llvm::Value *Sum = Builder.CreateAdd(Builder.CreateLoad(I64, Self),
                                         llvm::ConstantInt::get(I64, 8));
    Builder.CreateStore(Sum, Addr);
    llvm::Value *Mem =
        Builder.CreateIntToPtr(Builder.CreateLoad(I64, Addr), Ptr);
    Builder.CreateStore(Builder.CreateLoad(I64, Mem), Slot);
  };
  auto FlagBr = [&](llvm::AllocaInst *Slot, llvm::AllocaInst *FlagSlot,
                    llvm::BasicBlock *OnZero, llvm::BasicBlock *OnNonZero) {
    llvm::Value *Eq = Builder.CreateICmpEQ(Builder.CreateLoad(I64, Slot),
                                           llvm::ConstantInt::get(I64, 0));
    Builder.CreateStore(Builder.CreateZExt(Eq, I8), FlagSlot);
    Builder.CreateCondBr(
        Builder.CreateICmpNE(Builder.CreateLoad(I8, FlagSlot),
                             llvm::ConstantInt::get(I8, 0)),
        OnZero, OnNonZero);
  };
  Stage(Addr1, Slot1);
  FlagBr(Slot1, Flag, OtherBB, Kind);
  Builder.SetInsertPoint(Kind);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(
          Builder.CreateCall(
              IsKind, {Builder.CreateIntToPtr(Builder.CreateLoad(I64, Slot1),
                                              Ptr)}),
          llvm::ConstantInt::get(I32, 0)),
      Retest, Join);
  Builder.SetInsertPoint(Retest);
  Stage(Addr2, Slot2);
  FlagBr(Slot2, Flag2, Zero, Field);
  Builder.SetInsertPoint(Zero);
  Builder.CreateStore(Builder.CreateLoad(I32, ZeroHome), Id);
  Builder.CreateBr(Join);
  Builder.SetInsertPoint(Field);
  llvm::Value *FieldAddr = Builder.CreateAdd(
      Builder.CreateLoad(I64, Slot2), llvm::ConstantInt::get(I64, 16));
  llvm::Value *FieldVal = Builder.CreateLoad(
      I32, Builder.CreateIntToPtr(FieldAddr, Ptr));
  Builder.CreateStore(FieldVal, Id);
  Builder.CreateBr(Join);
  Builder.SetInsertPoint(OtherBB);
  Builder.CreateCall(Other);
  Builder.CreateBr(Join);
  Builder.SetInsertPoint(Join);
  Builder.CreateCall(Use, {Builder.CreateLoad(I32, Id)});
  Builder.CreateCall(Tail);
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("void dead_null_field(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const std::string Fn = Source.substr(BodyAt);
  EXPECT_NE(Fn.find("use_id("), std::string::npos) << Source;
  EXPECT_NE(Fn.find("other_step("), std::string::npos) << Source;
  EXPECT_NE(Fn.find("tail_step("), std::string::npos) << Source;
  EXPECT_NE(Fn.find("IsKind("), std::string::npos) << Source;
  EXPECT_NE(Fn.find("16"), std::string::npos) << Source;
  const auto UseAt = Fn.find("use_id(");
  const auto FieldAt = Fn.find("16");
  ASSERT_NE(UseAt, std::string::npos) << Source;
  ASSERT_NE(FieldAt, std::string::npos) << Source;
  EXPECT_LT(FieldAt, UseAt) << Source;
  EXPECT_EQ(Fn.find("= 0;"), std::string::npos) << Source;
  EXPECT_NE(Fn.find("if (!(v0))"), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, ForwardsDeadNullFieldIntoCall) {
  // The null arm of an implied pointer test only stores 0, so the call's
  // only live value is the field. That field is the call argument. A second
  // call keeps the assignment.
  class RecordDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140000660 && Addr != 0x140000670)
        return std::nullopt;
      auto Basic = NdType::makeNamedRecord("RecordBasic", 112);
      Basic->FieldDisplayNames = {"id"};
      Basic->FieldDisplayOffsets = {0};
      Basic->FieldDisplayTypes = {NdType::makeInt(4, false)};
      auto Data = NdType::makeNamedRecord("CRecordData", 1792);
      Data->FieldDisplayNames = {"m_core"};
      Data->FieldDisplayOffsets = {152};
      Data->FieldDisplayTypes = {Basic};
      auto Holder = NdType::makeNamedRecord("PtrBox", 16);
      Holder->FieldDisplayNames = {"p"};
      Holder->FieldDisplayOffsets = {8};
      Holder->FieldDisplayTypes = {NdType::makePtr(Data)};
      auto Record = NdType::makeNamedRecord("CRecord", 512);
      Record->FieldDisplayNames = {"m_pRecordData"};
      Record->FieldDisplayOffsets = {72};
      Record->FieldDisplayTypes = {Holder};
      FunctionSym FS;
      FS.Addr = Addr;
      FS.Params = {{"this", NdType::makePtr(Record)}};
      FS.ReturnType = NdType::makeVoid();
      FS.Name = Addr == 0x140000660 ? "forward_period" : "keep_period";
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  auto Build = [](llvm::Module &Module, const char *Name, bool SecondUse) {
    llvm::LLVMContext &Context = Module.getContext();
    llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
    llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
    llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
    llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
    llvm::FunctionType *KindTy = llvm::FunctionType::get(I32, {Ptr}, false);
    llvm::Function *IsKind = llvm::Function::Create(
        KindTy, llvm::GlobalValue::ExternalLinkage, "IsKind", Module);
    llvm::FunctionType *UseTy =
        llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I32}, false);
    llvm::Function *Use = llvm::Function::Create(
        UseTy, llvm::GlobalValue::ExternalLinkage, "use_period", Module);
    llvm::Function *Again = llvm::Function::Create(
        UseTy, llvm::GlobalValue::ExternalLinkage, "use_again", Module);
    llvm::FunctionType *VoidTy =
        llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
    llvm::Function *Other = llvm::Function::Create(
        VoidTy, llvm::GlobalValue::ExternalLinkage, "other_step", Module);
    llvm::FunctionType *FnTy =
        llvm::FunctionType::get(VoidTy->getReturnType(), {Ptr}, false);
    llvm::Function *Function = llvm::Function::Create(
        FnTy, llvm::GlobalValue::ExternalLinkage, Name, Module);
    rewrite_source::setOriginalVA(*Function, SecondUse ? 0x140000670
                                                      : 0x140000660);
    llvm::BasicBlock *Entry =
        llvm::BasicBlock::Create(Context, "entry", Function);
    llvm::BasicBlock *Kind =
        llvm::BasicBlock::Create(Context, "kind", Function);
    llvm::BasicBlock *Retest =
        llvm::BasicBlock::Create(Context, "retest", Function);
    llvm::BasicBlock *Zero =
        llvm::BasicBlock::Create(Context, "zero", Function);
    llvm::BasicBlock *Field =
        llvm::BasicBlock::Create(Context, "field", Function);
    llvm::BasicBlock *Join =
        llvm::BasicBlock::Create(Context, "join", Function);
    llvm::BasicBlock *OtherBB =
        llvm::BasicBlock::Create(Context, "other", Function);
    llvm::IRBuilder<> Builder(Entry);
    auto *Self = Builder.CreateAlloca(I64, nullptr, "self");
    auto *Addr1 = Builder.CreateAlloca(I64, nullptr, "addr1");
    auto *Addr2 = Builder.CreateAlloca(I64, nullptr, "addr2");
    auto *Slot1 = Builder.CreateAlloca(I64, nullptr, "p1");
    auto *Slot2 = Builder.CreateAlloca(I64, nullptr, "p2");
    auto *ZeroHome = Builder.CreateAlloca(I32, nullptr, "zero_home");
    auto *Id = Builder.CreateAlloca(I32, nullptr, "id_slot");
    auto *Flag = Builder.CreateAlloca(I8, nullptr, "ZF");
    auto *Flag2 = Builder.CreateAlloca(I8, nullptr, "ZF2");
    Builder.CreateStore(Builder.CreatePtrToInt(Function->getArg(0), I64),
                        Self);
    Builder.CreateStore(llvm::ConstantInt::get(I32, 0), ZeroHome);
    auto Stage = [&](llvm::AllocaInst *Addr, llvm::AllocaInst *Slot) {
      llvm::Value *Sum = Builder.CreateAdd(Builder.CreateLoad(I64, Self),
                                           llvm::ConstantInt::get(I64, 80));
      Builder.CreateStore(Sum, Addr);
      llvm::Value *Mem =
          Builder.CreateIntToPtr(Builder.CreateLoad(I64, Addr), Ptr);
      Builder.CreateStore(Builder.CreateLoad(I64, Mem), Slot);
    };
    auto FlagBr = [&](llvm::AllocaInst *Slot, llvm::AllocaInst *FlagSlot,
                      llvm::BasicBlock *OnZero, llvm::BasicBlock *OnNonZero) {
      llvm::Value *Eq = Builder.CreateICmpEQ(Builder.CreateLoad(I64, Slot),
                                             llvm::ConstantInt::get(I64, 0));
      Builder.CreateStore(Builder.CreateZExt(Eq, I8), FlagSlot);
      Builder.CreateCondBr(
          Builder.CreateICmpNE(Builder.CreateLoad(I8, FlagSlot),
                               llvm::ConstantInt::get(I8, 0)),
          OnZero, OnNonZero);
    };
    Stage(Addr1, Slot1);
    FlagBr(Slot1, Flag, OtherBB, Kind);
    Builder.SetInsertPoint(Kind);
    Builder.CreateCondBr(
        Builder.CreateICmpNE(
            Builder.CreateCall(
                IsKind, {Builder.CreateIntToPtr(Builder.CreateLoad(I64, Slot1),
                                                Ptr)}),
            llvm::ConstantInt::get(I32, 0)),
        Retest, OtherBB);
    Builder.SetInsertPoint(Retest);
    Stage(Addr2, Slot2);
    FlagBr(Slot2, Flag2, Zero, Field);
    Builder.SetInsertPoint(Zero);
    Builder.CreateStore(Builder.CreateLoad(I32, ZeroHome), Id);
    Builder.CreateBr(Join);
    Builder.SetInsertPoint(Field);
    llvm::Value *FieldAddr = Builder.CreateAdd(
        Builder.CreateLoad(I64, Slot2), llvm::ConstantInt::get(I64, 152));
    Builder.CreateStore(
        Builder.CreateLoad(I32, Builder.CreateIntToPtr(FieldAddr, Ptr)), Id);
    Builder.CreateBr(Join);
    Builder.SetInsertPoint(OtherBB);
    Builder.CreateCall(Other);
    Builder.CreateRetVoid();
    Builder.SetInsertPoint(Join);
    Builder.CreateCall(Use, {Builder.CreateLoad(I32, Id)});
    if (SecondUse)
      Builder.CreateCall(Again, {Builder.CreateLoad(I32, Id)});
    Builder.CreateRetVoid();
    return Function;
  };

  {
    llvm::LLVMContext Context;
    llvm::Module Module("llvm-c-forward-dead-null", Context);
    llvm::Function *Function = Build(Module, "forward_period", false);
    std::string Source;
    llvm::raw_string_ostream OS(Source);
    CEmitterOptions Options;
    Options.EmitIncludes = false;
    ASSERT_TRUE(
        LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr, Function));
    OS.flush();
    const auto BodyAt = Source.find("void forward_period(");
    ASSERT_NE(BodyAt, std::string::npos) << Source;
    const std::string Fn = Source.substr(BodyAt);
    const auto UseAt = Fn.find("use_period(");
    const auto IdAt = Fn.find("m_core.id");
    ASSERT_NE(UseAt, std::string::npos) << Source;
    ASSERT_NE(IdAt, std::string::npos) << Source;
    EXPECT_GT(IdAt, UseAt) << Source;
    EXPECT_EQ(Fn.find("m_core.id", IdAt + 1), std::string::npos) << Source;
    EXPECT_EQ(Fn.find("= 0;"), std::string::npos) << Source;
    EXPECT_NE(Fn.find("other_step("), std::string::npos) << Source;
    EXPECT_NE(Fn.find("IsKind("), std::string::npos) << Source;
  }
  {
    llvm::LLVMContext Context;
    llvm::Module Module("llvm-c-keep-dead-null", Context);
    llvm::Function *Function = Build(Module, "keep_period", true);
    std::string Source;
    llvm::raw_string_ostream OS(Source);
    CEmitterOptions Options;
    Options.EmitIncludes = false;
    ASSERT_TRUE(
        LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr, Function));
    OS.flush();
    const auto BodyAt = Source.find("void keep_period(");
    ASSERT_NE(BodyAt, std::string::npos) << Source;
    const std::string Fn = Source.substr(BodyAt);
    const auto UseAt = Fn.find("use_period(");
    const auto IdAt = Fn.find("m_core.id");
    ASSERT_NE(UseAt, std::string::npos) << Source;
    ASSERT_NE(IdAt, std::string::npos) << Source;
    EXPECT_LT(IdAt, UseAt) << Source;
    EXPECT_NE(Fn.find("use_again("), std::string::npos) << Source;
    EXPECT_EQ(Fn.find("= 0;"), std::string::npos) << Source;
  }
}

TEST(LLVMCPointerAddresses, KeepsNullAssignWhenDeadArmCalls) {
  // A printed call on the null edge is not a zero substitute, so the test stays.
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-kept-null-call", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *KindTy = llvm::FunctionType::get(I32, {Ptr}, false);
  llvm::Function *IsKind = llvm::Function::Create(
      KindTy, llvm::GlobalValue::ExternalLinkage, "IsKind", Module);
  llvm::FunctionType *UseTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I32}, false);
  llvm::Function *Use = llvm::Function::Create(
      UseTy, llvm::GlobalValue::ExternalLinkage, "use_id", Module);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Keep = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "keep_side", Module);
  llvm::Function *Other = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "other_step", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "kept_null_call", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Kind = llvm::BasicBlock::Create(Context, "kind", Function);
  llvm::BasicBlock *Retest =
      llvm::BasicBlock::Create(Context, "retest", Function);
  llvm::BasicBlock *Zero = llvm::BasicBlock::Create(Context, "zero", Function);
  llvm::BasicBlock *Field =
      llvm::BasicBlock::Create(Context, "field", Function);
  llvm::BasicBlock *Join = llvm::BasicBlock::Create(Context, "join", Function);
  llvm::BasicBlock *OtherBB =
      llvm::BasicBlock::Create(Context, "other", Function);
  llvm::IRBuilder<> Builder(Entry);
  auto *Self = Builder.CreateAlloca(I64, nullptr, "self");
  auto *Addr1 = Builder.CreateAlloca(I64, nullptr, "addr1");
  auto *Addr2 = Builder.CreateAlloca(I64, nullptr, "addr2");
  auto *Slot1 = Builder.CreateAlloca(I64, nullptr, "p1");
  auto *Slot2 = Builder.CreateAlloca(I64, nullptr, "p2");
  auto *Id = Builder.CreateAlloca(I32, nullptr, "id_slot");
  auto *Flag = Builder.CreateAlloca(I8, nullptr, "ZF");
  auto *Flag2 = Builder.CreateAlloca(I8, nullptr, "ZF2");
  Builder.CreateStore(Function->getArg(0), Self);
  auto Stage = [&](llvm::AllocaInst *Addr, llvm::AllocaInst *Slot) {
    llvm::Value *Sum = Builder.CreateAdd(Builder.CreateLoad(I64, Self),
                                         llvm::ConstantInt::get(I64, 8));
    Builder.CreateStore(Sum, Addr);
    llvm::Value *Mem =
        Builder.CreateIntToPtr(Builder.CreateLoad(I64, Addr), Ptr);
    Builder.CreateStore(Builder.CreateLoad(I64, Mem), Slot);
  };
  auto FlagBr = [&](llvm::AllocaInst *Slot, llvm::AllocaInst *FlagSlot,
                    llvm::BasicBlock *OnZero, llvm::BasicBlock *OnNonZero) {
    llvm::Value *Eq = Builder.CreateICmpEQ(Builder.CreateLoad(I64, Slot),
                                           llvm::ConstantInt::get(I64, 0));
    Builder.CreateStore(Builder.CreateZExt(Eq, I8), FlagSlot);
    Builder.CreateCondBr(
        Builder.CreateICmpNE(Builder.CreateLoad(I8, FlagSlot),
                             llvm::ConstantInt::get(I8, 0)),
        OnZero, OnNonZero);
  };
  Stage(Addr1, Slot1);
  FlagBr(Slot1, Flag, OtherBB, Kind);
  Builder.SetInsertPoint(Kind);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(
          Builder.CreateCall(
              IsKind, {Builder.CreateIntToPtr(Builder.CreateLoad(I64, Slot1),
                                              Ptr)}),
          llvm::ConstantInt::get(I32, 0)),
      Retest, Join);
  Builder.SetInsertPoint(Retest);
  Stage(Addr2, Slot2);
  FlagBr(Slot2, Flag2, Zero, Field);
  Builder.SetInsertPoint(Zero);
  Builder.CreateCall(Keep);
  Builder.CreateStore(llvm::ConstantInt::get(I32, 0), Id);
  Builder.CreateBr(Join);
  Builder.SetInsertPoint(Field);
  llvm::Value *FieldAddr = Builder.CreateAdd(
      Builder.CreateLoad(I64, Slot2), llvm::ConstantInt::get(I64, 16));
  Builder.CreateStore(
      Builder.CreateLoad(I32, Builder.CreateIntToPtr(FieldAddr, Ptr)), Id);
  Builder.CreateBr(Join);
  Builder.SetInsertPoint(OtherBB);
  Builder.CreateCall(Other);
  Builder.CreateBr(Join);
  Builder.SetInsertPoint(Join);
  Builder.CreateCall(Use, {Builder.CreateLoad(I32, Id)});
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("void kept_null_call(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const std::string Fn = Source.substr(BodyAt);
  EXPECT_NE(Fn.find("keep_side("), std::string::npos) << Source;
  EXPECT_NE(Fn.find("use_id("), std::string::npos) << Source;
  EXPECT_NE(Fn.find("= 0;"), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, KeepsNestedPointerTestAfterPointerStore) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-kept-ptr", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Dtor = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "dtor", Module);
  llvm::FunctionType *IdTy = llvm::FunctionType::get(I64, {I64}, false);
  llvm::Function *Ident = llvm::Function::Create(
      IdTy, llvm::GlobalValue::ExternalLinkage, "ident", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "kept_ptr", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Have = llvm::BasicBlock::Create(Context, "have", Function);
  llvm::BasicBlock *Release =
      llvm::BasicBlock::Create(Context, "release", Function);
  llvm::BasicBlock *Done = llvm::BasicBlock::Create(Context, "done", Function);
  llvm::IRBuilder<> Builder(Entry);
  auto *Slot = Builder.CreateAlloca(I64, nullptr, "p");
  Builder.CreateStore(Function->getArg(0), Slot);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(Builder.CreateLoad(I64, Slot),
                           llvm::ConstantInt::get(I64, 0)),
      Have, Done);
  Builder.SetInsertPoint(Have);
  Builder.CreateStore(Builder.CreateCall(Ident, {Function->getArg(0)}), Slot);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(Builder.CreateLoad(I64, Slot),
                           llvm::ConstantInt::get(I64, 0)),
      Release, Done);
  Builder.SetInsertPoint(Release);
  Builder.CreateCall(Dtor);
  Builder.CreateBr(Done);
  Builder.SetInsertPoint(Done);
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("void kept_ptr(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const std::string Body = Source.substr(BodyAt);
  EXPECT_NE(Body.find("dtor("), std::string::npos) << Source;
  size_t IfCount = 0;
  for (size_t Pos = 0; (Pos = Body.find("if (", Pos)) != std::string::npos;
       Pos += 4)
    ++IfCount;
  EXPECT_EQ(IfCount, 2u) << Source;
}

TEST(LLVMCPointerAddresses, RecordVisibleRegisterSpillOfZeroIsKept) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-zero-frame-spill", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *UseTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Use = llvm::Function::Create(
      UseTy, llvm::GlobalValue::ExternalLinkage, "use_slot", Module);
  llvm::FunctionType *RecTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *UseRec = llvm::Function::Create(
      RecTy, llvm::GlobalValue::ExternalLinkage, "use_record", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "spill_frame_zero", Module);
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  auto *Frame = Builder.CreateAlloca(llvm::ArrayType::get(I8, 168), nullptr,
                                     "frame");
  auto *End = Builder.CreateInBoundsGEP(I8, Frame, llvm::ConstantInt::get(I64, 88),
                                       "frame_end");
  auto *RSP = Builder.CreateAlloca(I64, nullptr, "RSP");
  auto *RSP1 = Builder.CreateAlloca(I64, nullptr, "RSP1");
  auto *RSP2 = Builder.CreateAlloca(I64, nullptr, "RSP2");
  auto *RBX = Builder.CreateAlloca(I64, nullptr, "RBX");
  auto *Eight = llvm::ConstantInt::get(I64, 8);
  auto *ThirtyTwo = llvm::ConstantInt::get(I64, 32);
  auto *Forty = llvm::ConstantInt::get(I64, 40);
  auto *FortyEight = llvm::ConstantInt::get(I64, 48);
  auto *SixtyFour = llvm::ConstantInt::get(I64, 64);
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), RBX);
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), RSP1);
  Builder.CreateStore(Builder.CreatePtrToInt(End, I64), RSP);
  Builder.CreateStore(Builder.CreateLoad(I64, RBX), RBX);
  llvm::Value *Sub = Builder.CreateSub(Builder.CreateLoad(I64, RSP), Eight);
  Builder.CreateStore(Sub, RSP1);
  Builder.CreateStore(Builder.CreateLoad(I64, RBX),
                      Builder.CreateIntToPtr(Builder.CreateLoad(I64, RSP1), Ptr));
  llvm::Value *Sub2 =
      Builder.CreateSub(Builder.CreateLoad(I64, RSP1), SixtyFour);
  Builder.CreateStore(Sub2, RSP2);
  llvm::Value *Addr48 =
      Builder.CreateAdd(Builder.CreateLoad(I64, RSP2), ThirtyTwo);
  llvm::Value *Addr56 =
      Builder.CreateAdd(Builder.CreateLoad(I64, RSP2), Forty);
  llvm::Value *Addr64 =
      Builder.CreateAdd(Builder.CreateLoad(I64, RSP2), FortyEight);
  Builder.CreateStore(llvm::ConstantInt::get(I64, 2),
                      Builder.CreateIntToPtr(Addr48, Ptr));
  Builder.CreateStore(Addr64, Builder.CreateIntToPtr(Addr56, Ptr));
  llvm::Value *Live = Builder.CreateInBoundsGEP(I8, Frame, ThirtyTwo);
  Builder.CreateStore(llvm::ConstantInt::get(I64, 7), Live);
  Builder.CreateCall(Use, {Live});
  Builder.CreateCall(UseRec, {Addr48});
  Builder.CreateRetVoid();

  llvm::Function *Kept = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "spill_frame_kept", Module);
  llvm::IRBuilder<> KeptBuilder(
      llvm::BasicBlock::Create(Context, "entry", Kept));
  auto *KeptFrame = KeptBuilder.CreateAlloca(llvm::ArrayType::get(I8, 168),
                                             nullptr, "frame");
  auto *KeptEnd = KeptBuilder.CreateInBoundsGEP(
      I8, KeptFrame, llvm::ConstantInt::get(I64, 88), "frame_end");
  auto *KeptRSP = KeptBuilder.CreateAlloca(I64, nullptr, "RSP");
  auto *KeptRSP1 = KeptBuilder.CreateAlloca(I64, nullptr, "RSP1");
  auto *KeptRSP2 = KeptBuilder.CreateAlloca(I64, nullptr, "RSP2");
  KeptBuilder.CreateStore(llvm::ConstantInt::get(I64, 0), KeptRSP1);
  KeptBuilder.CreateStore(KeptBuilder.CreatePtrToInt(KeptEnd, I64), KeptRSP);
  llvm::Value *KeptSub =
      KeptBuilder.CreateSub(KeptBuilder.CreateLoad(I64, KeptRSP), Eight);
  KeptBuilder.CreateStore(KeptSub, KeptRSP1);
  KeptBuilder.CreateStore(
      llvm::ConstantInt::get(I64, 9),
      KeptBuilder.CreateIntToPtr(KeptBuilder.CreateLoad(I64, KeptRSP1), Ptr));
  llvm::Value *KeptSub2 =
      KeptBuilder.CreateSub(KeptBuilder.CreateLoad(I64, KeptRSP1), SixtyFour);
  KeptBuilder.CreateStore(KeptSub2, KeptRSP2);
  llvm::Value *Kept48 =
      KeptBuilder.CreateAdd(KeptBuilder.CreateLoad(I64, KeptRSP2), ThirtyTwo);
  llvm::Value *Kept56 =
      KeptBuilder.CreateAdd(KeptBuilder.CreateLoad(I64, KeptRSP2), Forty);
  llvm::Value *Kept64 =
      KeptBuilder.CreateAdd(KeptBuilder.CreateLoad(I64, KeptRSP2), FortyEight);
  KeptBuilder.CreateStore(Kept64, KeptBuilder.CreateIntToPtr(Kept56, Ptr));
  KeptBuilder.CreateCall(UseRec, {Kept48});
  KeptBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("spill_frame_zero(");
  const auto KeptAt = Source.find("spill_frame_kept(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  ASSERT_NE(KeptAt, std::string::npos) << Source;
  const std::string ZeroFn = Source.substr(BodyAt, KeptAt - BodyAt);
  const std::string KeptFn = Source.substr(KeptAt);
  EXPECT_NE(ZeroFn.find("= 7"), std::string::npos) << Source;
  EXPECT_NE(ZeroFn.find("= 2"), std::string::npos) << Source;
  EXPECT_NE(ZeroFn.find("+ 56"), std::string::npos) << Source;
  // The callee can follow [record + 8] to frame + 64 and read its +16
  // field at frame + 80. Without an access bound, zero is observable too.
  const auto ZeroStoreAt = ZeroFn.find("+ 80) = 0;");
  const auto RecordCallAt = ZeroFn.find("use_record(");
  ASSERT_NE(ZeroStoreAt, std::string::npos) << Source;
  ASSERT_NE(RecordCallAt, std::string::npos) << Source;
  EXPECT_LT(ZeroStoreAt, RecordCallAt) << Source;
  EXPECT_NE(KeptFn.find("+ 80"), std::string::npos) << Source;
  EXPECT_NE(KeptFn.find("= 9"), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, UnreadZeroSpillPastCallRecordIsOmitted) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-zero-spill", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *UseTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Use = llvm::Function::Create(
      UseTy, llvm::GlobalValue::ExternalLinkage, "use_record", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "spill_zero", Module);
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  auto *Frame = Builder.CreateAlloca(llvm::ArrayType::get(I8, 64), nullptr,
                                     "frame");
  auto *RBX = Builder.CreateAlloca(I64, nullptr, "RBX");
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), RBX);
  llvm::Value *Copied = Builder.CreateLoad(I64, RBX, "RBX_v");
  Builder.CreateStore(Copied, RBX);
  llvm::Value *Reloaded = Builder.CreateLoad(I64, RBX, "RBX_v7");
  llvm::Value *At8 = Builder.CreateInBoundsGEP(
      I8, Frame, llvm::ConstantInt::get(I64, 8));
  llvm::Value *At16 = Builder.CreateInBoundsGEP(
      I8, Frame, llvm::ConstantInt::get(I64, 16));
  Builder.CreateCall(Use, {Frame});
  Builder.CreateStore(llvm::ConstantInt::get(I64, 7), At8);
  Builder.CreateStore(llvm::ConstantInt::get(I32, 48), Frame);
  Builder.CreateStore(Reloaded, At16);
  Builder.CreateRetVoid();

  llvm::Function *Keep = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage,
      "keep_spill_for_later_record", Module);
  Builder.SetInsertPoint(llvm::BasicBlock::Create(Context, "entry", Keep));
  auto *KeepFrame = Builder.CreateAlloca(llvm::ArrayType::get(I8, 64));
  llvm::Value *KeepAt16 = Builder.CreateInBoundsGEP(
      I8, KeepFrame, llvm::ConstantInt::get(I64, 16));
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), KeepAt16);
  Builder.CreateCall(Use, {KeepFrame});
  Builder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("spill_zero(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto KeepAt = Source.find("keep_spill_for_later_record(", BodyAt);
  ASSERT_NE(KeepAt, std::string::npos) << Source;
  const std::string BeforeCall = Source.substr(BodyAt, KeepAt - BodyAt);
  const std::string AfterStore = Source.substr(KeepAt);
  EXPECT_NE(BeforeCall.find("= 7"), std::string::npos) << Source;
  EXPECT_NE(BeforeCall.find("= 48"), std::string::npos) << Source;
  EXPECT_EQ(BeforeCall.find("= 0"), std::string::npos) << Source;
  EXPECT_NE(AfterStore.find("= 0"), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, SpecializesOneCallPhiTailAtEdges) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-phi-tail", Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *DtorTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Dtor = llvm::Function::Create(
      DtorTy, llvm::GlobalValue::ExternalLinkage, "destroy_one", Module);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *WorkA = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "work_a", Module);
  llvm::Function *WorkB = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "work_b", Module);
  llvm::Function *Release = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "release_name", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {llvm::Type::getInt1Ty(Context)}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "specialize_tail", Module);
  Function->getArg(0)->setName("flag");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *ArmA =
      llvm::BasicBlock::Create(Context, "arm_a", Function);
  llvm::BasicBlock *ArmB =
      llvm::BasicBlock::Create(Context, "arm_b", Function);
  llvm::BasicBlock *Tail = llvm::BasicBlock::Create(Context, "tail", Function);
  llvm::BasicBlock *Epi = llvm::BasicBlock::Create(Context, "epi", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  auto *Slot = EntryBuilder.CreateAlloca(Ptr, nullptr, "cleanup");
  auto *ObjA = EntryBuilder.CreateAlloca(Ptr, nullptr, "obj_a");
  auto *ObjB = EntryBuilder.CreateAlloca(Ptr, nullptr, "obj_b");
  EntryBuilder.CreateCondBr(Function->getArg(0), ArmA, ArmB);
  llvm::IRBuilder<> ABuilder(ArmA);
  ABuilder.CreateCall(WorkA);
  ABuilder.CreateStore(ObjA, Slot);
  ABuilder.CreateBr(Tail);
  llvm::IRBuilder<> BBuilder(ArmB);
  BBuilder.CreateCall(WorkB);
  BBuilder.CreateStore(ObjB, Slot);
  BBuilder.CreateBr(Tail);
  llvm::IRBuilder<> TailBuilder(Tail);
  TailBuilder.CreateCall(Dtor, {TailBuilder.CreateLoad(Ptr, Slot)});
  TailBuilder.CreateBr(Epi);
  llvm::IRBuilder<> EpiBuilder(Epi);
  EpiBuilder.CreateCall(Release);
  EpiBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("specialize_tail(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto AAt = Source.find("destroy_one(&obj_a", BodyAt);
  const auto BAt = Source.find("destroy_one(&obj_b", BodyAt);
  const auto RelAt = Source.find("release_name(", BodyAt);
  const auto WorkAAt = Source.find("work_a(", BodyAt);
  const auto WorkBAt = Source.find("work_b(", BodyAt);
  EXPECT_NE(AAt, std::string::npos) << Source;
  EXPECT_NE(BAt, std::string::npos) << Source;
  EXPECT_NE(RelAt, std::string::npos) << Source;
  EXPECT_NE(WorkAAt, std::string::npos) << Source;
  EXPECT_NE(WorkBAt, std::string::npos) << Source;
  EXPECT_EQ(Source.find("release_name(", RelAt + 1), std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("work_a(", WorkAAt + 1), std::string::npos) << Source;
  EXPECT_EQ(Source.find("work_b(", WorkBAt + 1), std::string::npos) << Source;
  EXPECT_EQ(Source.find("cleanup", BodyAt), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, KeepsAssignsWhenPhiTailCallHasAnotherArg) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-phi-tail-ctor", Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *BuildTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {Ptr, Ptr}, false);
  llvm::Function *Build = llvm::Function::Create(
      BuildTy, llvm::GlobalValue::ExternalLinkage, "build_name", Module);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Prep = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "prep_step", Module);
  llvm::Function *Release = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "release_name", Module);
  llvm::Type *I1 = llvm::Type::getInt1Ty(Context);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I1, I1}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "keep_source", Module);
  Function->getArg(0)->setName("flag");
  Function->getArg(1)->setName("flag2");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Body = llvm::BasicBlock::Create(Context, "body", Function);
  llvm::BasicBlock *Alt = llvm::BasicBlock::Create(Context, "alt", Function);
  llvm::BasicBlock *Def = llvm::BasicBlock::Create(Context, "def", Function);
  llvm::BasicBlock *Join = llvm::BasicBlock::Create(Context, "join", Function);
  llvm::BasicBlock *Epi = llvm::BasicBlock::Create(Context, "epi", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  auto *Slot = EntryBuilder.CreateAlloca(Ptr, nullptr, "picked");
  auto *Dst = EntryBuilder.CreateAlloca(Ptr, nullptr, "dst");
  auto *SrcA = EntryBuilder.CreateAlloca(Ptr, nullptr, "src_a");
  auto *SrcB = EntryBuilder.CreateAlloca(Ptr, nullptr, "src_b");
  EntryBuilder.CreateCondBr(Function->getArg(0), Def, Body);
  llvm::IRBuilder<> BodyBuilder(Body);
  BodyBuilder.CreateCall(Prep);
  BodyBuilder.CreateCondBr(Function->getArg(1), Def, Alt);
  llvm::IRBuilder<> DefBuilder(Def);
  DefBuilder.CreateStore(SrcA, Slot);
  DefBuilder.CreateBr(Join);
  llvm::IRBuilder<> AltBuilder(Alt);
  AltBuilder.CreateStore(SrcB, Slot);
  AltBuilder.CreateBr(Join);
  llvm::IRBuilder<> JoinBuilder(Join);
  JoinBuilder.CreateCall(Build, {Dst, JoinBuilder.CreateLoad(Ptr, Slot)});
  JoinBuilder.CreateBr(Epi);
  llvm::IRBuilder<> EpiBuilder(Epi);
  EpiBuilder.CreateCall(Release);
  EpiBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("keep_source(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto AAt = Source.find("&src_a", BodyAt);
  const auto BAt = Source.find("&src_b", BodyAt);
  const auto A2 = AAt == std::string::npos ? std::string::npos
                                           : Source.find("&src_a", AAt + 6);
  const auto BuildAt = Source.find("build_name(", BodyAt);
  const auto Build2 = BuildAt == std::string::npos
                          ? std::string::npos
                          : Source.find("build_name(", BuildAt + 1);
  const auto PrepAt = Source.find("prep_step(", BodyAt);
  const auto RelAt = Source.find("release_name(", BodyAt);
  const auto Rel2 = RelAt == std::string::npos
                        ? std::string::npos
                        : Source.find("release_name(", RelAt + 1);
  EXPECT_NE(AAt, std::string::npos) << Source;
  EXPECT_NE(BAt, std::string::npos) << Source;
  EXPECT_NE(A2, std::string::npos) << Source;
  EXPECT_NE(BuildAt, std::string::npos) << Source;
  EXPECT_EQ(Build2, std::string::npos) << Source;
  EXPECT_NE(PrepAt, std::string::npos) << Source;
  EXPECT_NE(RelAt, std::string::npos) << Source;
  EXPECT_EQ(Rel2, std::string::npos) << Source;
  EXPECT_LT(AAt, BuildAt) << Source;
  EXPECT_LT(BAt, BuildAt) << Source;
  EXPECT_LT(BuildAt, RelAt) << Source;
}

TEST(LLVMCPointerAddresses, OmitsDeadCopyBridgeBeforeSharedReturn) {
  class CursorDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140001000)
        return std::nullopt;
      auto Child = NdType::makeNamedRecord("ChildRecord", 8);
      auto Record = NdType::makeNamedRecord("Record", 16);
      Record->FieldDisplayNames = {"child"};
      Record->FieldDisplayOffsets = {8};
      Record->FieldDisplayTypes = {NdType::makePtr(Child)};
      FunctionSym FS;
      FS.Name = "dead_copy_return";
      FS.Addr = Addr;
      FS.Params = {{"this", NdType::makePtr(Record)},
                   {"flag", NdType::makeInt(1, false)},
                   {"value", NdType::makeInt(8, false)}};
      FS.ReturnType = NdType::makeInt(8, false);
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-dead-copy-return", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::FunctionType *DtorTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Work = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "prepare_return", Module);
  llvm::FunctionType *AcquireTy = llvm::FunctionType::get(I64, false);
  llvm::Function *Acquire = llvm::Function::Create(
      AcquireTy, llvm::GlobalValue::ExternalLinkage, "acquire_value", Module);
  llvm::Function *AcquireOther = llvm::Function::Create(
      AcquireTy, llvm::GlobalValue::ExternalLinkage, "acquire_other", Module);
  llvm::FunctionType *CheckTy =
      llvm::FunctionType::get(llvm::Type::getInt1Ty(Context), false);
  llvm::Function *Check = llvm::Function::Create(
      CheckTy, llvm::GlobalValue::ExternalLinkage, "check_done", Module);
  llvm::Function *Dtor = llvm::Function::Create(
      DtorTy, llvm::GlobalValue::ExternalLinkage, "CStringT_dtor", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      I64, {Ptr, llvm::Type::getInt1Ty(Context), I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "dead_copy_return", Module);
  rewrite_source::setOriginalVA(*Function, 0x140001000);
  Function->getArg(0)->setName("this");
  Function->getArg(1)->setName("flag");
  Function->getArg(2)->setName("value");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Header =
      llvm::BasicBlock::Create(Context, "header", Function);
  llvm::BasicBlock *Update =
      llvm::BasicBlock::Create(Context, "update", Function);
  llvm::BasicBlock *Bridge =
      llvm::BasicBlock::Create(Context, "dead_copy", Function);
  llvm::BasicBlock *Other =
      llvm::BasicBlock::Create(Context, "other", Function);
  llvm::BasicBlock *Epi = llvm::BasicBlock::Create(Context, "epi", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  auto *SourceSlot = EntryBuilder.CreateAlloca(I64, nullptr, "source_slot");
  auto *DeadSlot = EntryBuilder.CreateAlloca(Ptr, nullptr, "dead_slot");
  auto *Obj = EntryBuilder.CreateAlloca(I64, nullptr, "obj");
  llvm::Value *Field = EntryBuilder.CreateInBoundsGEP(
      llvm::Type::getInt8Ty(Context), Function->getArg(0),
      llvm::ConstantInt::get(I64, 8));
  EntryBuilder.CreateStore(EntryBuilder.CreateLoad(Ptr, Field), DeadSlot);
  EntryBuilder.CreateStore(EntryBuilder.CreateCall(Acquire), SourceSlot);
  EntryBuilder.CreateCondBr(Function->getArg(1), Header, Other);
  llvm::IRBuilder<> HeaderBuilder(Header);
  HeaderBuilder.CreateCondBr(HeaderBuilder.CreateCall(Check), Bridge, Update);
  llvm::IRBuilder<> UpdateBuilder(Update);
  UpdateBuilder.CreateStore(UpdateBuilder.CreateCall(AcquireOther), SourceSlot);
  UpdateBuilder.CreateBr(Header);
  llvm::IRBuilder<> BridgeBuilder(Bridge);
  BridgeBuilder.CreateStore(
      BridgeBuilder.CreateIntToPtr(
          BridgeBuilder.CreateLoad(I64, SourceSlot, "unused_copy"), Ptr),
      DeadSlot);
  BridgeBuilder.CreateBr(Epi);
  llvm::IRBuilder<> OtherBuilder(Other);
  OtherBuilder.CreateCall(Work);
  OtherBuilder.CreateBr(Epi);
  llvm::IRBuilder<> EpiBuilder(Epi);
  EpiBuilder.CreateCall(Dtor, {Obj});
  EpiBuilder.CreateRet(Function->getArg(2));

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr,
                                  Function));
  OS.flush();
  const auto BodyAt = Source.find("dead_copy_return(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  EXPECT_EQ(Source.find("goto L_dead_copy", BodyAt), std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("L_dead_copy:", BodyAt), std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("unused_copy", BodyAt), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("acquire_value(", BodyAt), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("CStringT_dtor(", BodyAt), std::string::npos)
      << Source;
}

TEST(LLVMCPointerAddresses, KeepsObservedCopyBridgeBeforeSharedReturn) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-live-copy-return", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *ObserveTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::FunctionType *DtorTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Observe = llvm::Function::Create(
      ObserveTy, llvm::GlobalValue::ExternalLinkage, "observe_copy", Module);
  llvm::Function *Dtor = llvm::Function::Create(
      DtorTy, llvm::GlobalValue::ExternalLinkage, "CStringT_dtor", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {llvm::Type::getInt1Ty(Context), I64},
      false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "live_copy_return", Module);
  Function->getArg(0)->setName("flag");
  Function->getArg(1)->setName("value");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Bridge =
      llvm::BasicBlock::Create(Context, "live_copy", Function);
  llvm::BasicBlock *Other =
      llvm::BasicBlock::Create(Context, "other", Function);
  llvm::BasicBlock *Epi = llvm::BasicBlock::Create(Context, "epi", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  auto *SourceSlot = EntryBuilder.CreateAlloca(I64, nullptr, "source_slot");
  auto *CopySlot = EntryBuilder.CreateAlloca(I64, nullptr, "copy_slot");
  auto *Obj = EntryBuilder.CreateAlloca(I64, nullptr, "obj");
  EntryBuilder.CreateStore(Function->getArg(1), SourceSlot);
  EntryBuilder.CreateCondBr(Function->getArg(0), Bridge, Other);
  llvm::IRBuilder<> BridgeBuilder(Bridge);
  BridgeBuilder.CreateStore(
      BridgeBuilder.CreateLoad(I64, SourceSlot, "needed_copy"), CopySlot);
  BridgeBuilder.CreateBr(Epi);
  llvm::IRBuilder<> OtherBuilder(Other);
  OtherBuilder.CreateStore(llvm::ConstantInt::get(I64, 7), CopySlot);
  OtherBuilder.CreateBr(Epi);
  llvm::IRBuilder<> EpiBuilder(Epi);
  EpiBuilder.CreateCall(Observe, {CopySlot});
  EpiBuilder.CreateCall(Dtor, {Obj});
  EpiBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("live_copy_return(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  EXPECT_NE(Source.find("observe_copy(", BodyAt), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("copy_slot0 =", BodyAt), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("observe_copy(&copy_slot", BodyAt), std::string::npos)
      << Source;
}

TEST(LLVMCPointerAddresses, PrintsSharedReturnEpilogueAtGotoEdges) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-shared-return", Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::FunctionType *DtorTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *WorkA = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "work_a", Module);
  llvm::Function *WorkB = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "work_b", Module);
  llvm::Function *Dtor = llvm::Function::Create(
      DtorTy, llvm::GlobalValue::ExternalLinkage, "obj_dtor", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {llvm::Type::getInt1Ty(Context)}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "shared_return", Module);
  Function->getArg(0)->setName("flag");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *ArmB =
      llvm::BasicBlock::Create(Context, "arm_b", Function);
  llvm::BasicBlock *ArmA =
      llvm::BasicBlock::Create(Context, "arm_a", Function);
  llvm::BasicBlock *Epi = llvm::BasicBlock::Create(Context, "epi", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  auto *Obj = EntryBuilder.CreateAlloca(Ptr, nullptr, "obj");
  EntryBuilder.CreateCondBr(Function->getArg(0), ArmA, ArmB);
  llvm::IRBuilder<> ABuilder(ArmA);
  ABuilder.CreateCall(WorkA);
  ABuilder.CreateBr(Epi);
  llvm::IRBuilder<> BBuilder(ArmB);
  BBuilder.CreateCall(WorkB);
  BBuilder.CreateBr(Epi);
  llvm::IRBuilder<> EpiBuilder(Epi);
  EpiBuilder.CreateCall(Dtor, {Obj});
  EpiBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("shared_return(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto WorkAAt = Source.find("work_a(", BodyAt);
  const auto WorkBAt = Source.find("work_b(", BodyAt);
  const auto RelAt = Source.find("obj_dtor(", BodyAt);
  const auto Rel2 = RelAt == std::string::npos
                        ? std::string::npos
                        : Source.find("obj_dtor(", RelAt + 1);
  const auto GotoAt = Source.find("goto ", BodyAt);
  const auto LabelAt = Source.find("L_", BodyAt);
  EXPECT_NE(WorkAAt, std::string::npos) << Source;
  EXPECT_NE(WorkBAt, std::string::npos) << Source;
  EXPECT_NE(RelAt, std::string::npos) << Source;
  EXPECT_NE(Rel2, std::string::npos) << Source;
  EXPECT_LT(WorkAAt, RelAt) << Source;
  EXPECT_LT(RelAt, WorkBAt) << Source;
  EXPECT_LT(WorkBAt, Rel2) << Source;
  EXPECT_EQ(GotoAt, std::string::npos) << Source;
  EXPECT_EQ(LabelAt, std::string::npos) << Source;
  EXPECT_EQ(Source.find("work_a(", WorkAAt + 1), std::string::npos) << Source;
  EXPECT_EQ(Source.find("work_b(", WorkBAt + 1), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, KeepsGotoWhenReturnTailHasTwoCalls) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-two-call-return", Context);
  llvm::FunctionType *VoidTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *WorkA = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "work_a", Module);
  llvm::Function *WorkB = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "work_b", Module);
  llvm::Function *ReleaseA = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "release_a", Module);
  llvm::Function *ReleaseB = llvm::Function::Create(
      VoidTy, llvm::GlobalValue::ExternalLinkage, "release_b", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {llvm::Type::getInt1Ty(Context)}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "two_call_return", Module);
  Function->getArg(0)->setName("flag");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *ArmB =
      llvm::BasicBlock::Create(Context, "arm_b", Function);
  llvm::BasicBlock *ArmA =
      llvm::BasicBlock::Create(Context, "arm_a", Function);
  llvm::BasicBlock *Epi = llvm::BasicBlock::Create(Context, "epi", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  EntryBuilder.CreateCondBr(Function->getArg(0), ArmA, ArmB);
  llvm::IRBuilder<> ABuilder(ArmA);
  ABuilder.CreateCall(WorkA);
  ABuilder.CreateBr(Epi);
  llvm::IRBuilder<> BBuilder(ArmB);
  BBuilder.CreateCall(WorkB);
  BBuilder.CreateBr(Epi);
  llvm::IRBuilder<> EpiBuilder(Epi);
  EpiBuilder.CreateCall(ReleaseA);
  EpiBuilder.CreateCall(ReleaseB);
  EpiBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("two_call_return(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto AAt = Source.find("release_a(", BodyAt);
  const auto BAt = Source.find("release_b(", BodyAt);
  const auto A2 = AAt == std::string::npos ? std::string::npos
                                           : Source.find("release_a(", AAt + 1);
  const auto GotoAt = Source.find("goto L_epi", BodyAt);
  const auto LabelAt = Source.find("L_epi:", BodyAt);
  EXPECT_NE(AAt, std::string::npos) << Source;
  EXPECT_NE(BAt, std::string::npos) << Source;
  EXPECT_EQ(A2, std::string::npos) << Source;
  EXPECT_NE(GotoAt, std::string::npos) << Source;
  EXPECT_NE(LabelAt, std::string::npos) << Source;
  EXPECT_LT(GotoAt, LabelAt) << Source;
  EXPECT_LT(LabelAt, AAt) << Source;
}

TEST(LLVMCPointerAddresses, FoldsNullFieldDiamondIntoUse) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-null-field-diamond", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::get(Context, 0);
  llvm::FunctionType *UseTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Use = llvm::Function::Create(
      UseTy, llvm::GlobalValue::ExternalLinkage, "use_id", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "load_id", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Zero = llvm::BasicBlock::Create(Context, "zero", Function);
  llvm::BasicBlock *Field =
      llvm::BasicBlock::Create(Context, "field", Function);
  llvm::BasicBlock *Join = llvm::BasicBlock::Create(Context, "join", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  auto *Slot = EntryBuilder.CreateAlloca(I64, nullptr, "id_slot");
  llvm::Value *PtrNull = llvm::ConstantPointerNull::get(
      llvm::cast<llvm::PointerType>(Ptr));
  EntryBuilder.CreateCondBr(
      EntryBuilder.CreateICmpEQ(Function->getArg(0), PtrNull), Zero, Field);
  llvm::IRBuilder<> ZeroBuilder(Zero);
  ZeroBuilder.CreateStore(llvm::ConstantInt::get(I64, 0), Slot);
  ZeroBuilder.CreateBr(Join);
  llvm::IRBuilder<> FieldBuilder(Field);
  llvm::Value *Addr = FieldBuilder.CreateAdd(
      FieldBuilder.CreatePtrToInt(Function->getArg(0), I64),
      llvm::ConstantInt::get(I64, 8));
  llvm::Value *Loaded =
      FieldBuilder.CreateLoad(I64, FieldBuilder.CreateIntToPtr(Addr, Ptr));
  FieldBuilder.CreateStore(Loaded, Slot);
  FieldBuilder.CreateBr(Join);
  llvm::IRBuilder<> JoinBuilder(Join);
  JoinBuilder.CreateCall(Use, {JoinBuilder.CreateLoad(I64, Slot)});
  JoinBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("load_id(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto UseAt = Source.find("use_id(", BodyAt);
  ASSERT_NE(UseAt, std::string::npos) << Source;
  EXPECT_NE(Source.find("?", UseAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("} else {", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("= 0;", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("use_id(", UseAt + 1), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, FoldsAssignDiamondIntoIfElse) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-assign-diamond", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::FunctionType *UseTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Use = llvm::Function::Create(
      UseTy, llvm::GlobalValue::ExternalLinkage, "use_joined", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {llvm::Type::getInt1Ty(Context)}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "assign_diamond", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Left = llvm::BasicBlock::Create(Context, "left", Function);
  llvm::BasicBlock *Right =
      llvm::BasicBlock::Create(Context, "right", Function);
  llvm::BasicBlock *Join = llvm::BasicBlock::Create(Context, "join", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  auto *Slot = EntryBuilder.CreateAlloca(I64, nullptr, "joined_slot");
  EntryBuilder.CreateCondBr(Function->getArg(0), Left, Right);
  llvm::IRBuilder<> LeftBuilder(Left);
  LeftBuilder.CreateStore(llvm::ConstantInt::get(I64, 1), Slot);
  LeftBuilder.CreateBr(Join);
  llvm::IRBuilder<> RightBuilder(Right);
  RightBuilder.CreateStore(llvm::ConstantInt::get(I64, 0), Slot);
  RightBuilder.CreateBr(Join);
  llvm::IRBuilder<> JoinBuilder(Join);
  llvm::Value *Loaded = JoinBuilder.CreateLoad(I64, Slot, "joined_val");
  JoinBuilder.CreateCall(Use, {Loaded});
  JoinBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto IfAt = Source.find("if (");
  const auto ElseAt = Source.find("} else {", IfAt);
  const auto OneAt = Source.find("= 1;", IfAt);
  const auto ZeroAt = Source.find("= 0;", ElseAt);
  ASSERT_NE(IfAt, std::string::npos) << Source;
  ASSERT_NE(ElseAt, std::string::npos) << Source;
  ASSERT_NE(OneAt, std::string::npos) << Source;
  ASSERT_NE(ZeroAt, std::string::npos) << Source;
  EXPECT_LT(OneAt, ElseAt) << Source;
  EXPECT_LT(ElseAt, ZeroAt) << Source;
  EXPECT_EQ(Source.find("goto"), std::string::npos) << Source;
  EXPECT_NE(Source.find("use_joined("), std::string::npos) << Source;
  const auto DiamondAt = Source.find("assign_diamond(");
  ASSERT_NE(DiamondAt, std::string::npos) << Source;
  EXPECT_EQ(Source.find("L_", DiamondAt), std::string::npos) << Source;
}

