TEST(LLVMCPointerAddresses, InlinesSinglePredPhiAssignArm) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-phi-assign", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::FunctionType *UseTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Use = llvm::Function::Create(
      UseTy, llvm::GlobalValue::ExternalLinkage, "use_picked", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {llvm::Type::getInt1Ty(Context)}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "phi_assign_arm", Module);
  Function->getArg(0)->setName("flag");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Also =
      llvm::BasicBlock::Create(Context, "also", Function);
  llvm::BasicBlock *Shared =
      llvm::BasicBlock::Create(Context, "shared", Function);
  llvm::BasicBlock *Pick =
      llvm::BasicBlock::Create(Context, "pick", Function);
  llvm::BasicBlock *Join =
      llvm::BasicBlock::Create(Context, "join", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  auto *Slot = EntryBuilder.CreateAlloca(I64, nullptr, "picked");
  EntryBuilder.CreateCondBr(Function->getArg(0), Pick, Shared);
  llvm::IRBuilder<> AlsoBuilder(Also);
  AlsoBuilder.CreateBr(Shared);
  llvm::IRBuilder<> SharedBuilder(Shared);
  SharedBuilder.CreateStore(llvm::ConstantInt::get(I64, 2), Slot);
  SharedBuilder.CreateBr(Join);
  llvm::IRBuilder<> PickBuilder(Pick);
  PickBuilder.CreateStore(llvm::ConstantInt::get(I64, 1), Slot);
  PickBuilder.CreateBr(Join);
  llvm::IRBuilder<> JoinBuilder(Join);
  llvm::Value *Loaded = JoinBuilder.CreateLoad(I64, Slot, "picked_val");
  JoinBuilder.CreateCall(Use, {Loaded});
  JoinBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("phi_assign_arm(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto IfAt = Source.find("if (", BodyAt);
  const auto OneAt = Source.find("= 1;", IfAt);
  const auto GotoAt = Source.find("goto L_join;", IfAt);
  const auto TwoAt = Source.find("= 2;", BodyAt);
  const auto UseAt = Source.find("use_picked(", BodyAt);
  ASSERT_NE(IfAt, std::string::npos) << Source;
  ASSERT_NE(OneAt, std::string::npos) << Source;
  ASSERT_NE(GotoAt, std::string::npos) << Source;
  ASSERT_NE(TwoAt, std::string::npos) << Source;
  ASSERT_NE(UseAt, std::string::npos) << Source;
  EXPECT_LT(IfAt, OneAt) << Source;
  EXPECT_LT(OneAt, GotoAt) << Source;
  EXPECT_LT(GotoAt, TwoAt) << Source;
  EXPECT_LT(TwoAt, UseAt) << Source;
  EXPECT_EQ(Source.find("L_pick:", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("= 1;", OneAt + 4), std::string::npos) << Source;
  EXPECT_EQ(Source.find("= 2;", TwoAt + 4), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, KeepsAssignArmOutsideInvertedSkip) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-phi-assign-skip", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::FunctionType *WorkTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Arm = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "arm_step", Module);
  llvm::FunctionType *UseTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Use = llvm::Function::Create(
      UseTy, llvm::GlobalValue::ExternalLinkage, "use_picked", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {llvm::Type::getInt1Ty(Context)}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "phi_assign_skip", Module);
  Function->getArg(0)->setName("flag");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Body = llvm::BasicBlock::Create(Context, "body", Function);
  llvm::BasicBlock *Pick =
      llvm::BasicBlock::Create(Context, "pick", Function);
  llvm::BasicBlock *After =
      llvm::BasicBlock::Create(Context, "after", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  auto *Slot = EntryBuilder.CreateAlloca(I64, nullptr, "picked");
  EntryBuilder.CreateCondBr(Function->getArg(0), Pick, Body);
  llvm::IRBuilder<> BodyBuilder(Body);
  BodyBuilder.CreateCall(Arm);
  BodyBuilder.CreateStore(llvm::ConstantInt::get(I64, 2), Slot);
  BodyBuilder.CreateBr(After);
  llvm::IRBuilder<> PickBuilder(Pick);
  PickBuilder.CreateStore(llvm::ConstantInt::get(I64, 1), Slot);
  PickBuilder.CreateBr(After);
  llvm::IRBuilder<> AfterBuilder(After);
  llvm::Value *Loaded = AfterBuilder.CreateLoad(I64, Slot, "picked_val");
  AfterBuilder.CreateCall(Use, {Loaded});
  AfterBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("phi_assign_skip(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto IfAt = Source.find("if (!(flag))", BodyAt);
  const auto ArmAt = Source.find("arm_step(", BodyAt);
  const auto TwoAt = Source.find("= 2;", BodyAt);
  const auto OneAt = Source.find("= 1;", BodyAt);
  const auto UseAt = Source.find("use_picked(", BodyAt);
  ASSERT_NE(IfAt, std::string::npos) << Source;
  ASSERT_NE(ArmAt, std::string::npos) << Source;
  ASSERT_NE(TwoAt, std::string::npos) << Source;
  ASSERT_NE(OneAt, std::string::npos) << Source;
  ASSERT_NE(UseAt, std::string::npos) << Source;
  EXPECT_LT(IfAt, ArmAt) << Source;
  EXPECT_LT(ArmAt, TwoAt) << Source;
  EXPECT_LT(TwoAt, OneAt) << Source;
  EXPECT_LT(OneAt, UseAt) << Source;
  EXPECT_EQ(Source.find("if (flag)", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("L_pick:", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("arm_step(", ArmAt + 1), std::string::npos) << Source;
  EXPECT_EQ(Source.find("= 1;", OneAt + 4), std::string::npos) << Source;
  EXPECT_EQ(Source.find("= 2;", TwoAt + 4), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, FoldsConditionChainIntoConjunctionElse) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-cond-chain", Context);
  llvm::FunctionType *WorkTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Hit = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "hit_step", Module);
  llvm::Function *Miss = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "miss_step", Module);
  llvm::Function *Use = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "use_step", Module);
  llvm::Type *I1 = llvm::Type::getInt1Ty(Context);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I1, I1, I1}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "cond_chain", Module);
  Function->getArg(0)->setName("flag");
  Function->getArg(1)->setName("flag2");
  Function->getArg(2)->setName("flag3");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Check2 =
      llvm::BasicBlock::Create(Context, "check2", Function);
  llvm::BasicBlock *Check3 =
      llvm::BasicBlock::Create(Context, "check3", Function);
  llvm::BasicBlock *HitBB =
      llvm::BasicBlock::Create(Context, "hit", Function);
  llvm::BasicBlock *MissBB =
      llvm::BasicBlock::Create(Context, "miss", Function);
  llvm::BasicBlock *After =
      llvm::BasicBlock::Create(Context, "after", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  EntryBuilder.CreateCondBr(Function->getArg(0), Check2, MissBB);
  llvm::IRBuilder<> Check2Builder(Check2);
  Check2Builder.CreateCondBr(Function->getArg(1), Check3, MissBB);
  llvm::IRBuilder<> Check3Builder(Check3);
  Check3Builder.CreateCondBr(Function->getArg(2), HitBB, MissBB);
  llvm::IRBuilder<> HitBuilder(HitBB);
  HitBuilder.CreateCall(Hit);
  HitBuilder.CreateBr(After);
  llvm::IRBuilder<> MissBuilder(MissBB);
  MissBuilder.CreateCall(Miss);
  MissBuilder.CreateBr(After);
  llvm::IRBuilder<> AfterBuilder(After);
  AfterBuilder.CreateCall(Use);
  AfterBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("cond_chain(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto IfAt = Source.find("if (flag && flag2 && flag3)", BodyAt);
  const auto HitAt = Source.find("hit_step(", BodyAt);
  const auto ElseAt = Source.find("} else {", BodyAt);
  const auto MissAt = Source.find("miss_step(", BodyAt);
  const auto UseAt = Source.find("use_step(", BodyAt);
  ASSERT_NE(IfAt, std::string::npos) << Source;
  ASSERT_NE(HitAt, std::string::npos) << Source;
  ASSERT_NE(ElseAt, std::string::npos) << Source;
  ASSERT_NE(MissAt, std::string::npos) << Source;
  ASSERT_NE(UseAt, std::string::npos) << Source;
  EXPECT_LT(IfAt, HitAt) << Source;
  EXPECT_LT(HitAt, ElseAt) << Source;
  EXPECT_LT(ElseAt, MissAt) << Source;
  EXPECT_LT(MissAt, UseAt) << Source;
  EXPECT_EQ(Source.find("goto ", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("L_", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("hit_step(", HitAt + 1), std::string::npos) << Source;
  EXPECT_EQ(Source.find("miss_step(", MissAt + 1), std::string::npos) << Source;
}

