  llvm::BasicBlock *Other =
      llvm::BasicBlock::Create(Context, "other", Function);
  llvm::BasicBlock *Join = llvm::BasicBlock::Create(Context, "join", Function);
  llvm::BasicBlock *Hop = llvm::BasicBlock::Create(Context, "hop", Function);
  llvm::BasicBlock *Later =
      llvm::BasicBlock::Create(Context, "later", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  EntryBuilder.CreateCondBr(Function->getArg(0), Hop, Other);
  llvm::IRBuilder<> OtherBuilder(Other);
  OtherBuilder.CreateCall(OtherFn);
  OtherBuilder.CreateBr(Join);
  llvm::IRBuilder<> JoinBuilder(Join);
  JoinBuilder.CreateCall(Use);
  JoinBuilder.CreateRetVoid();
  llvm::IRBuilder<> HopBuilder(Hop);
  HopBuilder.CreateBr(Later);
  llvm::IRBuilder<> LaterBuilder(Later);
  LaterBuilder.CreateCall(LaterFn);
  LaterBuilder.CreateBr(Join);

  std::string Source;
