TEST(LLVMCPointerAddresses, InvertsSkipOverRegionBeforeTarget) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-skip-region", Context);
  llvm::FunctionType *WorkTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *WorkFn = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "work_step", Module);
  llvm::Function *MoreFn = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "more_step", Module);
  llvm::Function *SkipFn = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "skip_step", Module);
  llvm::Function *TailFn = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "tail_step", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {llvm::Type::getInt1Ty(Context)}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "skip_region", Module);
  Function->getArg(0)->setName("flag");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Work = llvm::BasicBlock::Create(Context, "work", Function);
  llvm::BasicBlock *More = llvm::BasicBlock::Create(Context, "more", Function);
  llvm::BasicBlock *Skip = llvm::BasicBlock::Create(Context, "skip", Function);
  llvm::BasicBlock *Tail = llvm::BasicBlock::Create(Context, "tail", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  EntryBuilder.CreateCondBr(Function->getArg(0), Skip, Work);
  llvm::IRBuilder<> WorkBuilder(Work);
  WorkBuilder.CreateCall(WorkFn);
  WorkBuilder.CreateBr(More);
  llvm::IRBuilder<> MoreBuilder(More);
  MoreBuilder.CreateCall(MoreFn);
  MoreBuilder.CreateBr(Tail);
  llvm::IRBuilder<> SkipBuilder(Skip);
  SkipBuilder.CreateCall(SkipFn);
  SkipBuilder.CreateRetVoid();
  llvm::IRBuilder<> TailBuilder(Tail);
  TailBuilder.CreateCall(TailFn);
  TailBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("skip_region(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto IfAt = Source.find("if (!(flag))", BodyAt);
  const auto WorkAt = Source.find("work_step(", BodyAt);
  const auto MoreAt = Source.find("more_step(", BodyAt);
  const auto GotoAt = Source.find("goto L_tail;", BodyAt);
  const auto SkipAt = Source.find("skip_step(", BodyAt);
  const auto TailAt = Source.find("tail_step(", BodyAt);
  ASSERT_NE(IfAt, std::string::npos) << Source;
  ASSERT_NE(WorkAt, std::string::npos) << Source;
  ASSERT_NE(MoreAt, std::string::npos) << Source;
  ASSERT_NE(GotoAt, std::string::npos) << Source;
  ASSERT_NE(SkipAt, std::string::npos) << Source;
  ASSERT_NE(TailAt, std::string::npos) << Source;
  EXPECT_LT(IfAt, WorkAt) << Source;
  EXPECT_LT(WorkAt, MoreAt) << Source;
  EXPECT_LT(MoreAt, GotoAt) << Source;
  EXPECT_LT(GotoAt, SkipAt) << Source;
  EXPECT_LT(SkipAt, TailAt) << Source;
  EXPECT_EQ(Source.find("goto L_skip;", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("work_step(", WorkAt + 1), std::string::npos) << Source;
  EXPECT_EQ(Source.find("more_step(", MoreAt + 1), std::string::npos) << Source;
  EXPECT_EQ(Source.find("skip_step(", SkipAt + 1), std::string::npos) << Source;
  EXPECT_EQ(Source.find("tail_step(", TailAt + 1), std::string::npos) << Source;
}

