      llvm::BasicBlock::Create(Context, "shared", Function);
  llvm::BasicBlock *Skip1 =
      llvm::BasicBlock::Create(Context, "skip1", Function);
  llvm::BasicBlock *Head2 =
      llvm::BasicBlock::Create(Context, "head2", Function);
  llvm::BasicBlock *Period2 =
      llvm::BasicBlock::Create(Context, "period2", Function);
  llvm::BasicBlock *Use2 = llvm::BasicBlock::Create(Context, "use2", Function);
