  Period1Builder.CreateCall(PeriodA);
  Period1Builder.CreateCondBr(Function->getArg(1), ToCtor1, Use1);
  llvm::IRBuilder<> Use1Builder(Use1);
  Use1Builder.CreateCall(UseA);
  Use1Builder.CreateBr(Cleanup);
  llvm::IRBuilder<> ToCtor1Builder(ToCtor1);
  ToCtor1Builder.CreateBr(Shared);
  llvm::IRBuilder<> SharedBuilder(Shared);
  SharedBuilder.CreateCall(CtorFn);
  SharedBuilder.CreateBr(Finished);
  llvm::IRBuilder<> Skip1Builder(Skip1);
  Skip1Builder.CreateBr(Head2);
