TEST(LLVMCPointerAddresses, KeepsSharedAssignGotoWhenDefaultHasAnotherEntry) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-shared-assign-extra", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::FunctionType *WorkTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Prep = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "prep_step", Module);
  llvm::Function *Tail = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "tail_step", Module);
  llvm::FunctionType *UseTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Use = llvm::Function::Create(
      UseTy, llvm::GlobalValue::ExternalLinkage, "use_picked", Module);
  llvm::Type *I1 = llvm::Type::getInt1Ty(Context);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {I1, I1, I1}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "shared_assign_extra", Module);
  Function->getArg(0)->setName("flag");
  Function->getArg(1)->setName("flag2");
  Function->getArg(2)->setName("flag3");
  llvm::BasicBlock *Head = llvm::BasicBlock::Create(Context, "head", Function);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Body = llvm::BasicBlock::Create(Context, "body", Function);
  llvm::BasicBlock *Alt = llvm::BasicBlock::Create(Context, "alt", Function);
  llvm::BasicBlock *Def = llvm::BasicBlock::Create(Context, "def", Function);
  llvm::BasicBlock *Join = llvm::BasicBlock::Create(Context, "join", Function);
  llvm::BasicBlock *Side = llvm::BasicBlock::Create(Context, "side", Function);
  llvm::IRBuilder<> HeadBuilder(Head);
  HeadBuilder.CreateCondBr(Function->getArg(2), Side, Entry);
  llvm::IRBuilder<> EntryBuilder(Entry);
  auto *Slot = EntryBuilder.CreateAlloca(I64, nullptr, "picked");
  EntryBuilder.CreateCondBr(Function->getArg(0), Def, Body);
  llvm::IRBuilder<> BodyBuilder(Body);
  BodyBuilder.CreateCall(Prep);
  BodyBuilder.CreateCondBr(Function->getArg(1), Def, Alt);
  llvm::IRBuilder<> DefBuilder(Def);
  DefBuilder.CreateStore(llvm::ConstantInt::get(I64, 0), Slot);
  DefBuilder.CreateBr(Join);
  llvm::IRBuilder<> AltBuilder(Alt);
  AltBuilder.CreateStore(llvm::ConstantInt::get(I64, 1), Slot);
  AltBuilder.CreateBr(Join);
  llvm::IRBuilder<> JoinBuilder(Join);
  llvm::Value *Loaded = JoinBuilder.CreateLoad(I64, Slot, "picked_val");
  JoinBuilder.CreateCall(Use, {Loaded});
  JoinBuilder.CreateRetVoid();
  llvm::IRBuilder<> SideBuilder(Side);
  SideBuilder.CreateCall(Tail);
  SideBuilder.CreateBr(Def);

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("shared_assign_extra(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto TailAt = Source.find("tail_step(", BodyAt);
  const auto PrepAt = Source.find("prep_step(", BodyAt);
  const auto OneAt = Source.find("= 1;", BodyAt);
  const auto ZeroAt = Source.find("= 0;", BodyAt);
  const auto UseAt = Source.find("use_picked(", BodyAt);
  const auto GotoAt = Source.find("goto ", BodyAt);
  ASSERT_NE(TailAt, std::string::npos) << Source;
  ASSERT_NE(PrepAt, std::string::npos) << Source;
  ASSERT_NE(OneAt, std::string::npos) << Source;
  ASSERT_NE(ZeroAt, std::string::npos) << Source;
  ASSERT_NE(UseAt, std::string::npos) << Source;
  ASSERT_NE(GotoAt, std::string::npos) << Source;
  EXPECT_EQ(Source.find("= 0;", ZeroAt + 4), std::string::npos) << Source;
  EXPECT_EQ(Source.find("= 1;", OneAt + 4), std::string::npos) << Source;
  EXPECT_EQ(Source.find("tail_step(", TailAt + 1), std::string::npos) << Source;
  EXPECT_EQ(Source.find("prep_step(", PrepAt + 1), std::string::npos) << Source;
  EXPECT_EQ(Source.find("use_picked(", UseAt + 1), std::string::npos) << Source;
}

