TEST(LLVMCPointerAddresses, InlinesDivisionTrapAtTheCheck) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-div-trap", Context);
  llvm::FunctionType *WorkTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Work = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "work_step", Module);
  llvm::Function *Trap = llvm::Intrinsic::getOrInsertDeclaration(
      &Module, llvm::Intrinsic::trap);
  llvm::Function *Hit = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "hit_step", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {llvm::Type::getInt1Ty(Context),
                                       llvm::Type::getInt1Ty(Context)},
      false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "div_trap", Module);
  Function->getArg(0)->setName("present");
  Function->getArg(1)->setName("overflow");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Check =
      llvm::BasicBlock::Create(Context, "check", Function);
  llvm::BasicBlock *Search =
      llvm::BasicBlock::Create(Context, "search", Function);
  llvm::BasicBlock *Done = llvm::BasicBlock::Create(Context, "done", Function);
  llvm::BasicBlock *Fail = llvm::BasicBlock::Create(Context, "fail", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  EntryBuilder.CreateCondBr(Function->getArg(0), Check, Done);
  llvm::IRBuilder<> CheckBuilder(Check);
  CheckBuilder.CreateCondBr(Function->getArg(1), Fail, Search);
  llvm::IRBuilder<> SearchBuilder(Search);
  SearchBuilder.CreateCall(Work);
  SearchBuilder.CreateBr(Done);
  llvm::IRBuilder<> DoneBuilder(Done);
  DoneBuilder.CreateCall(Hit);
  DoneBuilder.CreateRetVoid();
  llvm::IRBuilder<> FailBuilder(Fail);
  FailBuilder.CreateCall(Trap);
  FailBuilder.CreateUnreachable();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("div_trap(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto TrapAt = Source.find("__builtin_trap()", BodyAt);
  const auto UnreachAt = Source.find("__builtin_unreachable()", BodyAt);
  const auto WorkAt = Source.find("work_step(", BodyAt);
  const auto HitAt = Source.find("hit_step(", BodyAt);
  const auto Trap2 = TrapAt == std::string::npos
                         ? std::string::npos
                         : Source.find("__builtin_trap()", TrapAt + 1);
  EXPECT_NE(TrapAt, std::string::npos) << Source;
  EXPECT_NE(UnreachAt, std::string::npos) << Source;
  EXPECT_NE(WorkAt, std::string::npos) << Source;
  EXPECT_NE(HitAt, std::string::npos) << Source;
  EXPECT_LT(TrapAt, UnreachAt) << Source;
  EXPECT_LT(UnreachAt, WorkAt) << Source;
  EXPECT_LT(WorkAt, HitAt) << Source;
  EXPECT_EQ(Trap2, std::string::npos) << Source;
  EXPECT_EQ(Source.find("goto L_fail", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("L_fail:", BodyAt), std::string::npos) << Source;
}

