TEST(LLVMCPointerAddresses, InvertsSkipGotoKeepsOutgoingGoto) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-skip-tail", Context);
  llvm::FunctionType *WorkTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Arm = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "arm_step", Module);
  llvm::Function *Use = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "use_step", Module);
  llvm::Function *Later = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "later_step", Module);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context),
      {llvm::Type::getInt1Ty(Context), llvm::Type::getInt1Ty(Context)}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "skip_false_tail", Module);
  Function->getArg(0)->setName("flag");
  Function->getArg(1)->setName("flag2");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Body = llvm::BasicBlock::Create(Context, "body", Function);
  llvm::BasicBlock *After =
      llvm::BasicBlock::Create(Context, "after", Function);
  llvm::BasicBlock *LaterBB =
      llvm::BasicBlock::Create(Context, "later", Function);
  llvm::BasicBlock *Left = llvm::BasicBlock::Create(Context, "left", Function);
  llvm::BasicBlock *Right =
      llvm::BasicBlock::Create(Context, "right", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  EntryBuilder.CreateCondBr(Function->getArg(0), After, Body);
  llvm::IRBuilder<> BodyBuilder(Body);
  BodyBuilder.CreateCall(Arm);
  BodyBuilder.CreateBr(LaterBB);
  llvm::IRBuilder<> AfterBuilder(After);
  AfterBuilder.CreateCall(Use);
  AfterBuilder.CreateCondBr(Function->getArg(1), Left, Right);
  llvm::IRBuilder<> LaterBuilder(LaterBB);
  LaterBuilder.CreateCall(Later);
  LaterBuilder.CreateRetVoid();
  llvm::IRBuilder<> LeftBuilder(Left);
  LeftBuilder.CreateRetVoid();
  llvm::IRBuilder<> RightBuilder(Right);
  RightBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("skip_false_tail(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  const auto ArmAt = Source.find("arm_step(", BodyAt);
  const auto UseAt = Source.find("use_step(", BodyAt);
  const auto LaterAt = Source.find("later_step(", BodyAt);
  const auto GotoAt = Source.find("goto L_later;", BodyAt);
  const auto IfAt = Source.find("if (!(flag))", BodyAt);
  ASSERT_NE(ArmAt, std::string::npos) << Source;
  ASSERT_NE(UseAt, std::string::npos) << Source;
  ASSERT_NE(LaterAt, std::string::npos) << Source;
  ASSERT_NE(GotoAt, std::string::npos) << Source;
  ASSERT_NE(IfAt, std::string::npos) << Source;
  EXPECT_LT(IfAt, ArmAt) << Source;
  EXPECT_LT(ArmAt, GotoAt) << Source;
  EXPECT_LT(GotoAt, UseAt) << Source;
  EXPECT_LT(UseAt, LaterAt) << Source;
  EXPECT_EQ(Source.find("L_body:", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("L_after:", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("goto L_after;", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("arm_step(", ArmAt + 1), std::string::npos) << Source;
}

