TEST(LLVMCPointerAddresses, NarrowWidenMulUsesUnsignedCarrier) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-narrow-carrier", Context);
  llvm::Type *I16 = llvm::Type::getInt16Ty(Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  auto AddFn = [&](bool Sign, llvm::Instruction::BinaryOps Op,
                   const char *Name) {
    llvm::FunctionType *FnTy = llvm::FunctionType::get(I16, {I16, I16}, false);
    llvm::Function *Function = llvm::Function::Create(
        FnTy, llvm::GlobalValue::ExternalLinkage, Name, Module);
    Function->getArg(0)->setName("left");
    Function->getArg(1)->setName("right");
    llvm::IRBuilder<> Builder(
        llvm::BasicBlock::Create(Context, "entry", Function));
    llvm::Value *L = Sign ? Builder.CreateSExt(Function->getArg(0), I32)
                          : Builder.CreateZExt(Function->getArg(0), I32);
    llvm::Value *R = Sign ? Builder.CreateSExt(Function->getArg(1), I32)
                          : Builder.CreateZExt(Function->getArg(1), I32);
    Builder.CreateRet(Builder.CreateTrunc(Builder.CreateBinOp(Op, L, R), I16));
  };
  AddFn(false, llvm::Instruction::Mul, "zext_mul16");
  AddFn(true, llvm::Instruction::Mul, "sext_mul16");
  AddFn(false, llvm::Instruction::Add, "zext_add16");
  AddFn(true, llvm::Instruction::Sub, "sext_sub16");

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  auto Body = [&](const char *Name) {
    const auto At = Source.find(std::string(Name) + "(");
    EXPECT_NE(At, std::string::npos) << Source;
    return At;
  };
  const auto Mul = Body("zext_mul16");
  const auto SMul = Body("sext_mul16");
  const auto Add = Body("zext_add16");
  const auto Sub = Body("sext_sub16");
  EXPECT_NE(Source.find("(uint16_t)((uint32_t)left * (uint32_t)right)", Mul),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("(uint16_t)((uint32_t)left * (uint32_t)right)", SMul),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("(uint16_t)((uint32_t)left + (uint32_t)right)", Add),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("(uint16_t)((uint32_t)left - (uint32_t)right)", Sub),
            std::string::npos)
      << Source;
}

TEST(LLVMCPointerAddresses, SameTargetSkipGotosComposeAnd) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-skip-and", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::FunctionType *WorkTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Taken = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "taken_step", Module);
  llvm::Function *Rest = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "rest_step", Module);
  llvm::FunctionType *KindTy = llvm::FunctionType::get(I64, {I64}, false);
  llvm::Function *Kind = llvm::Function::Create(
      KindTy, llvm::GlobalValue::ExternalLinkage, "IsKind", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "skip_and", Module);
  Function->getArg(0)->setName("record");
  llvm::Function *Other = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "other_step", Module);
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *KindBB =
      llvm::BasicBlock::Create(Context, "kind", Function);
  llvm::BasicBlock *Work =
      llvm::BasicBlock::Create(Context, "work", Function);
  llvm::BasicBlock *Tail =
      llvm::BasicBlock::Create(Context, "tail", Function);
  llvm::BasicBlock *Skip =
      llvm::BasicBlock::Create(Context, "skip", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  EntryBuilder.CreateCondBr(
      EntryBuilder.CreateICmpEQ(Function->getArg(0),
                                llvm::ConstantInt::get(I64, 0)),
      Skip, KindBB);
  llvm::IRBuilder<> KindBuilder(KindBB);
  llvm::Value *Call = KindBuilder.CreateCall(Kind, {Function->getArg(0)});
  KindBuilder.CreateCondBr(
      KindBuilder.CreateICmpEQ(Call, llvm::ConstantInt::get(I64, 0)), Skip,
      Work);
  llvm::IRBuilder<> WorkBuilder(Work);
  WorkBuilder.CreateCall(Taken);
  WorkBuilder.CreateBr(Tail);
  llvm::IRBuilder<> TailBuilder(Tail);
  TailBuilder.CreateCall(Other);
  TailBuilder.CreateRetVoid();
  llvm::IRBuilder<> SkipBuilder(Skip);
  SkipBuilder.CreateCall(Rest);
  SkipBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("skip_and(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  EXPECT_NE(Source.find("if (!(record && IsKind(record)))", BodyAt),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("taken_step(", BodyAt), std::string::npos) << Source;
  EXPECT_NE(Source.find("other_step(", BodyAt), std::string::npos) << Source;
  EXPECT_NE(Source.find("rest_step(", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("IsKind(", Source.find("IsKind(", BodyAt) + 1),
            std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("goto ", Source.find("goto ", BodyAt) + 1),
            std::string::npos)
      << Source;
}

TEST(LLVMCPointerAddresses, SameTargetSkipGotosKeepDuplicateCall) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-skip-dup", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::FunctionType *WorkTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Taken = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "taken_step", Module);
  llvm::FunctionType *KindTy = llvm::FunctionType::get(I64, {I64}, false);
  llvm::Function *Kind = llvm::Function::Create(
      KindTy, llvm::GlobalValue::ExternalLinkage, "IsKind", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "skip_dup", Module);
  Function->getArg(0)->setName("record");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *Again =
      llvm::BasicBlock::Create(Context, "again", Function);
  llvm::BasicBlock *Work =
      llvm::BasicBlock::Create(Context, "work", Function);
  llvm::BasicBlock *Skip =
      llvm::BasicBlock::Create(Context, "skip", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  EntryBuilder.CreateCondBr(
      EntryBuilder.CreateICmpEQ(
          EntryBuilder.CreateCall(Kind, {Function->getArg(0)}),
          llvm::ConstantInt::get(I64, 0)),
      Skip, Again);
  llvm::IRBuilder<> AgainBuilder(Again);
  AgainBuilder.CreateCondBr(
      AgainBuilder.CreateICmpEQ(
          AgainBuilder.CreateCall(Kind, {Function->getArg(0)}),
          llvm::ConstantInt::get(I64, 0)),
      Skip, Work);
  llvm::IRBuilder<> WorkBuilder(Work);
  WorkBuilder.CreateCall(Taken);
  WorkBuilder.CreateBr(Skip);
  llvm::IRBuilder<> SkipBuilder(Skip);
  SkipBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("skip_dup(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  size_t Count = 0;
  for (size_t Pos = BodyAt;
       (Pos = Source.find("IsKind(", Pos)) != std::string::npos; Pos += 7)
    ++Count;
  EXPECT_EQ(Count, 2u) << Source;
  EXPECT_EQ(Source.find("&&", BodyAt), std::string::npos) << Source;
  EXPECT_NE(Source.find("taken_step(", BodyAt), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, SameTargetSkipGotosForwardsStoredCall) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-skip-home", Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::FunctionType *WorkTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), false);
  llvm::Function *Taken = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "taken_step", Module);
  llvm::Function *Other = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "other_step", Module);
  llvm::Function *Rest = llvm::Function::Create(
      WorkTy, llvm::GlobalValue::ExternalLinkage, "rest_step", Module);
  llvm::FunctionType *KindTy = llvm::FunctionType::get(I64, {I64}, false);
  llvm::Function *Kind = llvm::Function::Create(
      KindTy, llvm::GlobalValue::ExternalLinkage, "IsKind", Module);
  llvm::FunctionType *FnTy =
      llvm::FunctionType::get(llvm::Type::getVoidTy(Context), {I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "skip_home", Module);
  Function->getArg(0)->setName("record");
  llvm::BasicBlock *Entry =
      llvm::BasicBlock::Create(Context, "entry", Function);
  llvm::BasicBlock *KindBB =
      llvm::BasicBlock::Create(Context, "kind", Function);
  llvm::BasicBlock *Work =
      llvm::BasicBlock::Create(Context, "work", Function);
  llvm::BasicBlock *Tail =
      llvm::BasicBlock::Create(Context, "tail", Function);
  llvm::BasicBlock *Skip =
      llvm::BasicBlock::Create(Context, "skip", Function);
  llvm::IRBuilder<> EntryBuilder(Entry);
  llvm::AllocaInst *Home = EntryBuilder.CreateAlloca(I64, nullptr, "home");
  EntryBuilder.CreateStore(llvm::ConstantInt::get(I64, 0), Home);
  EntryBuilder.CreateCondBr(
      EntryBuilder.CreateICmpEQ(Function->getArg(0),
                                llvm::ConstantInt::get(I64, 0)),
      Skip, KindBB);
  llvm::IRBuilder<> KindBuilder(KindBB);
  llvm::Value *Call = KindBuilder.CreateCall(Kind, {Function->getArg(0)});
  KindBuilder.CreateStore(Call, Home);
  KindBuilder.CreateCondBr(
      KindBuilder.CreateICmpEQ(KindBuilder.CreateLoad(I64, Home),
                               llvm::ConstantInt::get(I64, 0)),
      Skip, Work);
  llvm::IRBuilder<> WorkBuilder(Work);
  WorkBuilder.CreateCall(Taken);
  WorkBuilder.CreateBr(Tail);
  llvm::IRBuilder<> TailBuilder(Tail);
  TailBuilder.CreateCall(Other);
  TailBuilder.CreateRetVoid();
  llvm::IRBuilder<> SkipBuilder(Skip);
  SkipBuilder.CreateCall(Rest);
  SkipBuilder.CreateRetVoid();

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options));
  OS.flush();
  const auto BodyAt = Source.find("skip_home(");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  EXPECT_NE(Source.find("if (!(record && IsKind(record)))", BodyAt),
            std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("IsKind(", Source.find("IsKind(", BodyAt) + 1),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("taken_step(", BodyAt), std::string::npos) << Source;
  EXPECT_NE(Source.find("other_step(", BodyAt), std::string::npos) << Source;
  EXPECT_NE(Source.find("rest_step(", BodyAt), std::string::npos) << Source;
  EXPECT_EQ(Source.find("goto ", Source.find("goto ", BodyAt) + 1),
            std::string::npos)
      << Source;
}

