      Kind->FieldDisplayNames = {"KindA", "KindB"};
      Kind->FieldDisplayOffsets = {7, 8};
      FunctionSym FS;
      FS.Name = "takeKind";
      FS.Addr = Addr;
      FS.ReturnType = NdType::makeVoid();
      FS.Params.emplace_back("kind", Kind);
