TEST(HighCPointerAddresses, ZeroArgMsvcThrowCtorDropsStaleCallOperands) {
  constexpr va_t Base = 0x140000000;
  constexpr va_t ThrowInfo = Base + 0x1100;
  constexpr va_t ThrownObject = Base + 0x1280;
  BinaryImage Img;
  Img.Arch = Arch::X64;
  Img.Format = BinaryFormat::COFF;
  Img.Bits = Bitness::Bits64;
  Img.Base = Base;
  Segment Data;
  Data.Name = ".rdata";
  Data.VA = Base + 0x1000;
  Data.Data.resize(0x300);
  Data.Size = Data.Data.size();
  Data.Flags = SegmentFlags::Readable;
  auto Put32 = [&](size_t Offset, uint32_t Value) {
    for (size_t I = 0; I < 4; ++I)
      Data.Data[Offset + I] = static_cast<uint8_t>(Value >> (8 * I));
  };
  Put32(0x10C, 0x1140); // ThrowInfo -> CatchableTypeArray
  Put32(0x140, 1);      // one catchable type
  Put32(0x144, 0x1180); // CatchableTypeArray -> CatchableType
  Put32(0x184, 0x11C0); // CatchableType -> TypeDescriptor
  constexpr char TypeName[] = ".?AVProbeZero@@";
  std::memcpy(Data.Data.data() + 0x1D0, TypeName, sizeof(TypeName));
  Img.Segments.push_back(std::move(Data));
  Symbol CtorSymbol = Symbol::makeFunc(Base + 0x2100, 1);
  CtorSymbol.Name = "??0ProbeZero@@QEAA@XZ";
  Img.Symbols.push_back(std::move(CtorSymbol));

  HighFunc Func;
  Func.Name = "throws_zero";
  Func.Entry = Base + 0x2000;
  Func.ReturnType = NdType::makeVoid();
  HighStmt Ctor;
  Ctor.Kind = StmtKind::Call;
  Ctor.CallExpr = HighExpr::makeCall(
      "sub_140002100", Base + 0x2100,
      {HighExpr::makeConst(ThrownObject, 8), HighExpr::makeConst(11, 8),
       HighExpr::makeConst(22, 8), HighExpr::makeConst(33, 8)});
  HighStmt Throw;
  Throw.Kind = StmtKind::Call;
  Throw.CallExpr = HighExpr::makeCall(
      "_CxxThrowException", Base + 0x2200,
      {HighExpr::makeConst(ThrownObject, 8),
       HighExpr::makeConst(ThrowInfo, 8)});
  Func.Body = {Ctor, Throw};

  const std::string Source = emitFunctions({Func}, Arch::X64, &Img);
  EXPECT_NE(Source.find("throw ProbeZero();"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("throw ProbeZero(11"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("ProbeZero_ctor("), std::string::npos) << Source;
}

