TEST(HighCPointerAddresses, CleanupFuncletFrameSlotLoadForwardsIntoDtor) {
  class SlotDbg : public NullDebugContext {
  public:
    std::optional<VariableSym> resolveVariable(va_t FuncAddr,
                                               int64_t Disp) const override {
      if (FuncAddr != 0x140001000 || Disp != -24)
        return std::nullopt;
      VariableSym Var;
      Var.Name = "badgeRecordName";
      Var.Type = NdType::makeNamedRecord("CStringT", 8);
      Var.Type->FieldDisplayNames = {"m_pszData"};
      Var.Type->FieldDisplayOffsets = {0};
      Var.Type->FieldDisplayTypes = {NdType::makePtr()};
      Var.StackOffset = Disp;
      return Var;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  HighFunc Func;
  Func.Name = "cleanup_funclet";
  Func.Entry = 0x140001000;
  Func.FrameSize = 512;
  Func.ReturnType = NdType::makeVoid();
  Func.ExceptionMetadata = ExceptionFunction{};
  Func.Params = {{"result", NdType::makePtr()}, {"this", NdType::makePtr()}};
  const TargetRegInfo &TRI = getTargetRegInfo(Arch::X64);
  MedVar SP;
  SP.Kind = MedVar::Reg;
  SP.Size = 8;
  SP.TheArch = Arch::X64;
  SP.RegOff = TRI.StackPointer;
  auto SlotAddr = HighExpr::makeBinop(
      NdOp::INT_SUB, HighExpr::makeVar(SP, NdType::makeInt(8, false)),
      HighExpr::makeConst(24, 8));
  MedVar CopyDest;
  CopyDest.Kind = MedVar::Temp;
  CopyDest.Id = 2;
  CopyDest.Size = 8;
  CopyDest.TheArch = Arch::X64;
  HighStmt Init;
  Init.Kind = StmtKind::Store;
  Init.StoreAddr = SlotAddr;
  Init.StoreVal = HighExpr::makeConst(0x140004000, 8);
  HighStmt Try;
  Try.Kind = StmtKind::CxxTry;
  Try.EHIsReducible = true;
  HighStmt Work;
  Work.Kind = StmtKind::Call;
  Work.CallExpr = HighExpr::makeCall("work", 0x140002000, {SlotAddr});
  Try.Body = {Init, Work};
  HighEHClause Cleanup;
  Cleanup.Kind = HighEHClauseKind::CxxCleanup;
  Try.EHClauses.push_back(Cleanup);
  HighStmt Copy;
  Copy.Kind = StmtKind::Assign;
  Copy.Dst = HighExpr::makeVar(CopyDest, NdType::makeInt(8));
  Copy.Val = HighExpr::makeLoad(
      HighExpr::makeBinop(NdOp::INT_ADD, parameter(1, NdType::makePtr()),
                          HighExpr::makeConst(488, 8)),
      NdType::makeInt(8));
  HighStmt Dtor;
  Dtor.Kind = StmtKind::Call;
  Dtor.CallExpr = HighExpr::makeCall(
      "CStringT_dtor", 0x140003000,
      {HighExpr::makeVar(CopyDest, NdType::makeInt(8))});
  Try.EHClauseBodies.push_back({Copy, Dtor});
  Func.Body = {Try};

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  ASSERT_TRUE(HighCEmitter().emit({Func}, OS, Options, &Dbg));
  OS.flush();
  EXPECT_NE(Source.find("CStringT_dtor(badgeRecordName.m_pszData)"),
            std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("t2 ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t2;"), std::string::npos) << Source;
}

