TEST(HighCPointerAddresses, IncomingHomeReuseKeepsFrameAddress) {
  class SlotDbg : public NullDebugContext {
  public:
    std::optional<VariableSym> resolveVariable(va_t FuncAddr,
                                               int64_t Disp) const override {
      if (FuncAddr != 0x140001000 || Disp != 8)
        return std::nullopt;
      VariableSym Var;
      Var.Name = "this";
      Var.IsParam = true;
      Var.Type = NdType::makePtr(NdType::makeNamedRecord("CRecord", 8));
      Var.StackOffset = Disp;
      return Var;
    }
    std::optional<VariableSym>
    resolveStackPointerVariable(va_t FuncAddr, int64_t Off) const override {
      if (FuncAddr != 0x140001000 || Off != 0x1D0)
        return std::nullopt;
      VariableSym Var;
      Var.Name = "name";
      Var.Type = NdType::makeNamedRecord("CStringT", 8);
      Var.StackOffset = Off;
      return Var;
    }
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr == 0x140002000) {
        FunctionSym FS;
        FS.Name = "Catalog_Lookup";
        FS.Addr = Addr;
        FS.CallConv = DebugCallConv::Thiscall;
        FS.ReturnType = NdType::makeNamedRecord("CStringT", 8);
        FS.Params.emplace_back(
            "this", NdType::makePtr(NdType::makeNamedRecord("CStringTable", 8)));
        FS.Params.emplace_back(
            "result", NdType::makePtr(NdType::makeNamedRecord("CStringT", 8)));
        FS.Params.emplace_back("nType", NdType::makeInt(4));
        FS.Params.emplace_back("nKey", NdType::makeInt(4));
        return FS;
      }
      if (Addr != 0x140001000)
        return std::nullopt;
      FunctionSym FS;
      FS.Name = "CRecord_GetRecordName";
      FS.Addr = Addr;
      FS.CallConv = DebugCallConv::Thiscall;
      FS.ReturnType = NdType::makeNamedRecord("CStringT", 8);
      FS.Params.emplace_back(
          "this", NdType::makePtr(NdType::makeNamedRecord("CRecord", 8)));
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  HighFunc Func;
  Func.Name = "CRecord_GetRecordName";
  Func.Entry = 0x140001000;
  Func.FrameSize = 0x1C8;
  auto Record = NdType::makeNamedRecord("CRecord", 8);
  auto ResultTy = NdType::makeNamedRecord("CStringT", 8);
  Func.ReturnType = ResultTy;
  Func.Params = {{"this", NdType::makePtr(Record)},
                 {"result", NdType::makePtr(ResultTy)}};
  const TargetRegInfo &TRI = getTargetRegInfo(Arch::X64);
  MedVar SP;
  SP.Kind = MedVar::Reg;
  SP.Size = 8;
  SP.TheArch = Arch::X64;
  SP.RegOff = TRI.StackPointer;
  auto Home = HighExpr::makeBinop(
      NdOp::INT_ADD, HighExpr::makeVar(SP, NdType::makeInt(8, false)),
      HighExpr::makeConst(8, 8));
  HighStmt Find;
  Find.Kind = StmtKind::Call;
  Find.CallExpr = HighExpr::makeCall(
      "Catalog_Lookup", 0x140002000,
      {HighExpr::makeConst(0x140070000, 8), Home, HighExpr::makeConst(1, 4),
       HighExpr::makeConst(0, 4)});
  Func.Body = {Find};
  returnValue(Func, parameter(1, Func.Params[1].Type));

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  ASSERT_TRUE(HighCEmitter().emit({Func}, OS, Options, &Dbg));
  OS.flush();
  const auto Args = lastCallArguments(Source, "Catalog_Lookup");
  ASSERT_TRUE(Args) << Source;
  ASSERT_EQ(Args->size(), 4u) << Source;
  EXPECT_NE((*Args)[1].find("frame_base + 8"), std::string::npos) << Source;
  EXPECT_NE((*Args)[1].find("CStringT*"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("unknown register"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("var_8"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("&this"), std::string::npos) << Source;
}

