TEST(HighCPointerAddresses, WrapperRecordSameWidthPointerStoreKeepsByteWidth) {
  class SlotDbg : public NullDebugContext {
  public:
    TypeRef Str;
    std::optional<VariableSym> resolveVariable(va_t FuncAddr,
                                               int64_t Disp) const override {
      if (FuncAddr != 0x140001000 || Disp != -8)
        return std::nullopt;
      VariableSym Var;
      Var.Name = "badgeRecordName";
      Var.Type = Str;
      Var.StackOffset = Disp;
      return Var;
    }
    bool hasInfo() const override { return true; }
  } Dbg;
  Dbg.Str = NdType::makeNamedRecord("CStringT", 8);
  Dbg.Str->FieldDisplayNames = {"m_pszData"};
  Dbg.Str->FieldDisplayOffsets = {0};
  Dbg.Str->FieldDisplayTypes = {NdType::makePtr()};

  HighFunc Func;
  Func.Name = "ctor_overlay";
  Func.Entry = 0x140001000;
  Func.FrameSize = 32;
  Func.ReturnType = NdType::makeVoid();
  const TargetRegInfo &TRI = getTargetRegInfo(Arch::X64);
  MedVar SP;
  SP.Kind = MedVar::Reg;
  SP.Size = 8;
  SP.TheArch = Arch::X64;
  SP.RegOff = TRI.StackPointer;
  auto Sp = HighExpr::makeVar(SP, NdType::makeInt(8, false));
  auto Home = HighExpr::makeBinop(NdOp::INT_SUB, Sp, HighExpr::makeConst(16, 8));
  auto Badge = HighExpr::makeBinop(NdOp::INT_SUB, Sp, HighExpr::makeConst(8, 8));
  HighStmt Ctor;
  Ctor.Kind = StmtKind::Call;
  Ctor.CallExpr = HighExpr::makeCall(
      "CStringT_ctor", 0x140003000,
      {Home, HighExpr::makeConst(0x140004000, 8)});
  HighStmt Overlay;
  Overlay.Kind = StmtKind::Assign;
  Overlay.Dst = HighExpr::makeLoad(Badge, NdType::makeInt(8));
  auto Addr = std::make_shared<HighExpr>();
  Addr->Kind = ExprKind::Addr;
  Addr->Type = NdType::makePtr();
  Addr->Operands.push_back(HighExpr::makeLoad(Home, NdType::makeInt(8)));
  Overlay.Val = std::move(Addr);
  HighStmt Dtor;
  Dtor.Kind = StmtKind::Call;
  Dtor.CallExpr = HighExpr::makeCall("CStringT_dtor", 0x140003100, {Badge});
  Func.Body = {Ctor, Overlay, Dtor};

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  ASSERT_TRUE(HighCEmitter().emit({Func}, OS, Options, &Dbg));
  OS.flush();
  const auto Stores = portableStoreCalls(Source);
  ASSERT_EQ(Stores.size(), 1u) << Source;
  EXPECT_EQ(Stores[0].Type, "int64_t") << Source;
  EXPECT_NE(Stores[0].Address.find("frame_base"), std::string::npos) << Source;
  EXPECT_NE(Stores[0].Value.find("frame_base"), std::string::npos) << Source;
  const auto Args = lastCallArguments(Source, "CStringT_dtor");
  ASSERT_TRUE(Args) << Source;
  ASSERT_EQ(Args->size(), 1u) << Source;
  EXPECT_NE((*Args)[0].find("frame_base - 8"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("unknown register"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("badgeRecordName = &"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, CollidingGetStemKeepsCalleeReturnOnSecondDest) {
  class CalleeDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140002000 && Addr != 0x140002100)
        return std::nullopt;
      FunctionSym FS;
      FS.Name = Addr == 0x140002000 ? "UnlimitedAdjustmentInfo_GetAdjustmentLevel"
                                    : "CRecordAdjustmentInfo_GetAdjustmentLevel";
      FS.Addr = Addr;
      FS.ReturnType = NdType::makeInt(4, true);
      FS.Params.emplace_back("this", NdType::makePtr());
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  HighFunc Func;
  Func.Name = "two_levels";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  MedVar First;
  First.Kind = MedVar::Temp;
  First.Id = 1;
  First.RenameTag = 1;
  First.Size = 8;
  First.TheArch = Arch::X64;
  MedVar Second;
  Second.Kind = MedVar::Temp;
  Second.Id = 115;
  Second.RenameTag = 115;
  Second.Size = 8;
  Second.TheArch = Arch::X64;
  HighStmt GetA;
  GetA.Kind = StmtKind::Assign;
  GetA.Dst = HighExpr::makeVar(First, NdType::makeInt(8));
  GetA.Val = HighExpr::makeCall("UnlimitedAdjustmentInfo_GetAdjustmentLevel",
                                0x140002000, {parameter(0)});
  HighStmt UseA;
  UseA.Kind = StmtKind::If;
  UseA.Cond = HighExpr::makeVar(First, NdType::makeInt(8));
  HighStmt GetB;
  GetB.Kind = StmtKind::Assign;
  GetB.Dst = HighExpr::makeVar(Second, NdType::makeInt(8));
  GetB.Val = HighExpr::makeCall("CRecordAdjustmentInfo_GetAdjustmentLevel",
                                0x140002100, {parameter(0)});
  HighStmt UseB;
  UseB.Kind = StmtKind::If;
  UseB.Cond = HighExpr::makeVar(Second, NdType::makeInt(8));
  UseB.Body = {HighStmt{}};
  UseB.Body[0].Kind = StmtKind::Call;
  UseB.Body[0].CallExpr =
      HighExpr::makeCall("take", 0x140002200,
                         {HighExpr::makeVar(Second, NdType::makeInt(8))});
  Func.Body = {GetA, UseA, GetB, UseB};
  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  ASSERT_TRUE(HighCEmitter().emit({Func}, OS, Options, &Dbg));
  OS.flush();
  EXPECT_TRUE(Source.find("int32_t v115") != std::string::npos ||
              Source.find("int32_t AdjustmentLevel") != std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("int64_t v115"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("int64_t AdjustmentLevel"), std::string::npos) << Source;
}

