TEST(HighCPointerAddresses, MsvcAtlCalleeTableOwnsExactAndSuffixNames) {
  EXPECT_NE(msvcAtlCallee("IsEmpty"), nullptr);
  EXPECT_NE(msvcAtlCallee("GetLength"), nullptr);
  EXPECT_NE(msvcAtlCallee("GetManager"), nullptr);
  EXPECT_NE(msvcAtlCallee("CStringT_dtor"), nullptr);
  EXPECT_NE(msvcAtlCallee("CStringT_ctor"), nullptr);
  EXPECT_NE(msvcAtlSyntheticPrototype("CStringT_ctor", *msvcAtlCallee("CStringT_ctor"),
                                     true)
                .find("CStringT* this, ..."),
            std::string::npos);
  EXPECT_NE(msvcAtlCallee("CStringT_assign"), nullptr);
  EXPECT_NE(msvcAtlCallee("CSimpleStringT_cstr"), nullptr);
  EXPECT_NE(msvcAtlCallee("Format"), nullptr);
  EXPECT_NE(msvcAtlCallee("Concatenate"), nullptr);
  EXPECT_NE(msvcAtlCallee("Foo::~Foo"), nullptr);
  EXPECT_EQ(msvcAtlCallee("LookupTextW"), nullptr);
  EXPECT_STREQ(msvcAtlSpecialMemberStem('0'), "ctor");
  EXPECT_STREQ(msvcAtlSpecialMemberStem('1'), "dtor");
  EXPECT_STREQ(msvcAtlSpecialMemberStem('4'), "assign");
  EXPECT_STREQ(msvcAtlSpecialMemberStem('B'), "cstr");
  EXPECT_EQ(msvcAtlSpecialMemberStem('2'), nullptr);
}

TEST(HighCPointerAddresses, AtlUnaryThisPrototypesAreTyped) {
  HighFunc Func;
  Func.Name = "parent";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  auto Call = [](const char *Name, va_t Addr, std::vector<ExprPtr> Args) {
    HighStmt S;
    S.Kind = StmtKind::ExprStmt;
    S.Val = HighExpr::makeCall(Name, Addr, std::move(Args));
    return S;
  };
  Func.Body.push_back(Call("IsEmpty", 0x140032a38,
                           {HighExpr::makeConst(0x140004000, 8)}));
  Func.Body.push_back(Call("GetLength", 0x140032a40,
                           {HighExpr::makeConst(0x140004000, 8)}));
  Func.Body.push_back(Call("GetManager", 0x140032a48,
                           {HighExpr::makeConst(0x140004000, 8)}));
  Func.Body.push_back(Call("CSimpleStringT_cstr", 0x1400329d8,
                           {HighExpr::makeConst(0x140004000, 8)}));
  Func.Body.push_back(Call(
      "CStringT_assign", 0x1400329f8,
      {HighExpr::makeConst(0x140004000, 8), HighExpr::makeConst(0x140004008, 8)}));
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("extern __fastcall bool IsEmpty(CStringT* this);"),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("extern __fastcall int32_t GetLength(CStringT* this);"),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("extern __fastcall void* GetManager(CStringT* this);"),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("extern __fastcall wchar_t* CSimpleStringT_cstr("
                        "CSimpleStringT* this);"),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("extern __fastcall void CStringT_assign(CStringT* this, "
                        "CStringT* src);"),
            std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("extern int IsEmpty"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("extern int CSimpleStringT_cstr"), std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("extern int CStringT_assign"), std::string::npos)
      << Source;
}

TEST(HighCPointerAddresses, AtlFormatAndConcatenatePrototypesAreTyped) {
  HighFunc Func;
  Func.Name = "parent";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  HighStmt Format;
  Format.Kind = StmtKind::ExprStmt;
  Format.Val = HighExpr::makeCall(
      "Format", 0x140032a50,
      {HighExpr::makeConst(0x140004000, 8), HighExpr::makeConst(0x140005000, 8),
       HighExpr::makeConst(0x140006000, 8)});
  HighStmt Concat;
  Concat.Kind = StmtKind::ExprStmt;
  Concat.Val = HighExpr::makeCall(
      "Concatenate", 0x140032b18,
      {HighExpr::makeConst(0x140004000, 8), HighExpr::makeConst(0x140005000, 8),
       HighExpr::makeConst(1, 4), HighExpr::makeConst(0x140006000, 8),
       HighExpr::makeConst(2, 4)});
  Func.Body = {Format, Concat};
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("extern __fastcall void Format(CStringT* this, "
                        "wchar_t* fmt, ...);"),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("extern __fastcall void Concatenate(CStringT* dest, "
                        "wchar_t* a, int32_t na, wchar_t* b, int32_t nb);"),
            std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("extern int Format"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("extern int Concatenate"), std::string::npos) << Source;
  EXPECT_NE(Source.find("Format("), std::string::npos) << Source;
  const auto FormatAt = Source.rfind("Format(");
  const auto FormatArgs =
      Source.substr(Source.find('(', FormatAt) + 1,
                    Source.find(')', FormatAt) - Source.find('(', FormatAt) - 1);
  EXPECT_EQ(std::count(FormatArgs.begin(), FormatArgs.end(), ','), 2) << Source;
}

