TEST(HighCPointerAddresses, AtlFormatComposesIntegerViewBeforeIf) {
  HighFunc Func;
  Func.Name = "fmt_adjustment";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  MedVar Level;
  Level.Kind = MedVar::Temp;
  Level.Id = 115;
  Level.Size = 4;
  Level.TheArch = Arch::X64;
  MedVar Narrow;
  Narrow.Kind = MedVar::Temp;
  Narrow.Id = 117;
  Narrow.Size = 2;
  Narrow.TheArch = Arch::X64;
  MedVar Wide;
  Wide.Kind = MedVar::Temp;
  Wide.Id = 99;
  Wide.Size = 4;
  Wide.TheArch = Arch::X64;
  Wide.SSAVer = 25;
  HighStmt Get;
  Get.Kind = StmtKind::Assign;
  Get.Dst = HighExpr::makeVar(Level, NdType::makeInt(4, true));
  Get.Val = HighExpr::makeCall("GetAdjustmentLevel", 0x140002200, {parameter(0)});
  Get.Val->Type = NdType::makeInt(4, true);
  auto ToI16 = std::make_shared<HighExpr>();
  ToI16->Kind = ExprKind::Cast;
  ToI16->CastTo = NdType::makeInt(2, true);
  ToI16->Type = NdType::makeInt(2, true);
  ToI16->Operands.push_back(HighExpr::makeVar(Level, NdType::makeInt(4, true)));
  HighStmt NarrowAssign;
  NarrowAssign.Kind = StmtKind::Assign;
  NarrowAssign.Dst = HighExpr::makeVar(Narrow, NdType::makeInt(2, true));
  NarrowAssign.Val = std::move(ToI16);
  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = HighExpr::makeVar(Level, NdType::makeInt(4, true));
  auto ToI32 = HighExpr::makeUnary(
      NdOp::INT_ZEXT, HighExpr::makeVar(Narrow, NdType::makeInt(2, true)));
  ToI32->Type = NdType::makeInt(4, false);
  HighStmt WideAssign;
  WideAssign.Kind = StmtKind::Assign;
  WideAssign.Dst = HighExpr::makeVar(Wide, NdType::makeInt(4, true));
  WideAssign.Val = std::move(ToI32);
  auto Arg = HighExpr::makeUnary(NdOp::INT_ZEXT,
                                 HighExpr::makeVar(Wide, NdType::makeInt(4, true)));
  Arg->Type = NdType::makeInt(8, false);
  HighStmt Format;
  Format.Kind = StmtKind::ExprStmt;
  Format.Val = HighExpr::makeCall(
      "Format", 0x140032a50,
      {HighExpr::makeConst(0x140004000, 8), HighExpr::makeConst(0x140005000, 8),
       std::move(Arg)});
  HighStmt Ctor;
  Ctor.Kind = StmtKind::ExprStmt;
  Ctor.Val = HighExpr::makeCall("CStringT_ctor", 0x1400329e0,
                                {HighExpr::makeConst(0x140004000, 8)});
  Guard.Body = {Ctor, WideAssign, Format};
  Func.Body = {Get, NarrowAssign, Guard};
  const std::string Source = emitFunctions({Func});
  const auto FormatAt = Source.rfind("Format(");
  ASSERT_NE(FormatAt, std::string::npos) << Source;
  const auto FormatArgs =
      Source.substr(Source.find('(', FormatAt),
                    Source.find(')', FormatAt) - Source.find('(', FormatAt) + 1);
  EXPECT_NE(FormatArgs.find("AdjustmentLevel"), std::string::npos) << Source;
  EXPECT_EQ(FormatArgs.find("(int64_t)"), std::string::npos) << Source;
  EXPECT_EQ(FormatArgs.find("(uint32_t)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t99_25"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t117"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, AtlFormatNarrowViewInsideIfElseComposes) {
  class CalleeDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140002000 && Addr != 0x140002100)
        return std::nullopt;
      FunctionSym FS;
      FS.Name = Addr == 0x140002000 ? "UnlimitedAdjustmentInfo_GetAdjustmentLevel"
                                    : "CRecordAdjustmentInfo_GetAdjustmentLevel";
      FS.Addr = Addr;
      FS.ReturnType = NdType::makeInt(4, true);
      FS.Params.emplace_back("this", NdType::makePtr());
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  HighFunc Func;
  Func.Name = "fmt_else_narrow";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  MedVar First;
  First.Kind = MedVar::Temp;
  First.Id = 1;
  First.RenameTag = 1;
  First.Size = 4;
  First.TheArch = Arch::X64;
  MedVar Level;
  Level.Kind = MedVar::Temp;
  Level.Id = 115;
  Level.RenameTag = 115;
  Level.Size = 4;
  Level.TheArch = Arch::X64;
  MedVar Narrow;
  Narrow.Kind = MedVar::Temp;
  Narrow.Id = 117;
  Narrow.RenameTag = 117;
  Narrow.Size = 2;
  Narrow.TheArch = Arch::X64;
  HighStmt GetA;
  GetA.Kind = StmtKind::Assign;
  GetA.Dst = HighExpr::makeVar(First, NdType::makeInt(4, true));
  GetA.Val = HighExpr::makeCall("UnlimitedAdjustmentInfo_GetAdjustmentLevel",
                                0x140002000, {parameter(0)});
  GetA.Val->Type = NdType::makeInt(4, true);
  HighStmt ThenStore;
  ThenStore.Kind = StmtKind::Store;
  ThenStore.StoreAddr = HighExpr::makeConst(0x140006000, 8);
  ThenStore.StoreVal = HighExpr::makeVar(First, NdType::makeInt(4, true));
  HighStmt ThenWork;
  ThenWork.Kind = StmtKind::Call;
  ThenWork.CallExpr = HighExpr::makeCall("CStringT_ctor", 0x1400329e0,
                                         {HighExpr::makeConst(0x140004000, 8)});
  HighStmt Then;
  Then.Kind = StmtKind::If;
  Then.Cond = HighExpr::makeVar(First, NdType::makeInt(4, true));
  Then.Body = {ThenStore, ThenWork};
  HighStmt GetB;
  GetB.Kind = StmtKind::Assign;
  GetB.Dst = HighExpr::makeVar(Level, NdType::makeInt(8, true));
  GetB.Val = HighExpr::makeCall(
      "CRecordAdjustmentInfo_GetAdjustmentLevel", 0x140002100,
      {parameter(0), HighExpr::makeUndef(8), HighExpr::makeUndef(8),
       HighExpr::makeUndef(8)});
  GetB.Val->Type = NdType::makeInt(4, true);
  MedVar Mid;
  Mid.Kind = MedVar::Temp;
  Mid.Id = 116;
  Mid.RenameTag = 116;
  Mid.Size = 4;
  Mid.TheArch = Arch::X64;
  MedVar CondView;
  CondView.Kind = MedVar::Temp;
  CondView.Id = 118;
  CondView.RenameTag = 118;
  CondView.Size = 4;
  CondView.TheArch = Arch::X64;
  MedVar Wide;
  Wide.Kind = MedVar::Temp;
  Wide.Id = 99;
  Wide.Size = 4;
  Wide.TheArch = Arch::X64;
  Wide.SSAVer = 25;
  auto Sub0 = [&](MedVar Dst, uint16_t DstSize, ExprPtr Src) {
    HighStmt S;
    S.Kind = StmtKind::Assign;
    S.Dst = HighExpr::makeVar(Dst, NdType::makeInt(DstSize, true));
    S.Val = HighExpr::makeBinop(NdOp::SUBBYTES, std::move(Src),
                                HighExpr::makeConst(0, 4));
    S.Val->Type = NdType::makeInt(DstSize, true);
    return S;
  };
  HighStmt MidAssign =
      Sub0(Mid, 4, HighExpr::makeVar(Level, NdType::makeInt(8, true)));
  HighStmt NarrowAssign =
      Sub0(Narrow, 2, HighExpr::makeVar(Mid, NdType::makeInt(4, true)));
  HighStmt CondAssign =
      Sub0(CondView, 4, HighExpr::makeVar(Level, NdType::makeInt(8, true)));
  auto ToI32 = std::make_shared<HighExpr>();
  ToI32->Kind = ExprKind::Cast;
  ToI32->CastTo = NdType::makeInt(4, true);
  ToI32->Type = NdType::makeInt(4, true);
  ToI32->Operands.push_back(
      HighExpr::makeVar(Narrow, NdType::makeInt(2, true)));
  HighStmt WideAssign;
  WideAssign.Kind = StmtKind::Assign;
  WideAssign.Dst = HighExpr::makeVar(Wide, NdType::makeInt(4, true));
  WideAssign.Val = std::move(ToI32);
  auto Arg = HighExpr::makeUnary(NdOp::INT_ZEXT,
                                 HighExpr::makeVar(Wide, NdType::makeInt(4, true)));
  Arg->Type = NdType::makeInt(8, false);
  HighStmt Format;
  Format.Kind = StmtKind::Call;
  Format.CallExpr = HighExpr::makeCall(
      "Format", 0x140032a50,
      {HighExpr::makeConst(0x140004100, 8), HighExpr::makeConst(0x140005000, 8),
       std::move(Arg),
       HighExpr::makeCall("CSimpleStringT_cstr", 0x1400329d8,
                          {HighExpr::makeConst(0x140004200, 8)})});
  HighStmt Ctor;
  Ctor.Kind = StmtKind::Call;
  Ctor.CallExpr = HighExpr::makeCall("CStringT_ctor", 0x1400329e0,
                                     {HighExpr::makeConst(0x140004100, 8)});
  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = HighExpr::makeBinop(NdOp::INT_NOTEQUAL,
                                   HighExpr::makeVar(CondView, NdType::makeInt(4, true)),
                                   HighExpr::makeConst(0, 4));
  Guard.Body = {Ctor, WideAssign, Format};
  HighStmt ElseCtor;
  ElseCtor.Kind = StmtKind::Call;
  ElseCtor.CallExpr = HighExpr::makeCall(
      "CStringT_ctor", 0x1400329e0, {HighExpr::makeConst(0x140004300, 8)});
  HighStmt Outer;
  Outer.Kind = StmtKind::IfElse;
  Outer.Cond = HighExpr::makeVar(First, NdType::makeInt(4, true));
  Outer.Body = {Then};
  Outer.ElseBody = {GetB, MidAssign, NarrowAssign, CondAssign, Guard};
  HighStmt Try;
  Try.Kind = StmtKind::CxxTry;
  Try.EHIsReducible = true;
  Try.Body = {GetA, Outer};
  HighEHClause Cleanup;
  Cleanup.Kind = HighEHClauseKind::CxxCleanup;
  Try.EHClauses.push_back(Cleanup);
  Try.EHClauseBodies.push_back({ElseCtor});
  Func.Body = {Try};

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  Options.Format = BinaryFormat::COFF;
  ASSERT_TRUE(HighCEmitter().emit({Func}, OS, Options, &Dbg));
  OS.flush();
  const auto FormatAt = Source.rfind("Format(");
  ASSERT_NE(FormatAt, std::string::npos) << Source;
  const auto FormatArgs =
      Source.substr(Source.find('(', FormatAt),
                    Source.find(')', FormatAt) - Source.find('(', FormatAt) + 1);
  EXPECT_TRUE(FormatArgs.find("v115") != std::string::npos ||
              FormatArgs.find("AdjustmentLevel") != std::string::npos)
      << Source;
  EXPECT_EQ(FormatArgs.find("v117"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("int16_t v117"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("v117 ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("v116"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("v118"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t99"), std::string::npos) << Source;
}

