TEST(HighCPointerAddresses, TypedCallResultOmitsSameTypeCast) {
  HighFunc Func;
  Func.Name = "typed_call";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  auto WideLen = [](ExprPtr Call) {
    auto Sext = HighExpr::makeUnary(NdOp::INT_SEXT, std::move(Call));
    Sext->Type = NdType::makeInt(4, true);
    auto Zext = HighExpr::makeUnary(NdOp::INT_ZEXT, std::move(Sext));
    Zext->Type = NdType::makeInt(8, false);
    return Zext;
  };
  HighStmt Store;
  Store.Kind = StmtKind::Assign;
  MedVar Dest;
  Dest.Kind = MedVar::Temp;
  Dest.Id = 10;
  Dest.Size = 8;
  Dest.TheArch = Arch::X64;
  Store.Dst = HighExpr::makeVar(Dest);
  Store.Val = WideLen(HighExpr::makeCall("GetLength", 0x140032a40,
                                        {HighExpr::makeConst(0x140007000, 8)}));
  auto Empty = HighExpr::makeCall("IsEmpty", 0x140032a50,
                                  {HighExpr::makeConst(0x140008000, 8)});
  auto Cast = HighExpr::makeUnary(NdOp::INT_ZEXT, std::move(Empty));
  Cast->Type = NdType::makeInt(4, true);
  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = HighExpr::makeBinop(NdOp::INT_NOTEQUAL, std::move(Cast),
                                   HighExpr::makeConst(0, 4));
  HighStmt Ret;
  Ret.Kind = StmtKind::Return;
  Guard.Body = {Ret};
  Func.Body = {Store, Guard};
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("GetLength("), std::string::npos) << Source;
  EXPECT_NE(Source.find("IsEmpty("), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(int64_t)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(uint32_t)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(int32_t)GetLength"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(int32_t)IsEmpty"), std::string::npos) << Source;
}

