TEST(HighCPointerAddresses, CollidingDebugStemsKeepRicherPrototype) {
  class OverloadDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr == 0x140011520) {
        FunctionSym FS;
        FS.Name = "LookupTextW";
        FS.Addr = Addr;
        FS.ReturnType = NdType::makeNamedRecord("CStringT", 8);
        FS.Params.emplace_back("msgID", NdType::makeInt(4, true));
        return FS;
      }
      if (Addr == 0x140013f30) {
        FunctionSym FS;
        FS.Name = "??$LookupTextW@V?$CStringT@H@@@";
        FS.Addr = Addr;
        FS.ReturnType = NdType::makeNamedRecord("CStringT", 8);
        FS.Params.emplace_back("msgID", NdType::makeInt(4, true));
        FS.Params.emplace_back(
            "name", NdType::makePtr(NdType::makeNamedRecord("CStringT", 8)));
        return FS;
      }
      return std::nullopt;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  HighFunc Func;
  Func.Name = "parent";
  Func.ReturnType = NdType::makeVoid();
  HighStmt TwoArg;
  TwoArg.Kind = StmtKind::ExprStmt;
  TwoArg.Val = HighExpr::makeCall(
      "LookupTextW", 0x140011520,
      {HighExpr::makeConst(0x140001040, 8), HighExpr::makeConst(1, 4)});
  Func.Body.push_back(std::move(TwoArg));
  HighStmt ThreeArg;
  ThreeArg.Kind = StmtKind::ExprStmt;
  ThreeArg.Val = HighExpr::makeCall(
      "??$LookupTextW@V?$CStringT@H@@@", 0x140013f30,
      {HighExpr::makeConst(0x140001040, 8), HighExpr::makeConst(0xCF1, 4),
       HighExpr::makeConst(0x140001080, 8)});
  Func.Body.push_back(std::move(ThreeArg));
  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.TheArch = Arch::X64;
  ASSERT_TRUE(HighCEmitter().emit({Func}, OS, Options, &Dbg));
  OS.flush();
  EXPECT_NE(Source.find("extern __fastcall CStringT* LookupTextW("
                        "CStringT* result, int32_t msgID, CStringT* name);"),
            std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("extern int LookupTextW"), std::string::npos)
      << Source;
  const auto First = Source.find("LookupTextW(");
  ASSERT_NE(First, std::string::npos) << Source;
  const auto Second = Source.find("LookupTextW(", First + 1);
  ASSERT_NE(Second, std::string::npos) << Source;
  const auto Third = Source.find("LookupTextW(", Second + 1);
  ASSERT_NE(Third, std::string::npos) << Source;
  auto ArgCount = [&](size_t CallAt) {
    const auto Open = Source.find('(', CallAt);
    const auto Close = Source.find(')', Open);
    const std::string Args = Source.substr(Open + 1, Close - Open - 1);
    return std::count(Args.begin(), Args.end(), ',');
  };
  // Prototype + two call sites. The 2-operand site stays 2 args; the
  // 3-operand site keeps the fmt/name pointer. Do not invent a 1-arg FS.
  EXPECT_EQ(ArgCount(Second), 1) << Source;
  EXPECT_EQ(ArgCount(Third), 2) << Source;
}

