TEST(HighCPointerAddresses, DtorStemDropsLeftoverClobberArgsAndUnknownAssigns) {
  HighFunc Func;
  Func.Name = "parent";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();

  auto MakeTemp = [](int Id) {
    MedVar V;
    V.Kind = MedVar::Temp;
    V.Id = Id;
    V.Size = 8;
    V.TheArch = Arch::X64;
    return V;
  };
  const MedVar V9 = MakeTemp(9);
  const MedVar V10 = MakeTemp(10);
  const MedVar V11 = MakeTemp(11);
  auto AssignUndef = [](const MedVar &Dest) {
    HighStmt S;
    S.Kind = StmtKind::Assign;
    S.Dst = HighExpr::makeVar(Dest);
    S.Val = HighExpr::makeUndef(8);
    S.IsPhiCopy = true;
    return S;
  };
  Func.Body.push_back(AssignUndef(V9));
  Func.Body.push_back(AssignUndef(V10));
  Func.Body.push_back(AssignUndef(V11));

  HighStmt Call;
  Call.Kind = StmtKind::ExprStmt;
  Call.Val = HighExpr::makeCall(
      "CStringT_dtor", 0x140003000,
      {HighExpr::makeConst(0x140004000, 8), HighExpr::makeVar(V9),
       HighExpr::makeVar(V11), HighExpr::makeVar(V10)});
  Func.Body.push_back(std::move(Call));
  HighStmt Ret;
  Ret.Kind = StmtKind::Return;
  Func.Body.push_back(std::move(Ret));

  const std::string Source = emitFunctions({Func});
  const auto CallAt = Source.rfind("CStringT_dtor(");
  ASSERT_NE(CallAt, std::string::npos) << Source;
  const auto Open = Source.find('(', CallAt);
  const auto Close = Source.find(')', Open);
  ASSERT_NE(Open, std::string::npos) << Source;
  ASSERT_NE(Close, std::string::npos) << Source;
  const std::string Args = Source.substr(Open + 1, Close - Open - 1);
  EXPECT_EQ(std::count(Args.begin(), Args.end(), ','), 0) << Source;
  EXPECT_EQ(Source.find("0 /* unknown */"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("v9"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("v10"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("v11"), std::string::npos) << Source;
}

