  MedVar SP;
  SP.Kind = MedVar::Reg;
  SP.Size = 8;
  SP.TheArch = Arch::X64;
  SP.RegOff = getTargetRegInfo(Arch::X64).StackPointer;
  auto Sp = HighExpr::makeVar(SP, NdType::makeInt(8, false));
  auto Home = HighExpr::makeBinop(NdOp::INT_SUB, Sp, HighExpr::makeConst(8, 8));
  HighStmt Store;
  Store.Kind = StmtKind::Store;
  Store.StoreAddr = Home;
  Store.StoreVal = parameter(1, NdType::makeInt(8));
  Func.Body.push_back(std::move(Store));
  auto Folded = HighExpr::makeBinop(
      NdOp::INT_ADD,
      HighExpr::makeBinop(NdOp::INT_SUB, Home, HighExpr::makeConst(32, 8)),
      HighExpr::makeConst(56, 8));
  HighStmt Call;
  Call.Kind = StmtKind::Assign;
  MedVar Dest;
  Dest.Kind = MedVar::Temp;
  Dest.Id = 24;
  Dest.Size = 8;
  Dest.TheArch = Arch::X64;
