  HighStmt Work;
  Work.Kind = StmtKind::Call;
  Work.CallExpr =
      HighExpr::makeCall("use", 0x140002000, {parameter(0, NdType::makeInt(8))});
  MedVar V1;
  V1.Kind = MedVar::Temp;
  V1.Id = 1;
  V1.Size = 8;
  V1.TheArch = Arch::X64;
  HighStmt OtherHome;
  OtherHome.Kind = StmtKind::Assign;
  OtherHome.Dst = HighExpr::makeVar(V1, NdType::makeInt(8, false));
  OtherHome.Val = HighExpr::makeBinop(
      NdOp::INT_SUB, HighExpr::makeVar(SP, NdType::makeInt(8, false)),
      HighExpr::makeConst(24, 8));
  HighStmt Reuse;
  Reuse.Kind = StmtKind::Assign;
  Reuse.Dst = HighExpr::makeVar(V0, NdType::makeInt(8, false));
  Reuse.Val = HighExpr::makeVar(V1, NdType::makeInt(8, false));
  HighStmt Junk;
  Junk.Kind = StmtKind::Assign;
  Junk.Dst = HighExpr::makeVar(V0, NdType::makeInt(8, false));
  Junk.Val = HighExpr::makeBinop(
      NdOp::INT_AND, HighExpr::makeVar(V0, NdType::makeInt(8, false)),
      HighExpr::makeConst(32, 8));
  HighStmt Dtor;
  Dtor.Kind = StmtKind::Call;
  Dtor.CallExpr =
      HighExpr::makeCall("dtor", 0x140003000, {HighExpr::makeVar(V0)});
  HighStmt Try;
  Try.Kind = StmtKind::CxxTry;
  Try.EHIsReducible = true;
