TEST(HighCPointerAddresses, Win64CallReloadsParamsFromCalleeSaves) {
  BinaryImage Img;
  Img.Arch = Arch::X64;
  Img.Bits = Bitness::Bits64;
  Img.Format = BinaryFormat::COFF;

  auto Reg = [](int Id, int SSA, uint64_t Off) {
    MedVar V;
    V.Kind = MedVar::Reg;
    V.TheArch = Arch::X64;
    V.Id = Id;
    V.SSAVer = SSA;
    V.Size = 8;
    V.RegOff = Off;
    return V;
  };
  auto Copy = [](MedVar Dst, MedVar Src, va_t Addr) {
    MedOp Op;
    Op.Opcode = NdOp::COPY;
    Op.Output = Dst;
    Op.addInput(Src);
    Op.Addr = Addr;
    return Op;
  };

  const MedVar RCX0 = Reg(10, 0, x86reg::RCX);
  const MedVar RDX0 = Reg(11, 0, x86reg::RDX);
  const MedVar R80 = Reg(12, 0, x86reg::R8);
  const MedVar R90 = Reg(13, 0, x86reg::R9);
  const MedVar RBP1 = Reg(20, 1, x86reg::RBP);
  const MedVar RSI1 = Reg(21, 1, x86reg::RSI);
  const MedVar R141 = Reg(22, 1, x86reg::R14);
  const MedVar RDI1 = Reg(23, 1, x86reg::RDI);
  const MedVar R81 = Reg(12, 1, x86reg::R8);
  const MedVar RCX2 = Reg(10, 2, x86reg::RCX);
  const MedVar RDX2 = Reg(11, 2, x86reg::RDX);
  const MedVar R82 = Reg(12, 2, x86reg::R8);
  const MedVar R92 = Reg(13, 2, x86reg::R9);

  MedFunc Med;
  Med.Entry = 0x140001000;
  Med.Name = "gs_handler";
  Med.CC = CallingConv::Win64;
  const uint64_t ParamOffs[] = {x86reg::RCX, x86reg::RDX, x86reg::R8,
                                x86reg::R9};
  for (int I = 0; I < 4; ++I) {
    MedVar P;
    P.Kind = MedVar::Param;
    P.TheArch = Arch::X64;
    P.Id = 6 + I;
    P.Size = 8;
    P.RegOff = ParamOffs[I];
    Med.Params.push_back(P);
  }

  MedBlock Block;
  Block.Id = 0;
  Block.StartAddr = 0x140001000;
  Block.EndAddr = 0x140001080;
  Block.Ops.push_back(Copy(RBP1, RCX0, 0x140001000));
  Block.Ops.push_back(Copy(RSI1, RDX0, 0x140001004));
  Block.Ops.push_back(Copy(R141, R80, 0x140001008));
  Block.Ops.push_back(Copy(RDI1, R90, 0x14000100c));

  MedOp Flags;
  Flags.Opcode = NdOp::COPY;
  Flags.Output = R81;
  Flags.addInput(MedVar::makeConst(0x66, 4));
  Flags.Addr = 0x140001010;
  Block.Ops.push_back(std::move(Flags));

  Block.Ops.push_back(Copy(R92, RDI1, 0x140001020));
  Block.Ops.push_back(Copy(R82, R141, 0x140001024));
  Block.Ops.push_back(Copy(RDX2, RSI1, 0x140001028));
  Block.Ops.push_back(Copy(RCX2, RBP1, 0x14000102c));

  auto Hint = std::make_shared<SourceCallTypeHint>();
  Hint->CallKind = SourceCallTypeHint::Kind::Native;
  Hint->TargetName = "CxxFrameHandler3";
  Hint->TargetAddress = 0x140002000;
  Hint->Signature.ReturnType = NdType::makeInt(4);
  Hint->Signature.Architecture = Arch::X64;
  for (int I = 0; I < 4; ++I) {
    SourceParameterTypeHint P;
    P.Name = "arg" + std::to_string(I);
    P.Type = NdType::makePtr(NdType::makeVoid());
    Hint->Signature.Parameters.push_back(P);
  }

  MedOp Call;
  Call.Opcode = NdOp::CALL;
  Call.Addr = 0x140001030;
  Call.SourceCallHint = Hint;
  Call.Output = Reg(0, 1, x86reg::RAX);
  Call.Output.Size = 4;
  Call.addInput(MedVar::makeConst(0x140002000, 8));
  Call.addInput(Reg(10, 1, x86reg::RCX));
  Call.addInput(Reg(11, 1, x86reg::RDX));
  Call.addInput(R81);
  Call.addInput(Reg(13, 1, x86reg::R9));
  Block.Ops.push_back(std::move(Call));

  MedOp Ret;
  Ret.Opcode = NdOp::RETURN;
  Ret.Addr = 0x140001040;
  Ret.addInput(Reg(0, 1, x86reg::RAX));
  Block.Ops.push_back(std::move(Ret));
  Med.Blocks.push_back(std::move(Block));

  std::map<va_t, std::string> Names;
  Names[0x140002000] = "CxxFrameHandler3";
  MedToHighConverter Converter;
  Converter.setBinaryImage(&Img);
  Converter.setFuncNames(&Names);
  HighFunc High = Converter.convert(Med, Arch::X64);

  const std::string Source = emitFunctions({High}, Arch::X64, &Img);
  EXPECT_NE(Source.find("(void*)(uintptr_t)(arg0), (void*)(uintptr_t)(arg1), "
                        "(void*)(uintptr_t)(arg2), (void*)(uintptr_t)(arg3)"),
            std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("0 /* unknown */"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("0x66"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, Win64ParamSsaIdMapsToAbiSlot) {
  BinaryImage Img;
  Img.Arch = Arch::X64;
  Img.Bits = Bitness::Bits64;
  Img.Format = BinaryFormat::COFF;

  MedFunc Med;
  Med.Entry = 0x140001000;
  Med.Name = "ssa_param";
  Med.CC = CallingConv::Win64;
  const uint64_t ParamOffs[] = {x86reg::RCX, x86reg::RDX, x86reg::R8,
                                x86reg::R9};
  for (int I = 0; I < 4; ++I) {
    MedVar P;
    P.Kind = MedVar::Param;
    P.TheArch = Arch::X64;
    P.Id = 6 + I;
    P.Size = 8;
    P.RegOff = ParamOffs[I];
    Med.Params.push_back(P);
  }
  for (int I = 4; I < 8; ++I) {
    MedVar P;
    P.Kind = MedVar::Param;
    P.TheArch = Arch::X64;
    P.Id = I;
    P.Size = 8;
    P.RegOff = kNoParamReg;
    Med.Params.push_back(P);
  }

  MedVar Addr;
  Addr.Kind = MedVar::Param;
  Addr.TheArch = Arch::X64;
  Addr.Id = 6;
  Addr.Size = 8;
  Addr.RegOff = x86reg::RCX;

  MedBlock Block;
  Block.Id = 0;
  Block.StartAddr = 0x140001000;
  Block.EndAddr = 0x140001010;
  auto Hint = std::make_shared<SourceCallTypeHint>();
  Hint->CallKind = SourceCallTypeHint::Kind::Native;
  Hint->TargetName = "use_param";
  Hint->TargetAddress = 0x140002000;
  SourceParameterTypeHint HP;
  HP.Name = "p";
  HP.Type = NdType::makePtr(NdType::makeVoid());
  Hint->Signature.Parameters.push_back(HP);
  Hint->Signature.ReturnType = NdType::makeVoid();
  MedOp Call;
  Call.Opcode = NdOp::CALL;
  Call.Addr = 0x140001000;
  Call.SourceCallHint = Hint;
  Call.addInput(MedVar::makeConst(0x140002000, 8));
  Call.addInput(Addr);
  Block.Ops.push_back(std::move(Call));
  MedOp Ret;
  Ret.Opcode = NdOp::RETURN;
  Ret.Addr = 0x140001008;
  Block.Ops.push_back(std::move(Ret));
  Med.Blocks.push_back(std::move(Block));

  std::map<va_t, std::string> Names;
  Names[0x140002000] = "use_param";
  MedToHighConverter Converter;
  Converter.setBinaryImage(&Img);
  Converter.setFuncNames(&Names);
  HighFunc High = Converter.convert(Med, Arch::X64);
  std::string IR;
  for (const HighStmt &S : High.Body)
    IR += S.str() + "\n";
  EXPECT_NE(IR.find("use_param(arg0)"), std::string::npos) << IR;
  EXPECT_EQ(IR.find("arg6"), std::string::npos) << IR;
}

TEST(HighCPointerAddresses, Win64CopyFromTempAfterParamCopyIsNotParam) {
  // `mov eax, edx` copies eRecord into the RAX family.  A later `mov rax, [p]`
  // is a bucket pointer, not that parameter.  Remapping RAX.3 onto arg1
  // deleted CAtlMap walks (LookupColor).
  BinaryImage Img;
  Img.Arch = Arch::X64;
  Img.Bits = Bitness::Bits64;
  Img.Format = BinaryFormat::COFF;

  auto ParamAt = [](int Id, uint64_t Off, uint16_t Size) {
    MedVar V;
    V.Kind = MedVar::Param;
    V.TheArch = Arch::X64;
    V.Id = Id;
    V.Size = Size;
    V.RegOff = Off;
    return V;
  };
  auto RegAt = [](int Id, int SSA, uint64_t Off, uint16_t Size) {
    MedVar V;
    V.Kind = MedVar::Reg;
    V.TheArch = Arch::X64;
    V.Id = Id;
    V.SSAVer = SSA;
    V.Size = Size;
    V.RegOff = Off;
    return V;
  };
  auto TempAt = [](int Id, int SSA, uint16_t Size) {
    MedVar V;
    V.Kind = MedVar::Temp;
    V.TheArch = Arch::X64;
    V.Id = Id;
    V.SSAVer = SSA;
    V.Size = Size;
    return V;
  };

  const MedVar This = ParamAt(0, x86reg::RCX, 8);
  const MedVar Record = ParamAt(1, x86reg::RDX, 4);
  const MedVar Edx0 = RegAt(2, 0, x86reg::RDX, 4);
  const MedVar Eax2 = RegAt(0, 2, x86reg::RAX, 4);
  const MedVar TAddr = TempAt(20, 0, 8);
  const MedVar T22 = TempAt(22, 0, 8);
  const MedVar Rax3 = RegAt(0, 3, x86reg::RAX, 8);

  MedFunc Med;
  Med.Entry = 0x140001000;
  Med.Name = "lookup_bin";
  Med.CC = CallingConv::Win64;
  Med.Params = {This, Record};

  MedBlock Block;
  Block.Id = 0;
  Block.StartAddr = 0x140001000;
  Block.EndAddr = 0x140001020;
  MedOp SaveRecord;
  SaveRecord.Opcode = NdOp::COPY;
  SaveRecord.Output = Eax2;
  SaveRecord.addInput(Edx0);
  SaveRecord.Addr = 0x140001000;
  Block.Ops.push_back(std::move(SaveRecord));
  MedOp Add;
  Add.Opcode = NdOp::INT_ADD;
  Add.Output = TAddr;
  Add.addInput(This);
  Add.addInput(MedVar::makeConst(8, 8));
  Add.Addr = 0x140001004;
  Block.Ops.push_back(std::move(Add));
  MedOp Load;
  Load.Opcode = NdOp::LOAD;
  Load.Output = T22;
  Load.addInput(TAddr);
  Load.Addr = 0x140001008;
  Block.Ops.push_back(std::move(Load));
  MedOp TakeBin;
  TakeBin.Opcode = NdOp::COPY;
  TakeBin.Output = Rax3;
  TakeBin.addInput(T22);
  TakeBin.Addr = 0x14000100C;
  Block.Ops.push_back(std::move(TakeBin));
  MedOp Ret;
  Ret.Opcode = NdOp::RETURN;
  Ret.Addr = 0x140001010;
  Ret.addInput(Rax3);
  Block.Ops.push_back(std::move(Ret));
  Med.Blocks.push_back(std::move(Block));

  MedToHighConverter Converter;
  Converter.setBinaryImage(&Img);
  HighFunc High = Converter.convert(Med, Arch::X64);
  std::string IR;
  for (const HighStmt &S : High.Body)
    IR += S.str() + "\n";
  EXPECT_NE(IR.find("*"), std::string::npos) << IR;
  EXPECT_EQ(IR.find("return arg1"), std::string::npos) << IR;

  High.Entry = Med.Entry;
  High.Name = "lookup_bin";
  High.ReturnType = NdType::makePtr(NdType::makeVoid());
  High.Params = {{"this", NdType::makePtr(NdType::makeVoid())},
                 {"eRecord", NdType::makeInt(4, false)}};
  const std::string Source = emitFunctions({High}, Arch::X64, &Img);
  EXPECT_NE(Source.find("return"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("return eRecord"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("return arg1"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, TypedPointerIndexLoadPrintsBucketsAndNodeFields) {
  auto Node = NdType::makeNamedRecord("CNode", 24);
  auto NodePtr = NdType::makePtr(Node);
  Node->FieldDisplayNames = {"m_key", "m_value", "m_pNext", "m_nHash"};
  Node->FieldDisplayOffsets = {0, 4, 8, 16};
  Node->FieldDisplayTypes = {NdType::makeInt(4, false), NdType::makeInt(4, false),
                             NodePtr, NdType::makeInt(4, false)};
  auto BinsPtr = NdType::makePtr(NodePtr);
  auto Map = NdType::makeNamedRecord("CAtlMap", 72);
  Map->FieldDisplayNames = {"m_ppBins", "m_nBins"};
  Map->FieldDisplayOffsets = {0, 16};
  Map->FieldDisplayTypes = {BinsPtr, NdType::makeInt(4, false)};
  auto Table = NdType::makeNamedRecord("CRecordDataTable", 640);
  Table->FieldDisplayNames = {"m_colorTable"};
  Table->FieldDisplayOffsets = {168};
  Table->FieldDisplayTypes = {Map};

  HighFunc Func;
  Func.Name = "LookupColor";
  Func.ReturnType = NdType::makeInt(4, false);
  Func.Params = {{"this", NdType::makePtr(Table)},
                 {"eRecord", NdType::makeInt(4, false)}};

  auto Temp = [](int Id, uint16_t Size) {
    MedVar V;
    V.Kind = MedVar::Temp;
    V.Id = Id;
    V.Size = Size;
    V.TheArch = Arch::X64;
    return V;
  };
  const auto Bins = Temp(2, 8);
  const auto NBins = Temp(19, 4);
  const auto Rem = Temp(20, 4);
  const auto Bucket = Temp(22, 8);
  const auto Cursor = Temp(1, 8);
  const auto Hash = Temp(32, 4);
  const auto Key = Temp(33, 4);
  const auto Next = Temp(23, 8);
  const auto Value = Temp(34, 4);

  auto This = parameter(0, Func.Params[0].Type);
  MedVar RecordVar;
  RecordVar.Kind = MedVar::Param;
  RecordVar.Id = 1;
  RecordVar.Size = 4;
  RecordVar.TheArch = Arch::X64;
  auto Record = HighExpr::makeVar(RecordVar, Func.Params[1].Type);

  auto AddImm = [](ExprPtr Base, uint64_t Off) {
    auto E = HighExpr::makeBinop(NdOp::INT_ADD, std::move(Base),
                                 HighExpr::makeConst(Off, 8));
    E->Type = NdType::makeInt(8, false);
    return E;
  };

  HighStmt LoadBins;
  LoadBins.Kind = StmtKind::Assign;
  LoadBins.Dst = HighExpr::makeVar(Bins, BinsPtr);
  LoadBins.Val = HighExpr::makeLoad(AddImm(This, 168), BinsPtr);

  HighStmt LoadNBins;
  LoadNBins.Kind = StmtKind::Assign;
  LoadNBins.Dst = HighExpr::makeVar(NBins, NdType::makeInt(4, false));
  LoadNBins.Val =
      HighExpr::makeLoad(AddImm(This, 184), NdType::makeInt(4, false));

  HighStmt TakeRem;
  TakeRem.Kind = StmtKind::Assign;
  TakeRem.Dst = HighExpr::makeVar(Rem, NdType::makeInt(4, false));
  TakeRem.Val = HighExpr::makeBinop(
      NdOp::INT_REM, Record, HighExpr::makeVar(NBins, NdType::makeInt(4, false)));

  auto Scale = HighExpr::makeBinop(
      NdOp::INT_MULT, HighExpr::makeVar(Rem, NdType::makeInt(4, false)),
      HighExpr::makeConst(8, 8));
  auto BucketAddr = HighExpr::makeBinop(
      NdOp::INT_ADD, HighExpr::makeVar(Bins, BinsPtr), std::move(Scale));

  HighStmt LoadBucket;
  LoadBucket.Kind = StmtKind::Assign;
  LoadBucket.Dst = HighExpr::makeVar(Bucket, NodePtr);
  LoadBucket.Val = HighExpr::makeLoad(std::move(BucketAddr), NodePtr);

  HighStmt TakeCursor;
  TakeCursor.Kind = StmtKind::Assign;
  TakeCursor.Dst = HighExpr::makeVar(Cursor, NodePtr);
  TakeCursor.Val = HighExpr::makeVar(Bucket, NodePtr);

  HighStmt LoadHash;
  LoadHash.Kind = StmtKind::Assign;
  LoadHash.Dst = HighExpr::makeVar(Hash, NdType::makeInt(4, false));
  LoadHash.Val = HighExpr::makeLoad(
      AddImm(HighExpr::makeVar(Cursor, NodePtr), 16), NdType::makeInt(4, false));

  HighStmt LoadKey;
  LoadKey.Kind = StmtKind::Assign;
  LoadKey.Dst = HighExpr::makeVar(Key, NdType::makeInt(4, false));
  LoadKey.Val = HighExpr::makeLoad(HighExpr::makeVar(Cursor, NodePtr),
                                   NdType::makeInt(4, false));

  HighStmt LoadNext;
  LoadNext.Kind = StmtKind::Assign;
  LoadNext.Dst = HighExpr::makeVar(Next, NodePtr);
  LoadNext.Val =
      HighExpr::makeLoad(AddImm(HighExpr::makeVar(Cursor, NodePtr), 8), NodePtr);

  HighStmt Step;
  Step.Kind = StmtKind::Assign;
  Step.Dst = HighExpr::makeVar(Cursor, NodePtr);
  Step.Val = HighExpr::makeVar(Next, NodePtr);

  HighStmt LoadValue;
  LoadValue.Kind = StmtKind::Assign;
  LoadValue.Dst = HighExpr::makeVar(Value, NdType::makeInt(4, false));
  LoadValue.Val = HighExpr::makeLoad(
      AddImm(HighExpr::makeVar(Cursor, NodePtr), 4), NdType::makeInt(4, false));

  HighStmt Hit;
  Hit.Kind = StmtKind::If;
  Hit.Cond = HighExpr::makeBinop(
      NdOp::BOOL_AND,
      HighExpr::makeBinop(NdOp::INT_EQUAL,
                          HighExpr::makeVar(Hash, NdType::makeInt(4, false)),
                          Record),
      HighExpr::makeBinop(NdOp::INT_EQUAL,
                          HighExpr::makeVar(Key, NdType::makeInt(4, false)),
                          Record));
  HighStmt HitRet;
  HitRet.Kind = StmtKind::Return;
  HitRet.RetVal = HighExpr::makeVar(Value, NdType::makeInt(4, false));
  Hit.Body.push_back(std::move(HitRet));

  HighStmt Miss;
  Miss.Kind = StmtKind::Return;
  Miss.RetVal = HighExpr::makeConst(0xFFFFFF, 4);

  Func.Body = {LoadBins, LoadNBins, TakeRem, LoadBucket, TakeCursor,
               LoadHash, LoadKey, LoadValue, Hit, LoadNext, Step, Miss};

  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("this->m_colorTable.m_ppBins["), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("eRecord % this->m_colorTable.m_nBins"),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("m_nHash"), std::string::npos) << Source;
  EXPECT_NE(Source.find("m_key"), std::string::npos) << Source;
  EXPECT_NE(Source.find("m_pNext"), std::string::npos) << Source;
  EXPECT_NE(Source.find("m_value"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("+ 16"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("]->m_nHash"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("]->m_value"), std::string::npos) << Source;
  EXPECT_NE(Source.find("m_nHash == eRecord"), std::string::npos) << Source;
  EXPECT_NE(Source.find("m_key == eRecord"), std::string::npos) << Source;
  EXPECT_NE(Source.find("t1->m_pNext"), std::string::npos) << Source;
  EXPECT_NE(Source.find("return t1->m_value"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t1->m_pNext ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t22 ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t32 ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t23 ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t34 ="), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, TypedMapCursorComposesHashKeyNextValue) {
  // Guest LookupColor HighIR: untyped temps, RenameTag cursor, nested
  // `(i64)(eRecord % nBins) * 8`, and `v1 = t22` hidden by CopyForward.
  // Collect must still type the cursor so hash/next/value assigns fold.
  auto Rank = NdType::makeNamedRecord("eRecordRank", 4, true);
  auto Node = NdType::makeNamedRecord(
      "ATL::CAtlMap<enum eRecordRank,unsigned long>::CNode", 24);
  auto NodePtr = NdType::makePtr(Node);
  Node->FieldDisplayNames = {"m_key", "m_value", "m_pNext", "m_nHash"};
  Node->FieldDisplayOffsets = {0, 4, 8, 16};
  Node->FieldDisplayTypes = {Rank, NdType::makeInt(4, false), NodePtr,
                             NdType::makeInt(4, false)};
  auto BinsPtr = NdType::makePtr(NodePtr);
  auto Map = NdType::makeNamedRecord("ATL::CAtlMap", 72);
  Map->FieldDisplayNames = {"m_ppBins", "m_nBins"};
  Map->FieldDisplayOffsets = {0, 16};
  Map->FieldDisplayTypes = {BinsPtr, NdType::makeInt(4, false)};
  auto Table = NdType::makeNamedRecord("CRecordDataTable", 640);
  Table->FieldDisplayNames = {"m_colorTable"};
  Table->FieldDisplayOffsets = {168};
  Table->FieldDisplayTypes = {Map};

  HighFunc Func;
  Func.Name = "LookupColor";
  Func.ReturnType = NdType::makeInt(4, false);
  Func.Params = {{"this", NdType::makePtr(Table)}, {"eRecord", Rank}};

  auto Temp = [](int Id, int SSA, uint16_t Size, int Rename = -1) {
    MedVar V;
    V.Kind = MedVar::Temp;
    V.Id = Id;
    V.SSAVer = SSA;
    V.Size = Size;
    V.RenameTag = Rename;
    V.TheArch = Arch::X64;
    return V;
  };
  const auto Bins = Temp(2, 0, 8);
  const auto NBins = Temp(19, 0, 4);
  const auto Bucket = Temp(22, 0, 8);
  const auto Cursor = Temp(1, 0, 8, 1);
  const auto Hash = Temp(19, 2, 4);
  const auto Next = Temp(2, 3, 8);
  const auto Value = Temp(19, 4, 4);

  auto This = parameter(0, Func.Params[0].Type);
  MedVar RecordVar;
  RecordVar.Kind = MedVar::Param;
  RecordVar.Id = 1;
  RecordVar.Size = 4;
  RecordVar.TheArch = Arch::X64;
  auto Record = HighExpr::makeVar(RecordVar, Func.Params[1].Type);
  auto Int64 = NdType::makeInt(8, false);
  auto Int32 = NdType::makeInt(4, false);

  auto AddImm = [&](ExprPtr Base, uint64_t Off) {
    auto E = HighExpr::makeBinop(NdOp::INT_ADD, std::move(Base),
                                 HighExpr::makeConst(Off, 8));
    E->Type = Int64;
    return E;
  };
  auto Untyped = [&](const MedVar &V, const TypeRef &Ty) {
    return HighExpr::makeVar(V, Ty);
  };

  HighStmt LoadBins;
  LoadBins.Kind = StmtKind::Assign;
  LoadBins.Dst = Untyped(Bins, Int64);
  LoadBins.Val = HighExpr::makeLoad(AddImm(This, 168), Int64);

  HighStmt LoadNBins;
  LoadNBins.Kind = StmtKind::Assign;
  LoadNBins.Dst = Untyped(NBins, Int32);
  LoadNBins.Val = HighExpr::makeLoad(AddImm(This, 184), Int32);

  auto RecordView = HighExpr::makeUnary(NdOp::INT_ZEXT, Record);
  RecordView->Type = Int32;
  auto Rem = HighExpr::makeBinop(NdOp::INT_REM, std::move(RecordView),
                                 Untyped(NBins, Int32));
  auto Wide = HighExpr::makeUnary(NdOp::INT_ZEXT, std::move(Rem));
  Wide->Type = Int64;
  auto Scale =
      HighExpr::makeBinop(NdOp::INT_MULT, std::move(Wide), HighExpr::makeConst(8, 8));
  auto BucketAddr =
      HighExpr::makeBinop(NdOp::INT_ADD, Untyped(Bins, Int64), std::move(Scale));

  HighStmt LoadBucket;
  LoadBucket.Kind = StmtKind::Assign;
  LoadBucket.Dst = Untyped(Bucket, Int64);
  LoadBucket.Val = HighExpr::makeLoad(std::move(BucketAddr), Int64);

  HighStmt TakeCursor;
  TakeCursor.Kind = StmtKind::Assign;
  TakeCursor.Dst = Untyped(Cursor, Int64);
  TakeCursor.Val = Untyped(Bucket, Int64);

  HighStmt Miss;
  Miss.Kind = StmtKind::If;
  Miss.Cond = HighExpr::makeBinop(NdOp::INT_EQUAL, HighExpr::makeVar(Cursor, NodePtr),
                                  HighExpr::makeConst(0, 8));
  HighStmt MissRet;
  MissRet.Kind = StmtKind::Return;
  MissRet.RetVal = HighExpr::makeConst(0xFFFFFF, 4);
  Miss.Body.push_back(std::move(MissRet));

  HighStmt LoadHash;
  LoadHash.Kind = StmtKind::Assign;
  LoadHash.Dst = Untyped(Hash, Int32);
  LoadHash.Val =
      HighExpr::makeLoad(AddImm(HighExpr::makeVar(Cursor, NodePtr), 16), Int32);

  HighStmt Hit;
  Hit.Kind = StmtKind::If;
  Hit.Cond = HighExpr::makeBinop(
      NdOp::BOOL_AND,
      HighExpr::makeBinop(NdOp::INT_EQUAL, Untyped(Hash, Int32), Record),
      HighExpr::makeBinop(
          NdOp::INT_EQUAL,
          HighExpr::makeLoad(HighExpr::makeVar(Cursor, NodePtr), Int32), Record));
  HighStmt HitBreak;
  HitBreak.Kind = StmtKind::Break;
  Hit.Body.push_back(std::move(HitBreak));

  HighStmt LoadNext;
  LoadNext.Kind = StmtKind::Assign;
  LoadNext.Dst = Untyped(Next, Int64);
  LoadNext.Val =
      HighExpr::makeLoad(AddImm(HighExpr::makeVar(Cursor, NodePtr), 8), Int64);

  HighStmt Step;
  Step.Kind = StmtKind::Assign;
  Step.Dst = HighExpr::makeVar(Cursor, NodePtr);
  Step.Val = Untyped(Next, Int64);

  HighStmt Loop;
  Loop.Kind = StmtKind::While;
  Loop.Cond = HighExpr::makeConst(1, 1);
  Loop.Body = {Miss, LoadHash, Hit, LoadNext, Step};

  HighStmt LoadValue;
  LoadValue.Kind = StmtKind::Assign;
  LoadValue.Dst = Untyped(Value, Int32);
  LoadValue.Val =
      HighExpr::makeLoad(AddImm(HighExpr::makeVar(Cursor, NodePtr), 4), Int32);

  HighStmt Ret;
  Ret.Kind = StmtKind::Return;
  Ret.RetVal = Untyped(Value, Int32);

  Func.Body = {LoadBins, LoadNBins, LoadBucket, TakeCursor, Loop, LoadValue,
               Ret};

  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("this->m_colorTable.m_ppBins["), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("eRecord % this->m_colorTable.m_nBins"),
            std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("(uint32_t)eRecord"), std::string::npos) << Source;
  EXPECT_NE(Source.find("for (v1 = "), std::string::npos) << Source;
  EXPECT_NE(Source.find("v1 = "), std::string::npos) << Source;
  EXPECT_NE(Source.find("CNode* v1"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("int64_t v1"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("CAtlMap* v1"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("while (1)"), std::string::npos) << Source;
  EXPECT_NE(Source.find("this->m_colorTable.m_ppBins["), std::string::npos)
      << Source;
  EXPECT_NE(Source.find("v1->m_nHash == eRecord"), std::string::npos) << Source;
  EXPECT_NE(Source.find("v1->m_key == eRecord"), std::string::npos) << Source;
  EXPECT_NE(Source.find("v1->m_pNext"), std::string::npos) << Source;
  EXPECT_NE(Source.find("return v1->m_value"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("v1->m_pNext ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t22 ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t19_2 ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t2_3 ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("t19_4 ="), std::string::npos) << Source;
  EXPECT_EQ(Source.find("+ 16"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("]->m_nHash"), std::string::npos) << Source;
}

