  Join.Ops.push_back(Copy(R8, MedVar::makeConst(1, 4), 0x140001020));
  Join.Ops.push_back(Copy(RDX, MedVar::makeConst(0x140005000, 8), 0x140001028));
  Join.Ops.push_back(Copy(RCX, MedVar::makeConst(0x140006000, 8), 0x140001030));
