  Med.Blocks.push_back(std::move(Setup));

  MedBlock Then;
  Then.Id = 2;
  Then.StartAddr = 0x140001020;
  Then.Preds = {1};
  Then.Succs = {4};
  Then.Ops.push_back(Copy(RDX1, MedVar::makeConst(0xCF1, 4), 0x140001020));
  MedOp ThenBr;
  ThenBr.Opcode = NdOp::BRANCH;
  ThenBr.Addr = 0x140001028;
  ThenBr.addInput(MedVar::makeConst(0x140001038, 8));
  Then.Ops.push_back(std::move(ThenBr));
  Med.Blocks.push_back(std::move(Then));

  MedBlock ElseB;
  ElseB.Id = 3;
  ElseB.StartAddr = 0x140001030;
  ElseB.Preds = {1};
  ElseB.Succs = {4};
  ElseB.Ops.push_back(Copy(RDX2, MedVar::makeConst(0xCF0, 4), 0x140001030));
  MedOp ElseBr;
  ElseBr.Opcode = NdOp::BRANCH;
  ElseBr.Addr = 0x140001034;
  ElseBr.addInput(MedVar::makeConst(0x140001038, 8));
  ElseB.Ops.push_back(std::move(ElseBr));
  Med.Blocks.push_back(std::move(ElseB));

  MedBlock CallBlk;
  CallBlk.Id = 4;
  CallBlk.StartAddr = 0x140001038;
  CallBlk.Preds = {2, 3};
  PhiNode RdxPhi;
  RdxPhi.Output = Reg(11, 3, x86reg::RDX);
  RdxPhi.Args.push_back({2, RDX1});
  RdxPhi.Args.push_back({3, RDX2});
