TEST(HighCPointerAddresses, Win64IpMapSplitCallKeepsPredLeaArgs) {
  BinaryImage Img;
  Img.Arch = Arch::X64;
  Img.Bits = Bitness::Bits64;
  Img.Format = BinaryFormat::COFF;

  auto Reg = [](int Id, int SSA, uint64_t Off) {
    MedVar V;
    V.Kind = MedVar::Reg;
    V.TheArch = Arch::X64;
    V.Id = Id;
    V.SSAVer = SSA;
    V.Size = 8;
    V.RegOff = Off;
    return V;
  };
  auto Copy = [](MedVar Dst, MedVar Src, va_t Addr) {
    MedOp Op;
    Op.Opcode = NdOp::COPY;
    Op.Output = Dst;
    Op.addInput(Src);
    Op.Addr = Addr;
    return Op;
  };

  MedFunc Med;
  Med.Entry = 0x140001000;
  Med.Name = "label_getcommon";
  Med.CC = CallingConv::Win64;
  for (int I = 0; I < 2; ++I) {
    MedVar P;
    P.Kind = MedVar::Param;
    P.TheArch = Arch::X64;
    P.Id = I;
    P.Size = 8;
    P.RegOff = I == 0 ? x86reg::RCX : x86reg::RDX;
    Med.Params.push_back(P);
  }

  const MedVar RBP = Reg(20, 1, x86reg::RBP);
  const MedVar RCX1 = Reg(10, 1, x86reg::RCX);
  const MedVar RDX1 = Reg(11, 1, x86reg::RDX);
  const MedVar R81 = Reg(12, 1, x86reg::R8);

  MedBlock Setup;
  Setup.Id = 0;
  Setup.StartAddr = 0x140001000;
  Setup.Succs = {1};
  MedOp LeaR8;
  LeaR8.Opcode = NdOp::INT_ADD;
  LeaR8.Output = R81;
  LeaR8.addInput(RBP);
  LeaR8.addInput(MedVar::makeConst(0x40, 8));
  LeaR8.Addr = 0x140001000;
  Setup.Ops.push_back(std::move(LeaR8));
  Setup.Ops.push_back(Copy(RDX1, MedVar::makeConst(1418, 4), 0x140001008));
  MedOp LeaRcx;
  LeaRcx.Opcode = NdOp::INT_ADD;
  LeaRcx.Output = RCX1;
  LeaRcx.addInput(RBP);
  LeaRcx.addInput(MedVar::makeConst(0x80, 8));
  LeaRcx.Addr = 0x140001010;
  Setup.Ops.push_back(std::move(LeaRcx));
  Med.Blocks.push_back(std::move(Setup));

  MedBlock CallBlk;
  CallBlk.Id = 1;
  CallBlk.StartAddr = 0x140001018;
  CallBlk.Preds = {0};
  MedOp Call;
  Call.Opcode = NdOp::CALL;
  Call.Addr = 0x140001018;
  Call.addInput(MedVar::makeConst(0x140002000, 8));
  CallBlk.Ops.push_back(std::move(Call));
  Med.Blocks.push_back(std::move(CallBlk));

  LowToMedConverter().runRegisterDce(Med, Arch::X64);
  bool KeptR8 = false;
  bool KeptRcx = false;
  for (const auto &Op : Med.Blocks[0].Ops) {
    if (Op.Output.Kind == MedVar::Reg && Op.Output.RegOff == x86reg::R8)
      KeptR8 = true;
    if (Op.Output.Kind == MedVar::Reg && Op.Output.RegOff == x86reg::RCX)
      KeptRcx = true;
  }
  EXPECT_TRUE(KeptR8);
  EXPECT_TRUE(KeptRcx);

  std::map<va_t, std::string> Names;
  Names[0x140002000] = "LookupTextW";
  MedToHighConverter Converter;
  Converter.setBinaryImage(&Img);
  Converter.setFuncNames(&Names);
  HighFunc High = Converter.convert(Med, Arch::X64);
  const std::string Source = emitFunctions({High}, Arch::X64, &Img);
  EXPECT_NE(Source.find(", 1418,"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, Win64CallOnlyBlockRecoversPredR9AndHome) {
  BinaryImage Img;
  Img.Arch = Arch::X64;
  Img.Bits = Bitness::Bits64;
  Img.Format = BinaryFormat::COFF;

  auto Reg = [](int Id, int SSA, uint64_t Off, uint16_t Size = 8) {
    MedVar V;
    V.Kind = MedVar::Reg;
    V.TheArch = Arch::X64;
    V.Id = Id;
    V.SSAVer = SSA;
    V.Size = Size;
    V.RegOff = Off;
    return V;
  };
  auto Copy = [](MedVar Dst, MedVar Src, va_t Addr) {
    MedOp Op;
    Op.Opcode = NdOp::COPY;
    Op.Output = Dst;
    Op.addInput(Src);
    Op.Addr = Addr;
    return Op;
  };

  MedFunc Med;
  Med.Entry = 0x140001000;
  Med.Name = "getrecordname_concat";
  Med.CC = CallingConv::Win64;
  for (int I = 0; I < 2; ++I) {
    MedVar P;
    P.Kind = MedVar::Param;
    P.TheArch = Arch::X64;
    P.Id = I;
    P.Size = 8;
    P.RegOff = I == 0 ? x86reg::RCX : x86reg::RDX;
    Med.Params.push_back(P);
  }

  const MedVar RSP = Reg(4, 1, x86reg::RSP);
  const MedVar RCX1 = Reg(10, 1, x86reg::RCX);
  const MedVar RDX1 = Reg(11, 1, x86reg::RDX);
  const MedVar R81 = Reg(12, 1, x86reg::R8);
  const MedVar R91 = Reg(13, 1, x86reg::R9);
  const MedVar ESI1 = Reg(14, 1, x86reg::RSI, 4);
  MedVar Home;
  Home.Kind = MedVar::Temp;
  Home.TheArch = Arch::X64;
  Home.Id = 50;
  Home.SSAVer = 1;
  Home.Size = 8;

  MedBlock Setup;
  Setup.Id = 0;
  Setup.StartAddr = 0x140001000;
  Setup.Succs = {1};
  Setup.Ops.push_back(Copy(RSP, RSP, 0x140001000));
  Setup.Ops.push_back(Copy(RCX1, MedVar::makeConst(0x1000, 8), 0x140001008));
  Setup.Ops.push_back(Copy(RDX1, MedVar::makeConst(0xAAA, 8), 0x140001010));
  Setup.Ops.push_back(Copy(R81, MedVar::makeConst(11, 4), 0x140001018));
  const MedVar RDI1 = Reg(15, 1, x86reg::RDI);
  Setup.Ops.push_back(Copy(RDI1, MedVar::makeConst(0xBBB, 8), 0x14000101C));
  Setup.Ops.push_back(Copy(ESI1, MedVar::makeConst(7, 4), 0x140001020));
  MedOp Helper;
  Helper.Opcode = NdOp::INDIR_CALL;
  Helper.Addr = 0x140001024;
  Helper.CallSiteId = 1;
  Helper.addInput(MedVar::makeConst(0x140003000, 8));
  Setup.Ops.push_back(std::move(Helper));
  MedOp LeaHome;
  LeaHome.Opcode = NdOp::INT_ADD;
  LeaHome.Output = Home;
  LeaHome.addInput(RSP);
  LeaHome.addInput(MedVar::makeConst(0x20, 8));
  LeaHome.Addr = 0x140001030;
  Setup.Ops.push_back(std::move(LeaHome));
  MedOp StoreHome;
  StoreHome.Opcode = NdOp::STORE;
  StoreHome.Addr = 0x140001038;
  StoreHome.addInput(Home);
  const MedVar ESIDangling = Reg(14, 51, x86reg::RSI, 4);
  StoreHome.addInput(ESIDangling);
  Setup.Ops.push_back(std::move(StoreHome));
  const MedVar RDIDangling = Reg(15, 61, x86reg::RDI);
  Setup.Ops.push_back(Copy(R91, RDIDangling, 0x140001040));
  // Later helper CALLs bump ESI/RDI SSA; those versions are CallClobbers
  // (`PreservedPrefixSize == 0`) so medvarToExpr is Undef until the walk
  // reaches `COPY esi = GetLength` / `COPY rdi = cstr` before the helpers.
  Med.CallClobbers.push_back({ESIDangling, 1, {}, 0});
  Med.CallClobbers.push_back({RDIDangling, 1, {}, 0});
  Med.Blocks.push_back(std::move(Setup));

  MedBlock CallBlk;
  CallBlk.Id = 1;
  CallBlk.StartAddr = 0x140001048;
  CallBlk.Preds = {0};
  MedOp Call;
  Call.Opcode = NdOp::INDIR_CALL;
  Call.Addr = 0x140001048;
  Call.addInput(MedVar::makeConst(0x140002000, 8));
  CallBlk.Ops.push_back(std::move(Call));
  Med.Blocks.push_back(std::move(CallBlk));

  LowToMedConverter().runRegisterDce(Med, Arch::X64);
  bool KeptR9 = false;
  bool KeptHome = false;
  for (const auto &Op : Med.Blocks[0].Ops) {
    if (Op.Output.Kind == MedVar::Reg && Op.Output.RegOff == x86reg::R9)
      KeptR9 = true;
    if (Op.Opcode == NdOp::STORE)
      KeptHome = true;
  }
  EXPECT_TRUE(KeptR9);
  EXPECT_TRUE(KeptHome);

  std::map<va_t, std::string> Names;
  Names[0x140002000] = "Concatenate";
  MedToHighConverter Converter;
  Converter.setBinaryImage(&Img);
  Converter.setFuncNames(&Names);
  HighFunc High = Converter.convert(Med, Arch::X64);
  const std::string Source = emitFunctions({High}, Arch::X64, &Img);
  const auto CallAt = Source.rfind("Concatenate(");
  ASSERT_NE(CallAt, std::string::npos) << Source;
  const auto Open = Source.find('(', CallAt);
  const auto Close = Source.find(')', Open);
  ASSERT_NE(Open, std::string::npos) << Source;
  ASSERT_NE(Close, std::string::npos) << Source;
  const std::string Args = Source.substr(Open + 1, Close - Open - 1);
  EXPECT_EQ(std::count(Args.begin(), Args.end(), ','), 4) << Source;
}

TEST(HighCPointerAddresses, NestedIfGotoSkipInvertsToIf) {
  HighFunc Func;
  Func.Name = "nested_skip";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();

  HighStmt Skip;
  Skip.Kind = StmtKind::If;
  Skip.Cond = HighExpr::makeBinop(NdOp::INT_EQUAL, parameter(0),
                                  HighExpr::makeConst(0, 8));
  HighStmt ToRest;
  ToRest.Kind = StmtKind::Goto;
  ToRest.GotoTarget = 0x140001200;
  Skip.Body = {ToRest};

  HighStmt Work;
  Work.Kind = StmtKind::Call;
  Work.CallExpr = HighExpr::makeCall("taken", 0x140002000, {parameter(0)});

  HighStmt Rest;
  Rest.Kind = StmtKind::Call;
  Rest.Addr = 0x140001200;
  Rest.CallExpr = HighExpr::makeCall("rest", 0x140002100, {});

  HighStmt Outer;
  Outer.Kind = StmtKind::If;
  Outer.Cond = HighExpr::makeBinop(NdOp::INT_NOTEQUAL, parameter(0),
                                   HighExpr::makeConst(0, 8));
  Outer.Body = {Skip, Work, Rest};

  Func.Body = {Outer};
  structureIfElse(Func, 8);
  const std::string Source = emitFunctions({Func});
  EXPECT_EQ(Source.find("goto "), std::string::npos) << Source;
  EXPECT_NE(Source.find("taken("), std::string::npos) << Source;
  EXPECT_NE(Source.find("rest("), std::string::npos) << Source;
}

