  ToFormat.GotoTarget = 0x14000168F;
  HighStmt MaxSkip;
  MaxSkip.Kind = StmtKind::If;
  MaxSkip.Cond = HighExpr::makeBinop(NdOp::INT_EQUAL, parameter(2),
                                     HighExpr::makeConst(0, 4));
