  MedVar Dest;
  Dest.Kind = MedVar::Stack;
  Dest.Id = 8;
  Dest.Size = 8;
  Dest.TheArch = Arch::X64;
  Dest.StackOff = 8;
  Taken.Dst = HighExpr::makeVar(Dest);
  Taken.Val = HighExpr::makeCall("CStringT_assign", 0x140002300,
                                 {parameter(1), parameter(0)});
  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = HighExpr::makeUnary(
      NdOp::BOOL_NOT,
      HighExpr::makeBinop(NdOp::INT_SLESSEQUAL, parameter(3),
                          HighExpr::makeConst(0, 4)));
  Guard.Body = {Taken};
  HighStmt Use;
  Use.Kind = StmtKind::Call;
  Use.CallExpr = HighExpr::makeCall("GetData", 0x140002400,
                                    {parameter(2), HighExpr::makeVar(Dest)});
  Func.Body = {Guard, Use};
  structureIfElse(Func, 8);
