      FunctionSym FS;
      FS.Name = "LookupTextW";
      FS.Addr = Addr;
      FS.ReturnType = NdType::makeVoid();
      FS.Params.emplace_back("result", NdType::makePtr());
      FS.Params.emplace_back("key", NdType::makePtr());
      FS.Params.emplace_back("args", NdType::makePtr(Arg));
