TEST(HighCPointerAddresses, NestedIfAndComposesKindGuard) {
  HighFunc Func;
  Func.Name = "nested_kind";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();

  HighStmt Display;
  Display.Kind = StmtKind::Call;
  Display.CallExpr = HighExpr::makeCall("GetDisplayName", 0x140002000, {parameter(0)});
  HighStmt Ctor;
  Ctor.Kind = StmtKind::Call;
  Ctor.CallExpr = HighExpr::makeCall("CStringT_ctor", 0x140002100, {parameter(1)});

  HighStmt Badge;
  Badge.Kind = StmtKind::IfElse;
  Badge.Cond = HighExpr::makeBinop(NdOp::INT_NOTEQUAL, parameter(2),
                                 HighExpr::makeConst(0, 8));
  Badge.Body = {Display};
  Badge.ElseBody = {Ctor};

  HighStmt Kind;
  Kind.Kind = StmtKind::If;
  Kind.Cond = HighExpr::makeBinop(NdOp::INT_NOTEQUAL, parameter(3),
                                  HighExpr::makeConst(0, 8));
  Kind.Body = {Badge};

  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = HighExpr::makeBinop(NdOp::INT_NOTEQUAL, parameter(0),
                                   HighExpr::makeConst(0, 8));
  Guard.Body = {Kind};
  Func.Body = {Guard};

  structureIfElse(Func, 8);
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("&&"), std::string::npos) << Source;
  EXPECT_NE(Source.find("GetDisplayName("), std::string::npos) << Source;
  EXPECT_NE(Source.find("CStringT_ctor("), std::string::npos) << Source;
  EXPECT_NE(Source.find("else"), std::string::npos) << Source;
  const auto CtorAt = Source.rfind("CStringT_ctor(");
  ASSERT_NE(CtorAt, std::string::npos) << Source;
  const auto Open = Source.find('(', CtorAt);
  const auto Close = Source.find(')', Open);
  ASSERT_NE(Open, std::string::npos) << Source;
  ASSERT_NE(Close, std::string::npos) << Source;
  const std::string Args = Source.substr(Open + 1, Close - Open - 1);
  EXPECT_EQ(std::count(Args.begin(), Args.end(), ','), 0) << Source;
  size_t IfCount = 0;
  for (size_t Pos = 0; (Pos = Source.find("if (", Pos)) != std::string::npos;
       Pos += 4)
    ++IfCount;
  EXPECT_LE(IfCount, 2u) << Source;
}

