TEST(HighCPointerAddresses, NestedIfFlattensImpliedGuardThroughNestedIf) {
  HighFunc Func;
  Func.Name = "implied_through_nested";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  auto Ptr = []() { return parameter(0); };
  auto NeZero = [](ExprPtr X) {
    return HighExpr::makeBinop(NdOp::INT_NOTEQUAL, std::move(X),
                               HighExpr::makeConst(0, 8));
  };
  auto Plus8 = [&]() {
    return HighExpr::makeBinop(NdOp::INT_ADD, Ptr(), HighExpr::makeConst(8, 8));
  };
  HighStmt Fetch;
  Fetch.Kind = StmtKind::Assign;
  MedVar Old;
  Old.Kind = MedVar::Temp;
  Old.Id = 94;
  Old.SSAVer = 7;
  Old.Size = 4;
  Old.TheArch = Arch::X64;
  Fetch.Dst = HighExpr::makeVar(Old, NdType::makeInt(4));
  Fetch.Val = HighExpr::makeCall("addref", 0x140002500, {Plus8()});
  HighStmt Bump;
  Bump.Kind = StmtKind::Store;
  Bump.StoreAddr = Plus8();
  Bump.StoreVal = HighExpr::makeConst(1, 4);
  HighStmt Release;
  Release.Kind = StmtKind::Call;
  Release.CallExpr = HighExpr::makeCall("dtor", 0x140002600, {Ptr()});
  HighStmt Inner;
  Inner.Kind = StmtKind::If;
  Inner.Cond = NeZero(Ptr());
  Inner.Body = {Release};
  HighStmt Last;
  Last.Kind = StmtKind::If;
  Last.Cond = HighExpr::makeBinop(NdOp::INT_EQUAL, HighExpr::makeVar(Old),
                                  HighExpr::makeConst(1, 4));
  Last.Body = {Bump, Inner};
  HighStmt Clear;
  Clear.Kind = StmtKind::Assign;
  Clear.Dst = Ptr();
  Clear.Val = HighExpr::makeConst(0, 8);
  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = NeZero(Ptr());
  Guard.Body = {Fetch, Last, Clear};
  Func.Body = {Guard};
  invertSkipGotos(Func);
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("addref("), std::string::npos) << Source;
  EXPECT_NE(Source.find("dtor("), std::string::npos) << Source;
  const auto BodyAt = Source.find("void implied_through_nested");
  ASSERT_NE(BodyAt, std::string::npos) << Source;
  size_t IfCount = 0;
  for (size_t Pos = BodyAt; (Pos = Source.find("if (", Pos)) != std::string::npos;
       Pos += 4)
    ++IfCount;
  EXPECT_EQ(IfCount, 2u) << Source;
  size_t PtrIfCount = 0;
  for (size_t Pos = BodyAt;
       (Pos = Source.find("if (arg0", Pos)) != std::string::npos; Pos += 8)
    ++PtrIfCount;
  EXPECT_EQ(PtrIfCount, 1u) << Source;
}

