  Skip.Kind = StmtKind::If;
  Skip.Cond = HighExpr::makeBinop(
      NdOp::BOOL_OR,
      HighExpr::makeBinop(NdOp::BOOL_OR, EqZero(parameter(0)), EqZero(Kind())),
      EqZero(parameter(1)));
  HighStmt ToCtor;
  ToCtor.Kind = StmtKind::Goto;
  ToCtor.GotoTarget = 0x140001457;
  Skip.Body = {ToCtor};

  HighStmt Display;
  Display.Kind = StmtKind::Call;
  Display.CallExpr =
      HighExpr::makeCall("GetDisplayName", 0x140002000, {parameter(1)});
  HighStmt ToJoin;
  ToJoin.Kind = StmtKind::Goto;
  ToJoin.GotoTarget = 0x14000146C;

  HighStmt ToLabel;
  ToLabel.Kind = StmtKind::Goto;
  ToLabel.GotoTarget = 0x140001509;
  HighStmt Outer;
  Outer.Kind = StmtKind::IfElse;
  Outer.Cond =
      HighExpr::makeBinop(NdOp::BOOL_AND, NeZero(parameter(0)), NeZero(Kind()));
  Outer.Body = {Skip, Display, ToJoin};
  Outer.ElseBody = {ToLabel};

  HighStmt Ctor;
  Ctor.Kind = StmtKind::Call;
  Ctor.Addr = 0x140001457;
  Ctor.CallExpr = HighExpr::makeCall("ctor", 0x140002100, {parameter(2)});
