  Use.Addr = 0x14000146C;
  Use.CallExpr = HighExpr::makeCall("use", 0x140002200, {parameter(2)});
  HighStmt Label;
  Label.Kind = StmtKind::Call;
  Label.Addr = 0x140001509;
  Label.CallExpr = HighExpr::makeCall("label", 0x140002300, {parameter(2)});

  Func.Body = {Outer, Ctor, Use, Label};
  invertSkipGotos(Func);
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("GetDisplayName("), std::string::npos) << Source;
