TEST(HighCPointerAddresses, SignedJleLengthPrintsGreaterThanZero) {
  HighFunc Func;
  Func.Name = "aux_len";
  Func.Entry = 0x140001000;
  Func.ReturnType = NdType::makeVoid();
  Func.Params = {{"Length", NdType::makeInt(8)}};
  MedVar Len;
  Len.Kind = MedVar::Param;
  Len.Id = 0;
  Len.Size = 8;
  Len.TheArch = Arch::X64;
  auto LenVar = HighExpr::makeVar(Len, NdType::makeInt(8));
  MedVar Len2 = Len;
  Len2.SSAVer = 1;
  auto LenVar2 = HighExpr::makeVar(Len2, NdType::makeInt(8));
  auto Masked = [&](ExprPtr V) {
    return HighExpr::makeBinop(NdOp::INT_OR, std::move(V),
                               HighExpr::makeConst(0, 8));
  };
  auto Jle = HighExpr::makeUnary(
      NdOp::BOOL_NOT,
      HighExpr::makeBinop(
          NdOp::BOOL_OR,
          HighExpr::makeBinop(NdOp::INT_EQUAL, Masked(LenVar),
                              HighExpr::makeConst(0, 4)),
          HighExpr::makeBinop(
              NdOp::INT_NOTEQUAL,
              HighExpr::makeBinop(NdOp::INT_SLESS, Masked(LenVar2),
                                  HighExpr::makeConst(0, 4)),
              HighExpr::makeConst(0, 4))));
  HighStmt Guard;
  Guard.Kind = StmtKind::If;
  Guard.Cond = std::move(Jle);
  HighStmt Assign;
  Assign.Kind = StmtKind::Call;
  Assign.CallExpr =
      HighExpr::makeCall("CStringT_assign", 0x140002000, {parameter(0)});
  Guard.Body = {Assign};
  Func.Body = {Guard};
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("CStringT_assign("), std::string::npos) << Source;
  EXPECT_NE(Source.find("> 0"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("== 0 ||"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("< (int32_t)0 != 0"), std::string::npos) << Source;
}

