  ToSkip.GotoTarget = 0x140001157;
  HighStmt Branch;
  Branch.Kind = StmtKind::If;
  Branch.Cond = HighExpr::makeBinop(NdOp::INT_NOTEQUAL, parameter(0),
                                    HighExpr::makeConst(0, 8));
  Branch.Body = {ToSkip};

  HighStmt Taken;
  Taken.Kind = StmtKind::Call;
  Taken.CallExpr = HighExpr::makeCall("taken", 0x140002000, {parameter(0)});

