  Func.Params = {{"arg0", NdType::makePtr()}};

  MedVar ZeroVar;
  ZeroVar.Kind = MedVar::Temp;
  ZeroVar.Id = 5;
  ZeroVar.Size = 4;
  ZeroVar.TheArch = Arch::X64;
