  Zero.Kind = StmtKind::Assign;
  Zero.Dst = HighExpr::makeVar(ZeroVar);
  Zero.Val = HighExpr::makeConst(0, 4);

  HighStmt Then;
  Then.Kind = StmtKind::Assign;
  Then.Dst = HighExpr::makeVar(Key);
  Then.Val = HighExpr::makeConst(42, 4);
  Then.IsPhiCopy = true;
  HighStmt Jump;
  Jump.Kind = StmtKind::Goto;
  Jump.GotoTarget = 0x140001086;
  HighStmt If;
  If.Kind = StmtKind::IfElse;
