TEST(LLVMCPointerAddresses, NestedPtrBoxInnerRecordFieldPrintsArrow) {
  class RecordDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140012040)
        return std::nullopt;
      auto Basic = NdType::makeNamedRecord("RecordBasic", 112);
      Basic->FieldDisplayNames = {"id"};
      Basic->FieldDisplayOffsets = {0};
      Basic->FieldDisplayTypes = {NdType::makeInt(4, false)};
      auto Data = NdType::makeNamedRecord("CRecordData", 1792);
      Data->FieldDisplayNames = {"m_core"};
      Data->FieldDisplayOffsets = {152};
      Data->FieldDisplayTypes = {Basic};
      auto Holder = NdType::makeNamedRecord("PtrBox", 16);
      Holder->FieldDisplayNames = {"p"};
      Holder->FieldDisplayOffsets = {8};
      Holder->FieldDisplayTypes = {NdType::makePtr(Data)};
      auto Record = NdType::makeNamedRecord("CRecord", 512);
      Record->FieldDisplayNames = {"m_pRecordData"};
      Record->FieldDisplayOffsets = {72};
      Record->FieldDisplayTypes = {Holder};
      FunctionSym FS;
      FS.Name = "CRecord_RecordId";
      FS.Addr = Addr;
      FS.Params = {{"this", NdType::makePtr(Record)}};
      FS.ReturnType = NdType::makeInt(4, false);
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-nested-tptr", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I32 = llvm::Type::getInt32Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::getUnqual(I8);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(I32, {Ptr}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "CRecord_RecordId", Module);
  rewrite_source::setOriginalVA(*Function, 0x140012040);
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  llvm::Value *AddrSlot = Builder.CreateAlloca(I64, nullptr, "t0");
  llvm::Value *ValSlot = Builder.CreateAlloca(I64, nullptr, "t76");
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), AddrSlot);
  llvm::Value *ThisI =
      Builder.CreatePtrToInt(Function->getArg(0), I64, "this_i");
  Builder.CreateStore(
      Builder.CreateAdd(ThisI, llvm::ConstantInt::get(I64, 80), "add"),
      AddrSlot);
  llvm::Value *PtrV = Builder.CreateLoad(
      I64, Builder.CreateIntToPtr(Builder.CreateLoad(I64, AddrSlot), Ptr),
      "p");
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), ValSlot);
  Builder.CreateStore(PtrV, ValSlot);
  llvm::Value *Inner = Builder.CreateAdd(
      Builder.CreateLoad(I64, ValSlot, "p_v"),
      llvm::ConstantInt::get(I64, 152), "id_addr");
  llvm::Value *Ld =
      Builder.CreateLoad(I32, Builder.CreateIntToPtr(Inner, Ptr), "id");
  Builder.CreateRet(Ld);

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr,
                                  Function));
  OS.flush();
  EXPECT_NE(Source.find("this->m_pRecordData.p->m_core.id"), std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("+ 152"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("*(uint32_t*)"), std::string::npos) << Source;
}

