TEST(LLVMCPointerAddresses, ThisFieldAddressHomePrintsNestedMember) {
  class BadgeDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140016d30)
        return std::nullopt;
      auto Badge = NdType::makeNamedRecord("CBadgeBase", 128);
      auto Holder = NdType::makeNamedRecord("PtrBox", 8);
      Holder->FieldDisplayNames = {"p"};
      Holder->FieldDisplayOffsets = {0};
      Holder->FieldDisplayTypes = {NdType::makePtr(Badge)};
      auto Record = NdType::makeNamedRecord("CRecordBadge", 264);
      Record->FieldDisplayNames = {"m_pBadge"};
      Record->FieldDisplayOffsets = {32};
      Record->FieldDisplayTypes = {Holder};
      FunctionSym FS;
      FS.Name = "CRecordBadge_GetDisplayName";
      FS.Addr = Addr;
      FS.Params = {{"this", NdType::makePtr(Record)}};
      FS.ReturnType = NdType::makePtr(NdType::makeNamedRecord("CStringT", 8));
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-badge-field-home", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::getUnqual(I8);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(I64, {Ptr, I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "CRecordBadge_GetDisplayName",
      Module);
  rewrite_source::setOriginalVA(*Function, 0x140016d30);
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  llvm::Value *Slot = Builder.CreateAlloca(I64, nullptr, "t7");
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), Slot);
  llvm::Value *ThisI =
      Builder.CreatePtrToInt(Function->getArg(0), I64, "this_i");
  llvm::Value *Add =
      Builder.CreateAdd(ThisI, llvm::ConstantInt::get(I64, 32), "add");
  Builder.CreateStore(Add, Slot);
  llvm::Value *Addr = Builder.CreateLoad(I64, Slot, "t7_v");
  llvm::Value *Ld = Builder.CreateLoad(
      I64, Builder.CreateIntToPtr(Addr, Ptr, "memptr"), "ld");
  llvm::BasicBlock *NullBlk =
      llvm::BasicBlock::Create(Context, "isnull", Function);
  llvm::BasicBlock *CallBlk =
      llvm::BasicBlock::Create(Context, "vcall", Function);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(Ld, llvm::ConstantInt::get(I64, 0)), CallBlk,
      NullBlk);
  Builder.SetInsertPoint(NullBlk);
  Builder.CreateRet(Function->getArg(1));
  Builder.SetInsertPoint(CallBlk);
  Builder.CreateRet(Function->getArg(1));

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr,
                                  Function));
  OS.flush();
  EXPECT_NE(Source.find("this->m_pBadge.p"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("*(uint64_t*)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("+ 32"), std::string::npos) << Source;
}

TEST(LLVMCPointerAddresses, IndirectCallPrintsLoadedCalleePlusOffset) {
  class BadgeDbg : public NullDebugContext {
  public:
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      if (Addr != 0x140016d30)
        return std::nullopt;
      auto Badge = NdType::makeNamedRecord("CBadgeBase", 128);
      auto Holder = NdType::makeNamedRecord("PtrBox", 8);
      Holder->FieldDisplayNames = {"p"};
      Holder->FieldDisplayOffsets = {0};
      Holder->FieldDisplayTypes = {NdType::makePtr(Badge)};
      auto Record = NdType::makeNamedRecord("CRecordBadge", 264);
      Record->FieldDisplayNames = {"m_pBadge"};
      Record->FieldDisplayOffsets = {32};
      Record->FieldDisplayTypes = {Holder};
      FunctionSym FS;
      FS.Name = "CRecordBadge_GetDisplayName";
      FS.Addr = Addr;
      FS.Params = {{"this", NdType::makePtr(Record)}};
      FS.ReturnType = NdType::makePtr(NdType::makeNamedRecord("CStringT", 8));
      return FS;
    }
    bool hasInfo() const override { return true; }
  } Dbg;

  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-badge-vcall", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::getUnqual(I8);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(I64, {Ptr, I64}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "CRecordBadge_GetDisplayName",
      Module);
  rewrite_source::setOriginalVA(*Function, 0x140016d30);
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  llvm::Value *AddrSlot = Builder.CreateAlloca(I64, nullptr, "t7");
  llvm::Value *BadgeSlot = Builder.CreateAlloca(I64, nullptr, "t8");
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), AddrSlot);
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), BadgeSlot);
  llvm::Value *ThisI =
      Builder.CreatePtrToInt(Function->getArg(0), I64, "this_i");
  llvm::Value *Add =
      Builder.CreateAdd(ThisI, llvm::ConstantInt::get(I64, 32), "add");
  Builder.CreateStore(Add, AddrSlot);
  llvm::Value *FieldAddr = Builder.CreateLoad(I64, AddrSlot, "t7_v");
  llvm::Value *Badge = Builder.CreateLoad(
      I64, Builder.CreateIntToPtr(FieldAddr, Ptr, "memptr"), "ld");
  Builder.CreateStore(Badge, BadgeSlot);
  llvm::BasicBlock *NullBlk =
      llvm::BasicBlock::Create(Context, "isnull", Function);
  llvm::BasicBlock *CallBlk =
      llvm::BasicBlock::Create(Context, "vcall", Function);
  Builder.CreateCondBr(
      Builder.CreateICmpNE(Badge, llvm::ConstantInt::get(I64, 0)), CallBlk,
      NullBlk);
  Builder.SetInsertPoint(NullBlk);
  Builder.CreateRet(Function->getArg(1));
  Builder.SetInsertPoint(CallBlk);
  llvm::Value *BadgeV = Builder.CreateLoad(I64, BadgeSlot, "t8_v");
  llvm::Value *Vtbl = Builder.CreateLoad(
      I64, Builder.CreateIntToPtr(BadgeV, Ptr, "vtblptr"), "vtbl");
  llvm::Value *SlotAddr =
      Builder.CreateAdd(Vtbl, llvm::ConstantInt::get(I64, 88), "slot");
  llvm::Value *FnI = Builder.CreateLoad(
      I64, Builder.CreateIntToPtr(SlotAddr, Ptr, "slotptr"), "fn");
  llvm::Value *Callee = Builder.CreateIntToPtr(FnI, Ptr, "fp");
  llvm::FunctionType *CallTy =
      llvm::FunctionType::get(I64, {I64, I64}, false);
  Builder.CreateCall(CallTy, Callee, {BadgeV, Function->getArg(1)});
  Builder.CreateRet(Function->getArg(1));

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options, &Dbg, nullptr,
                                  Function));
  OS.flush();
  EXPECT_NE(Source.find("(*(void **)((uintptr_t)(*(void **)("),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("CStringT* CRecordBadge_GetDisplayName(CRecordBadge* this, "
                        "CStringT* result)"),
            std::string::npos)
      << Source;
  EXPECT_NE(Source.find("this->m_pBadge.p"), std::string::npos) << Source;
  EXPECT_NE(Source.find(" + 88))"), std::string::npos) << Source;
  EXPECT_NE(Source.find("(this->m_pBadge.p, result)"), std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("((void*)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("*(uint64_t*)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("uint64_t arg1"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("__try"), std::string::npos) << Source;
}

