TEST(LLVMCPointerAddresses, SyntheticFrameRbxSpillIsHidden) {
  llvm::LLVMContext Context;
  llvm::Module Module("llvm-c-frame-spill", Context);
  llvm::Type *I8 = llvm::Type::getInt8Ty(Context);
  llvm::Type *I64 = llvm::Type::getInt64Ty(Context);
  llvm::Type *Ptr = llvm::PointerType::getUnqual(I8);
  llvm::FunctionType *FnTy = llvm::FunctionType::get(I64, {Ptr}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "spill_only", Module);
  llvm::IRBuilder<> Builder(
      llvm::BasicBlock::Create(Context, "entry", Function));
  llvm::Value *RBX = Builder.CreateAlloca(I64, nullptr, "RBX");
  llvm::Value *RSP = Builder.CreateAlloca(I64, nullptr, "RSP");
  llvm::Value *RSP1 = Builder.CreateAlloca(I64, nullptr, "RSP.1");
  llvm::Value *Frame = Builder.CreateAlloca(
      llvm::ArrayType::get(I8, 168), nullptr, "frame");
  Builder.CreateStore(llvm::ConstantInt::get(I64, 0), RBX);
  llvm::Value *FrameEnd = Builder.CreateInBoundsGEP(
      I8, Frame, llvm::ConstantInt::get(I64, 56), "frame_end");
  Builder.CreateStore(Builder.CreatePtrToInt(FrameEnd, I64), RSP);
  llvm::Value *RbxV = Builder.CreateLoad(I64, RBX, "RBX_v");
  Builder.CreateStore(RbxV, RBX);
  llvm::Value *RspV = Builder.CreateLoad(I64, RSP, "RSP_v");
  llvm::Value *Sub =
      Builder.CreateSub(RspV, llvm::ConstantInt::get(I64, 8), "sub");
  Builder.CreateStore(Sub, RSP1);
  llvm::Value *RbxV1 = Builder.CreateLoad(I64, RBX, "RBX_v1");
  llvm::Value *Mem = Builder.CreateIntToPtr(Builder.CreateLoad(I64, RSP1), Ptr);
  Builder.CreateStore(RbxV1, Mem);
  Builder.CreateRet(Function->getArg(0));

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions Options;
  Options.EmitIncludes = false;
  ASSERT_TRUE(LLVMCEmitter().emit(Module, OS, Options, nullptr, nullptr,
                                  Function));
  OS.flush();
  EXPECT_EQ(Source.find("&frame"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("*(uint64_t*)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("RBX"), std::string::npos) << Source;
  EXPECT_NE(Source.find("return"), std::string::npos) << Source;
}

