  llvm::FunctionType *FnTy = llvm::FunctionType::get(
      llvm::Type::getVoidTy(Context), {Ptr}, false);
  llvm::Function *Function = llvm::Function::Create(
      FnTy, llvm::GlobalValue::ExternalLinkage, "taken_values", Module);
