  llvm::Value *End = Builder.CreateInBoundsGEP(
      I8, Frame, llvm::ConstantInt::get(I64, 56), "frame_end");
  llvm::Value *Rsp = Builder.CreatePtrToInt(End, I64, "rsp_init");
  llvm::Value *PackSlot =
      Builder.CreateSub(Rsp, llvm::ConstantInt::get(I64, 24), "pack");
