  Builder.CreateStore(Home, Vals);
  Builder.CreateCall(Common, {Function->getArg(0),
                              llvm::ConstantPointerNull::get(
                                  llvm::cast<llvm::PointerType>(Ptr)),
                              Pack});
  Builder.CreateRetVoid();

  std::string Source;
