TEST(LLVMCPointerAddresses, CorpusFuncLoadGsCookieDoesNotLoadNull) {
  if (NEVERD_BINARY_CORPUS_ROOT[0] == '\0')
    GTEST_SKIP() << "windows-eh corpus root is not configured";
  const auto Path = gsSehProbePath();
  if (!std::filesystem::exists(Path))
    GTEST_SKIP() << Path.string() << " is missing";

  BinaryLoadOptions Discover;
  Discover.OnlyFunctionEntries.insert(1);
  auto DiscoverImg = loadBinary(Path, Discover);
  ASSERT_TRUE(static_cast<bool>(DiscoverImg))
      << llvm::toString(DiscoverImg.takeError());
  const uint8_t RolRcx16[] = {0x48, 0xc1, 0xc1, 0x10};
  const va_t Rol = findExecutableBytes(*DiscoverImg, RolRcx16);
  ASSERT_NE(Rol, 0u);
  const va_t Entry = pdataEntryContaining(*DiscoverImg, Rol);
  ASSERT_NE(Entry, 0u);

  BinaryLoadOptions FuncOpts;
  FuncOpts.OnlyFunctionEntries.insert(Entry);
  auto Img = loadBinary(Path, FuncOpts);
  ASSERT_TRUE(static_cast<bool>(Img)) << llvm::toString(Img.takeError());
  const std::string Source = llvmcOnlyFunction(std::move(*Img), Entry);
  ASSERT_FALSE(Source.empty()) << Source;
  EXPECT_EQ(Source.find("*(uint64_t*)0"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("*(uint32_t*)0"), std::string::npos) << Source;
  EXPECT_NE(Source.find("g_"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, ReturnViewChainAroundAddKeepsOneCast) {
  HighFunc Func;
  Func.Name = "ret_add";
  Func.ReturnType = NdType::makeInt(4, true);
  Func.Params = {{"arg0", NdType::makeInt(4, false)}};
  auto Add = HighExpr::makeBinop(NdOp::INT_ADD,
                                 parameter(0, NdType::makeInt(4, false)),
                                 HighExpr::makeConst(1, 4));
  Add->Type = NdType::makeInt(4, false);
  Add->Operands[0]->Type = NdType::makeInt(4, false);
  Add->Operands[1]->Type = NdType::makeInt(4, false);
  auto Wide = HighExpr::makeUnary(NdOp::INT_ZEXT, Add);
  Wide->Type = NdType::makeInt(8, false);
  auto Outer = std::make_shared<HighExpr>();
  Outer->Kind = ExprKind::Cast;
  Outer->Type = Outer->CastTo = NdType::makeInt(8, false);
  Outer->Operands = {Wide};
  auto Narrow = std::make_shared<HighExpr>();
  Narrow->Kind = ExprKind::Cast;
  Narrow->Type = Narrow->CastTo = NdType::makeInt(4, true);
  Narrow->Operands = {Outer};
  returnValue(Func, Narrow);
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("return (int32_t)"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("(int64_t)"), std::string::npos) << Source;
  EXPECT_NE(Source.find("+ "), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, ReturnZextFromNarrowerKeepsSourceWidth) {
  HighFunc Func;
  Func.Name = "ret_zext16";
  Func.ReturnType = NdType::makeInt(4, true);
  Func.Params = {{"arg0", NdType::makeInt(2, true)}};
  auto Wide = HighExpr::makeUnary(NdOp::INT_ZEXT,
                                 parameter(0, NdType::makeInt(2, true)));
  Wide->Type = NdType::makeInt(8, false);
  Wide->Operands[0]->Type = NdType::makeInt(2, true);
  returnValue(Func, Wide);
  const std::string Source = emitFunctions({Func});
  EXPECT_NE(Source.find("uint16_t"), std::string::npos) << Source;
}

