TEST(HighCPointerAddresses, X86ExceptEbpStoreUsesTryResultSlot) {
  // Try body names Result as (ESP-4)-28. The outlined handler writes
  // [ebp-28] with incoming EBP, the same established frame, then the join
  // copies that EBP into the post-try load base.
  const auto I32 = NdType::makeInt(4);
  const auto I32U = NdType::makeInt(4, false);
  HighFunc Func;
  Func.Name = "x86_except_slot";
  Func.FrameSize = 64;
  Func.ReturnType = I32;
  Func.ExceptionMetadata = ExceptionFunction{};

  MedVar ESP;
  ESP.Kind = MedVar::Reg;
  ESP.Size = 4;
  ESP.TheArch = Arch::X86;
  ESP.RegOff = getTargetRegInfo(Arch::X86).StackPointer;
  MedVar EBP;
  EBP.Kind = MedVar::Reg;
  EBP.Size = 4;
  EBP.TheArch = Arch::X86;
  EBP.RegOff = getTargetRegInfo(Arch::X86).FramePointer;
  MedVar V0;
  V0.Kind = MedVar::Temp;
  V0.Id = 0;
  V0.Size = 4;
  V0.TheArch = Arch::X86;
  MedVar V10;
  V10.Kind = MedVar::Temp;
  V10.Id = 10;
  V10.Size = 4;
  V10.TheArch = Arch::X86;

  HighStmt SetFrame;
  SetFrame.Kind = StmtKind::Assign;
  SetFrame.Dst = HighExpr::makeVar(V0, I32U);
  SetFrame.Val = HighExpr::makeBinop(NdOp::INT_SUB, HighExpr::makeVar(ESP, I32U),
                                     HighExpr::makeConst(4, 4));
  Func.Body.push_back(std::move(SetFrame));

  HighStmt Init;
  Init.Kind = StmtKind::Store;
  Init.StoreAddr = HighExpr::makeBinop(NdOp::INT_SUB, HighExpr::makeVar(V0, I32U),
                                       HighExpr::makeConst(28, 4));
  Init.StoreVal = HighExpr::makeConst(0, 4);
  Func.Body.push_back(std::move(Init));

  HighStmt Try;
  Try.Kind = StmtKind::SEHTry;
  Try.EHIsReducible = true;
  HighStmt TryStore;
  TryStore.Kind = StmtKind::Store;
  TryStore.StoreAddr = HighExpr::makeBinop(
      NdOp::INT_SUB, HighExpr::makeVar(V0, I32U), HighExpr::makeConst(28, 4));
  TryStore.StoreVal = HighExpr::makeConst(static_cast<uint64_t>(-100), 4);
  Try.Body.push_back(std::move(TryStore));
  HighStmt TryJoin;
  TryJoin.Kind = StmtKind::Assign;
  TryJoin.Dst = HighExpr::makeVar(V10, I32U);
  TryJoin.Val = HighExpr::makeVar(V0, I32U);
  Try.Body.push_back(std::move(TryJoin));

  HighEHClause Except;
  Except.Kind = HighEHClauseKind::SEHExcept;
  Except.HandlerVA = 0x4010AA;
  Try.EHClauses.push_back(std::move(Except));
  HighStmt ExceptStore;
  ExceptStore.Kind = StmtKind::Store;
  ExceptStore.StoreAddr = HighExpr::makeBinop(
      NdOp::INT_SUB, HighExpr::makeVar(EBP, I32U), HighExpr::makeConst(28, 4));
  ExceptStore.StoreVal = HighExpr::makeConst(41, 4);
  HighStmt ExceptJoin;
  ExceptJoin.Kind = StmtKind::Assign;
  ExceptJoin.Dst = HighExpr::makeVar(V10, I32U);
  ExceptJoin.Val = HighExpr::makeVar(EBP, I32U);
  Try.EHClauseBodies.emplace_back();
  Try.EHClauseBodies.back().push_back(std::move(ExceptStore));
  Try.EHClauseBodies.back().push_back(std::move(ExceptJoin));
  Func.Body.push_back(std::move(Try));

  HighStmt Ret;
  Ret.Kind = StmtKind::Return;
  Ret.RetVal = HighExpr::makeLoad(
      HighExpr::makeBinop(NdOp::INT_SUB, HighExpr::makeVar(V10, I32U),
                          HighExpr::makeConst(28, 4)),
      I32);
  Func.Body.push_back(std::move(Ret));

  const std::string Source = emitFunctions({Func}, Arch::X86);
  const std::string TrySlot = assignedNameBefore(Source, "= 0xFFFFFF9C");
  const std::string ExceptSlot = assignedNameBefore(Source, "= 41");
  ASSERT_FALSE(TrySlot.empty()) << Source;
  EXPECT_EQ(TrySlot, ExceptSlot) << Source;
  EXPECT_NE(Source.find("return " + TrySlot), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, FuncLoadUsesDebugFunctionNameOnSynthesizedEntry) {
  if (NEVERD_BINARY_CORPUS_ROOT[0] == '\0')
    GTEST_SKIP() << "windows-eh corpus root is not configured";
  const auto Path = std::filesystem::path(NEVERD_BINARY_CORPUS_ROOT) /
                    "corpus/windows-eh/msvc/x86_64/fh4/no-gs/o0/abi-probe/"
                    "seh_probe-msvc-x86_64-fh4-no-gs-o0.exe";
  if (!std::filesystem::exists(Path))
    GTEST_SKIP() << Path.string() << " is missing";

  constexpr va_t Entry = 0x140001050;
  constexpr va_t Filter = 0x1400024E0;
  class NamedProbe : public NullDebugContext {
  public:
    bool hasInfo() const override { return true; }
    std::optional<FunctionSym> resolveFunction(va_t Addr) const override {
      FunctionSym Sym;
      Sym.Addr = Addr;
      if (Addr == Entry)
        Sym.Name = "probe_plain_seh";
      else if (Addr == Filter)
        Sym.Name = "probe_filter";
      else
        return std::nullopt;
      return Sym;
    }
  } Dbg;

  BinaryLoadOptions FuncOpts;
  FuncOpts.OnlyFunctionEntries.insert(Entry);
  auto Img = loadBinary(Path, FuncOpts);
  ASSERT_TRUE(static_cast<bool>(Img)) << llvm::toString(Img.takeError());
  llvm::LLVMContext Ctx;
  PipelineOptions Opts;
  Opts.EmitDumpOutput = false;
  Opts.OnlyFunctionEntries.insert(Entry);
  auto Result = Pipeline().run(*Img, Ctx, Opts, &Dbg);
  ASSERT_TRUE(Result.Success) << Result.Error;
  const HighFunc *Func = nullptr;
  for (const HighFunc &HF : Result.HighFuncs)
    if (HF.Entry == Entry)
      Func = &HF;
  ASSERT_NE(Func, nullptr);
  EXPECT_EQ(Func->Name, "probe_plain_seh");

  std::string Source;
  llvm::raw_string_ostream OS(Source);
  CEmitterOptions COpts;
  COpts.EmitIncludes = false;
  COpts.TheArch = Img->Arch;
  COpts.Format = Img->Format;
  COpts.Image = &*Img;
  ASSERT_TRUE(HighCEmitter().emit(Result.HighFuncs, OS, COpts, &Dbg));
  OS.flush();
  EXPECT_NE(Source.find("probe_plain_seh"), std::string::npos) << Source;
  EXPECT_NE(Source.find("probe_filter"), std::string::npos) << Source;
  EXPECT_EQ(Source.find("sub_140001050"), std::string::npos) << Source;
}

TEST(HighCPointerAddresses, CorpusFuncLoadX86SehProbeExceptAssignsResult) {
  // MSVC x86 `_except_handler3` plants the outlined except body in-function.
  // HighC must recover `Result = 41` on the same slot as `Result = -100`,
  // not `goto` the handler VA.
  if (NEVERD_BINARY_CORPUS_ROOT[0] == '\0')
    GTEST_SKIP() << "windows-eh corpus root is not configured";
  const auto Path = std::filesystem::path(NEVERD_BINARY_CORPUS_ROOT) /
                    "corpus/windows-eh/msvc/x86/native/no-gs/o0/abi-probe/"
                    "seh_probe-msvc-x86-native-no-gs-o0.exe";
  if (!std::filesystem::exists(Path))
    GTEST_SKIP() << Path.string() << " is missing";

  constexpr va_t Entry = 0x401040;
  BinaryLoadOptions FuncOpts;
  FuncOpts.OnlyFunctionEntries.insert(Entry);
  auto Img = loadBinary(Path, FuncOpts);
  ASSERT_TRUE(static_cast<bool>(Img)) << llvm::toString(Img.takeError());
  llvm::LLVMContext Ctx;
  PipelineOptions Opts;
  Opts.EmitDumpOutput = false;
  Opts.OnlyFunctionEntries.insert(Entry);
  auto Result = Pipeline().run(*Img, Ctx, Opts);
  ASSERT_TRUE(Result.Success) << Result.Error;
  const std::string Blocks = dumpMedBlockRanges(Result.MedFuncs);
  std::string HighDump;
  llvm::raw_string_ostream HighOS(HighDump);
  Pipeline::dumpHighIR(Result.HighFuncs, HighOS);
  HighOS.flush();
  const std::string Source = highcOnlyFunction(std::move(*Img), Entry);
  ASSERT_FALSE(Source.empty()) << Source << "\n" << Blocks << HighDump;
  EXPECT_NE(Source.find("__except"), std::string::npos)
      << Source << "\n"
      << Blocks << HighDump;
  EXPECT_EQ(Source.find("goto L_"), std::string::npos)
      << Source << "\n"
      << Blocks << HighDump;
  const auto Stores = portableStoreCalls(Source);
  const auto Normal = llvm::find_if(Stores, [](const PortableStoreCall &S) {
    return S.Type == "uint32_t" && S.Value == "0xFFFFFF9C";
  });
  const auto Handler = llvm::find_if(Stores, [](const PortableStoreCall &S) {
    return S.Type == "uint32_t" && S.Value == "41";
  });
  ASSERT_NE(Normal, Stores.end()) << Source << "\n" << Blocks << HighDump;
  ASSERT_NE(Handler, Stores.end()) << Source << "\n" << Blocks << HighDump;
  const std::string EntryFrame =
      "(int32_t)(uint32_t)((uint32_t)(frame_base) - (uint32_t)(4))";
  const std::string NormalFrame = assignedNameBefore(Source, "= " + EntryFrame);
  ASSERT_FALSE(NormalFrame.empty()) << Source;
  EXPECT_EQ(Normal->Address,
            "(uintptr_t)((uintptr_t)(" + NormalFrame + ") - 28)")
      << Source;
  EXPECT_EQ(Handler->Address, "(uintptr_t)((uintptr_t)((frame_base - 4)) - 28)")
      << Source;
  const size_t ExceptAt = Source.find("} __except (");
  ASSERT_NE(ExceptAt, std::string::npos) << Source;
  const std::string HandlerText = Source.substr(ExceptAt);
  const std::string JoinFrame =
      assignedNameBefore(HandlerText, "= (frame_base - 4);");
  ASSERT_FALSE(JoinFrame.empty()) << Source;
  const size_t NormalCopyAt = Source.find(JoinFrame + " = " + EntryFrame + ";");
  ASSERT_NE(NormalCopyAt, std::string::npos) << Source;
  EXPECT_LT(NormalCopyAt, ExceptAt) << Source;
  const std::string JoinedLoad =
      "neverd_mem_load_0((uintptr_t)((uintptr_t)(" + JoinFrame + ") - 28))";
  EXPECT_NE(HandlerText.find("g_4040C8 = " + JoinedLoad + ";"),
            std::string::npos)
      << Source;
  EXPECT_NE(
      sourceLineContaining(HandlerText, "return (int32_t)").find(JoinedLoad),
      std::string_view::npos)
      << Source;
  EXPECT_EQ(Source.find("unknown register"), std::string::npos) << Source;
  EXPECT_EQ(Source.find(JoinFrame + " = 0;"), std::string::npos) << Source;
  // The retained SSA copy of the exception code must reach the call unchanged.
  const std::string Code = assignedNameBefore(Source, "= 0xE0421001;");
  ASSERT_FALSE(Code.empty()) << Source;
  EXPECT_NE(Source.find("RaiseException(" + Code + ", 0, 0, 0)"),
            std::string::npos)
      << Source;
  EXPECT_EQ(Source.find("var_m14"), std::string::npos) << Source;
}

